/// Section-13 globals initialized by `FUN_0044EB40` and consumed by common
/// environment callback `FUN_0044EC60`.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub(crate) struct CommonEnvironmentPhysics {
    pub(crate) runtime_wind_mode: u32,
    pub(crate) drag_strength: u32,
    pub(crate) configured_wind_raw: [i16; 3],
    pub(crate) current_wind_raw: [i16; 3],
    pub(crate) maximum_wind_height_raw: i32,
    pub(crate) wind_above_sea: bool,
    pub(crate) waves_enabled: bool,
}

/// Per-frame inputs consumed by `FUN_0040E100`'s common underwater branch.
#[derive(Debug, Clone, Copy)]
pub(crate) struct CommonUnderwaterFrame {
    pub(crate) effective_environment_flags: u32,
    pub(crate) water_response_enabled: bool,
    pub(crate) position_y_raw: i16,
    pub(crate) solid_or_sea_y_raw: i16,
    pub(crate) self_mass_raw: u16,
    pub(crate) attached_cargo_mass: u32,
}

impl CommonEnvironmentPhysics {
    pub(crate) fn from_level(level: &LevelDescriptor) -> Self {
        let configured_vector_raw =
            [0x9c, 0xa0, 0xa4].map(|offset| level.raw_u32(offset).unwrap_or(0) as u16 as i16);
        // FUN_0044EB40 forces both height and mode to zero when the configured
        // vector is zero, even if the descriptor authored another mode.
        let runtime_wind_mode = if configured_vector_raw == [0; 3] {
            0
        } else {
            level.raw_u32(0x90).unwrap_or(0)
        };
        Self {
            runtime_wind_mode,
            drag_strength: level.raw_u32(0x94).unwrap_or(0),
            configured_wind_raw: configured_vector_raw,
            current_wind_raw: configured_vector_raw,
            maximum_wind_height_raw: if configured_vector_raw == [0; 3] {
                0
            } else {
                level.raw_u32(0x98).unwrap_or(0) as i32
            },
            wind_above_sea: level.raw_u32(0x80).unwrap_or(0) != 0,
            waves_enabled: level.raw_u32(0x84).unwrap_or(0) != 0,
        }
    }
}

