#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Type93LifecyclePurpose {
    PlayerCargoDrop,
    Type17MissingRelation {
        type_default_state_flags_at_0xc0: u32,
    },
    FactoryConvertedOutput {
        type_default_state_flags_at_0xc0: u32,
    },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Type93UpdatePhase {
    PlayerCargoDrop,
    LateTailMaterialiser,
}

impl Type93UpdatePhase {
    const fn includes(self, purpose: Type93LifecyclePurpose) -> bool {
        matches!(
            (self, purpose),
            (
                Self::PlayerCargoDrop,
                Type93LifecyclePurpose::PlayerCargoDrop
            ) | (
                Self::LateTailMaterialiser,
                Type93LifecyclePurpose::PlayerCargoDrop
            ) | (
                Self::LateTailMaterialiser,
                Type93LifecyclePurpose::Type17MissingRelation { .. }
            ) | (
                Self::LateTailMaterialiser,
                Type93LifecyclePurpose::FactoryConvertedOutput { .. }
            )
        )
    }
}

/// Allocation provenance for one world-style-selected worker emitted by a
/// Working Factory phase-2 transaction.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FactoryConvertedOutputBirthProvenance {
    entity_id: u32,
    source_factory: FactoryProductionEntityVersion,
    spawn_request: FactoryEntitySpawnRequest,
    selector_rng_word: u16,
    constructor_rng_words: Vec<u16>,
    selected_behavior_choice_index: usize,
    selected_behavior_class_id: u8,
}

impl FactoryConvertedOutputBirthProvenance {
    pub const fn entity_id(&self) -> u32 {
        self.entity_id
    }

    pub const fn source_factory(&self) -> FactoryProductionEntityVersion {
        self.source_factory
    }

    pub const fn spawn_request(&self) -> FactoryEntitySpawnRequest {
        self.spawn_request
    }

    pub const fn selector_rng_word(&self) -> u16 {
        self.selector_rng_word
    }

    pub fn constructor_rng_words(&self) -> &[u16] {
        &self.constructor_rng_words
    }

    pub const fn selected_behavior_choice_index(&self) -> usize {
        self.selected_behavior_choice_index
    }

    pub const fn selected_behavior_class_id(&self) -> u8 {
        self.selected_behavior_class_id
    }
}

/// Allocation-owned proof for the Type-93 half of one Working Factory
/// conversion. Live callers identify the proxy through its linear
/// [`FactorySpawnedEntity`] lease; this private sidecar prevents an arbitrary
/// unlinked Type-93 allocation from entering the materialiser/output attach
/// seam.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct FactoryOutputMaterialiserBirthProvenance {
    entity_id: u32,
    construction: Type93MaterialiserConstruction,
    source_factory: FactoryProductionEntityVersion,
    spawn_request: FactoryEntitySpawnRequest,
    selector_rng_word: u16,
}

/// Proof is minted only after the shared canonical Type93 constructor has
/// published its actual allocation. Geometry fixtures explicitly lack it.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Type93MaterialiserConstruction {
    Native(MainBaseAbortActorLease),
    AttachmentProjection,
}

#[derive(Debug, Clone, Copy)]
struct Type93MaterialiserSpawn {
    entity_id: u32,
    construction: Type93MaterialiserConstruction,
}

#[derive(Debug, Clone, Copy)]
struct CargoDropProxy {
    proxy_id: u32,
    cargo_id: u32,
    construction: Type93MaterialiserConstruction,
    purpose: Type93LifecyclePurpose,
    /// Host projection of the Materialiser's Primary callback task. Class-2
    /// death clears that task but deliberately leaves Sub-J custody intact for
    /// the later component destructor.
    task_active: bool,
    /// Type-93 component's comparison position. It is initialized before
    /// FUN_00408F00 raises the proxy by one raw Y unit.
    observed_position_raw: [i16; 3],
    stable_us: u32,
    /// FUN_004091B0's dword at component +8. Even values emit on movement;
    /// odd values wait for the proxy age to exceed 100 ms before advancing.
    movement_counter: i32,
}

/// Bounded local `FUN_00418640` policy for the authenticated Type-93 row.
/// Geometry fixtures deliberately carry no native Sub-J update authority.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Type93SubJPosePlan {
    AttachmentProjection,
    Empty,
    RetireRow,
    CopyParent { child_index: usize },
    Unsupported,
}

fn type93_attachment_descriptor() -> SubJAttachmentDescriptor {
    SubJAttachmentDescriptor {
        reserved_at_0x01: 0,
        slots: vec![SubJAttachmentSlotDescriptor {
            policy_word_raw: 0,
            local_offset_raw: [0; 3],
        }]
        .into_boxed_slice(),
    }
}

fn type93_attachment_runtime(child_entity_id: u32) -> SubJAttachmentRuntime {
    let mut runtime = SubJAttachmentRuntime::from_descriptor(&type93_attachment_descriptor())
        .expect("the exact one-row Type-93 descriptor is valid");
    let appended = runtime.append(child_entity_id);
    debug_assert_eq!(appended, Ok(SubJAttachmentAppend::Appended));
    runtime
}

/// Publish the two host-side projections of retail relation attachment in
/// `FUN_00416700` order: state bit first, then the parent handle.
fn project_relation_attach(entity: &mut Entity, relation_owner_id: u32) {
    entity.collision.state_flags_at_0x08 =
        relation_attach_state_word_after(entity.collision.state_flags_at_0x08);
    entity.attached_to = Some(relation_owner_id);
}

/// Clear the independently owned relation-membership projection before
/// dropping the host-side backlink. The complete type-default/callback release
/// remains with adapters that authenticate that additional custody.
fn project_relation_release_attachment(entity: &mut Entity) {
    entity.collision.state_flags_at_0x08 =
        relation_release_attachment_bit_after(entity.collision.state_flags_at_0x08);
    entity.attached_to = None;
}

fn authenticate_type93_materialiser_metadata(
    metadata: &EntityTypeRuntimeMetadata,
) -> Option<BehaviorSelection> {
    let initializer = metadata.initializer.as_ref()?;
    let [choice] = initializer.behavior_choices.as_ref() else {
        return None;
    };
    let RetailRuntimeValue::Known(topology) = metadata.common_mover_topology else {
        return None;
    };
    let RetailRuntimeValue::Known(Some(descriptor)) = &metadata.sub_j_attachment_descriptor else {
        return None;
    };
    let program = behavior_program(TYPE93_MATERIALISER_BEHAVIOR_CLASS_ID)?;
    let exact_absent_components = metadata.sub_a_propulsion_descriptor
        == RetailRuntimeValue::Known(None)
        && metadata.sub_b_lateral_descriptor == RetailRuntimeValue::Known(None)
        && metadata.sub_c_lift_descriptor == RetailRuntimeValue::Known(None)
        && metadata.sub_d_steering_descriptor == RetailRuntimeValue::Known(None)
        && metadata.projectile_emitter_descriptor == RetailRuntimeValue::Known(None)
        && metadata.status_component_descriptor == RetailRuntimeValue::Known(None)
        && metadata.actor_animation_descriptor == RetailRuntimeValue::Known(None)
        && metadata.sub_h_external_frame_descriptor == RetailRuntimeValue::Known(None)
        && metadata.sub_n_payload.is_none();
    if metadata.model_slots != [0; 4]
        || metadata.mass_raw != 1
        || metadata.capability_flags != 0
        || metadata.initial_health_raw != Some(1_000)
        || metadata.accepted_hit_presentation_sound_id != RetailRuntimeValue::Known(None)
        || metadata.death_sound_id != RetailRuntimeValue::Known(None)
        || metadata.constructor_sound_attachment_id != RetailRuntimeValue::Known(None)
        || metadata.generic_hit_sound_id != RetailRuntimeValue::Known(None)
        || topology != TYPE93_MATERIALISER_TOPOLOGY
        || descriptor != &type93_attachment_descriptor()
        || initializer.initializer_state_flags_raw != TYPE93_INITIALIZER_STATE_FLAGS_RAW
        || initializer.common_axis_descriptor != CommonAxisDescriptor::default()
        || initializer.behavior_rule_ref != 1
        || initializer.alternate_behavior_class_ref != 2
        || choice.weight_rule_id != 1
        || choice.weight_multiplier != 1
        || choice.behavior_class_id != TYPE93_MATERIALISER_BEHAVIOR_CLASS_ID
        || !exact_absent_components
    {
        return None;
    }
    Some(BehaviorSelection {
        choice_index: 0,
        program,
    })
}

