/// End-to-end target policy admitted by checked projectile damage.
///
/// Main Base and Working Factory have an audited-null `+0x44` modifier plus the
/// exact common survivor continuation. Their effective current behavior-style
/// impact slots `+0x20/+0x28` are null and fixed state suppresses the impulse
/// helper. EXE initial styles 4C9480/4C9558 and live Hive 4C94C8 prove the
/// equality of those two slots for this bounded target set.
///
/// The vulnerable Alien Hive is admitted only while it retains the exact
/// class-46 live style and reaction-suppression state proven by
/// `20260722-115649-level1-to-level2/`. This is deliberately not a general
/// pair/entity-type whitelist: other captured null modifiers do not silently
/// opt their targets into this independently bounded integration.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum AuditedProjectileSurvivorPolicy {
    BaseFactory,
    LiveAlienHive,
}

fn audited_projectile_survivor_policy(target: &Entity) -> Option<AuditedProjectileSurvivorPolicy> {
    // Every bounded continuation below was recovered only with an authored
    // null entity-instance damage modifier at live entity +0x44. Callback
    // addresses are mutable lifecycle state, so neither type nor behavior
    // style may substitute for this exact current value.
    if target.collision.pair_callbacks.damage_modifier_address != RetailRuntimeValue::Known(None) {
        return None;
    }
    if matches!(
        target.entity_type,
        MAIN_BASE_ENTITY_TYPE | FACTORY_ENTITY_TYPE
    ) {
        return Some(AuditedProjectileSurvivorPolicy::BaseFactory);
    }
    if target.entity_type != crate::hive_controller::HIVE_ENTITY_TYPE {
        return None;
    }

    let live_hive_style = behavior_program(46)?.initial_style;
    if target
        .current_behavior_context
        .map(|context| context.and_then(|context| context.active_style().audited()))
        != RetailRuntimeValue::Known(Some(live_hive_style))
        || target
            .collision
            .state_flags_at_0x08
            .masked(IMPACT_REACTION_SUPPRESSED_STATE_BIT)
            != RetailRuntimeValue::Known(IMPACT_REACTION_SUPPRESSED_STATE_BIT)
    {
        return None;
    }
    Some(AuditedProjectileSurvivorPolicy::LiveAlienHive)
}

fn required_checked_damage_value<T: Copy>(
    value: RetailRuntimeValue<T>,
    field: CheckedProjectileDamageRuntimeField,
) -> Result<T, CheckedProjectileDamageUnresolved> {
    match value {
        RetailRuntimeValue::Known(value) => Ok(value),
        RetailRuntimeValue::Unresolved => Err(
            CheckedProjectileDamageUnresolved::MissingRuntimeField(field),
        ),
    }
}

/// Resolve the complete local survivor state before the caller mutates any
/// entity word. Keeping this read phase separate makes the transaction's
/// rollback boundary explicit and keeps individual missing-field errors
/// visible without a ladder of partial writes.
fn checked_projectile_damage_state(
    target: &Entity,
) -> Result<CheckedLocalDamageState, CheckedProjectileDamageUnresolved> {
    let remote_owned = required_checked_damage_value(
        target
            .collision
            .state_flags_at_0x08
            .masked(REMOTE_OWNED_STATE_BIT),
        CheckedProjectileDamageRuntimeField::RemoteOwnership,
    )? != 0;
    if remote_owned {
        return Err(CheckedProjectileDamageUnresolved::RemoteDamageDispatchRequired);
    }
    // The executable loader installs a null common type-vtable callback at
    // +0x30 for every loaded type. There is therefore no type-hit callback to
    // invoke here; unlike +0x44, this is a global loader invariant.
    Ok(CheckedLocalDamageState {
        generic: GenericEntityDamageState {
            health_raw: required_checked_damage_value(
                target.collision.health_raw,
                CheckedProjectileDamageRuntimeField::Health,
            )?,
            pre_health_buffer_raw: required_checked_damage_value(
                target.collision.pre_health_damage_buffer_raw,
                CheckedProjectileDamageRuntimeField::PreHealthDamageBuffer,
            )?,
            already_dying: required_checked_damage_value(
                target.collision.state_flags_at_0x08.masked(DYING_STATE_BIT),
                CheckedProjectileDamageRuntimeField::DyingState,
            )? != 0,
        },
        generic_hit_sound_id: required_checked_damage_value(
            target.collision.generic_hit_sound_id,
            CheckedProjectileDamageRuntimeField::GenericHitSound,
        )?,
    })
}

