    /// Splice one or more allocations while preserving every survivor's live-
    /// list order. Attachments do not call this helper: retail retains attached
    /// allocations in the live chain and gates their behavior through state.
    fn remove_live_entity_ids(&mut self, removed_ids: &[u32]) {
        if removed_ids.is_empty() {
            return;
        }
        for entity in &mut self.entities {
            if !removed_ids.contains(&entity.id) {
                continue;
            }
            if let RetailRuntimeValue::Known(Some(factory)) = &mut entity.base_factory_runtime {
                if let Some(production) = factory.production.as_mut() {
                    production.release_voices();
                }
            }
        }
        if self
            .player_dying_contact_runtime
            .is_some_and(|runtime| removed_ids.contains(&runtime.player_id()))
        {
            self.player_dying_contact_runtime = None;
        }
        self.entities
            .retain(|entity| !removed_ids.contains(&entity.id));
        self.native_class0_actors
            .retain(|id, _| !removed_ids.contains(id));
        self.auxiliary_owned_ids
            .retain(|id| !removed_ids.contains(id));
        self.fresh_level1_type9_initial_productions
            .retain(|owner| !removed_ids.contains(&owner.entity_id()));
        self.pending_power_up_destroy_ids
            .retain(|id| !removed_ids.contains(id));
        self.pending_main_base_conversion_destroy_ids
            .retain(|id| !removed_ids.contains(id));
        self.pending_factory_scientist_destroy_ids
            .retain(|id| !removed_ids.contains(id));
        self.pending_actor_deferred_destroy_ids
            .retain(|id| !removed_ids.contains(id));
        self.factory_converted_output_births
            .retain(|birth| !removed_ids.contains(&birth.entity_id));
        self.factory_output_materialiser_births
            .retain(|birth| !removed_ids.contains(&birth.entity_id));
    }

