    /// Retail 44EBD0 runs once before the active world's actor callbacks.
    /// Its phase belongs to the process, while 44EB40 replaces the authored
    /// vector on a world load. Paused/menu frames must not call this method.
    pub fn advance_environment_frame(&mut self, world_fx: &mut WorldFx, elapsed_micros: u32) {
        if self.environment_physics.runtime_wind_mode == 2 {
            let phase = world_fx.advance_wind_phase(elapsed_micros.min(RETAIL_FRAME_DELTA_MAX_US));
            self.environment_physics.current_wind_raw =
                crate::common_mover::environment::gust_vector_raw(
                    self.environment_physics.configured_wind_raw,
                    phase,
                );
        }
    }

