    /// Execute Type-54 ordinary-death into class 38 Change Sea Level.
    ///
    /// Native ordinary construction authenticates the class0 receipt and living
    /// Class0Timer. Captured first-world fixtures without that receipt still
    /// require spawn 8. This owns `FUN_00410C10 -> FUN_0040DB80` and class 38's
    /// synchronous initializer: scatter/RNG/sound order, Secondary/Tertiary
    /// clears, and Primary only after task preparation succeeds. The returned
    /// receipt is the sole authority to tick that task; the heterogeneous
    /// dispatcher deliberately rejects this dedicated terrain-owning family.
    pub fn apply_main_base_abort_type54_death(
        &mut self,
        lease: MainBaseAbortActorLease,
        terrain: &TerrainGrid,
        active_model_extent_raw: u16,
        network_session: MainBaseType54NetworkSession,
        world_fx: &mut WorldFx,
    ) -> Result<MainBaseType54DeathAdvance, MainBaseType54DeathBlock> {
        self.apply_main_base_abort_type54_death_with_allocator(
            lease,
            terrain,
            active_model_extent_raw,
            network_session,
            world_fx,
            &mut HostMainBaseType54PrimaryTaskAllocator,
        )
    }

    fn apply_main_base_abort_type54_death_with_allocator(
        &mut self,
        lease: MainBaseAbortActorLease,
        terrain: &TerrainGrid,
        active_model_extent_raw: u16,
        network_session: MainBaseType54NetworkSession,
        world_fx: &mut WorldFx,
        allocator: &mut impl MainBaseType54PrimaryTaskAllocator,
    ) -> Result<MainBaseType54DeathAdvance, MainBaseType54DeathBlock> {
        let entity_id = lease.entity_id;
        let Some(entity_index) = self
            .entities
            .iter()
            .position(|entity| entity.id == entity_id)
        else {
            return Err(MainBaseType54DeathBlock::EntityMissing);
        };

        let entity = &self.entities[entity_index];
        let expected_lease =
            observe_main_base_abort_actor(entity, self.allocation_generation).lease;
        if lease != expected_lease {
            return Err(MainBaseType54DeathBlock::ActorLeaseMismatch {
                expected: expected_lease,
                actual: lease,
            });
        }
        let route = classify_main_base_abort_actor(MainBaseAbortActorFacts {
            entity_id,
            entity_type: entity.entity_type,
            capability_flags: entity.capability_flags,
            state_flags: entity
                .collision
                .state_flags_at_0x08
                .masked(ORDINARY_DEATH_STATE_SKIP_MASK),
        });
        if route != (MainBaseAbortActorRoute::OrdinaryDeath { entity_id }) {
            return Err(MainBaseType54DeathBlock::NotOrdinaryRoute(route));
        }
        if entity.entity_type != LEVEL_ONE_TYPE54_ENTITY_TYPE {
            return Err(MainBaseType54DeathBlock::UnsupportedEntityType {
                actual: entity.entity_type,
            });
        }
        let native_class0 = self.native_class0_construction_present(entity_id);
        if native_class0 {
            if !self.native_class0_allocation_authenticates(entity_id) {
                return Err(MainBaseType54DeathBlock::NativeConstructorReceiptMismatch);
            }
        } else {
            if !self.fresh_new_game_first_world {
                return Err(MainBaseType54DeathBlock::NotFreshNewGameFirstWorld);
            }
            if entity.authored_spawn_index != Some(LEVEL_ONE_TYPE54_SPAWN_INDEX) {
                return Err(MainBaseType54DeathBlock::UnauthenticatedSpawn {
                    actual: entity.authored_spawn_index,
                });
            }
        }
        let remote_owned = match entity
            .collision
            .state_flags_at_0x08
            .masked(REMOTE_OWNED_STATE_BIT)
        {
            RetailRuntimeValue::Known(value) => value != 0,
            RetailRuntimeValue::Unresolved => {
                return Err(MainBaseType54DeathBlock::RemoteOwnershipUnresolved)
            }
        };
        if remote_owned {
            let outcome = MainBaseType54DeathOutcome::RemoteOwnedNoOp {
                entity_id,
                entity_type: entity.entity_type,
            };
            return Ok(self.finish_main_base_abort_type54_death(entity_id, outcome));
        }
        let already_dying = match entity.collision.state_flags_at_0x08.masked(DYING_STATE_BIT) {
            RetailRuntimeValue::Known(value) => value != 0,
            RetailRuntimeValue::Unresolved => {
                return Err(MainBaseType54DeathBlock::DyingStateUnresolved)
            }
        };
        match classify_generic_death_entry(false, already_dying) {
            GenericDeathEntry::RemoteOwnedNoOp => {
                unreachable!("remote ownership returned before the dying-state read")
            }
            GenericDeathEntry::AlreadyDyingNoOp => {
                let outcome = MainBaseType54DeathOutcome::AlreadyDyingNoOp {
                    entity_id,
                    entity_type: entity.entity_type,
                };
                return Ok(self.finish_main_base_abort_type54_death(entity_id, outcome));
            }
            GenericDeathEntry::Dispatch => {}
        }

        if native_class0 && self.native_class0_has_pending_prefix(entity_id) {
            return Err(MainBaseType54DeathBlock::PendingNativePrefix);
        }

        // Generic death's remote/already-dying entries return before the
        // selected type/style initializer is consulted. Authenticate the
        // downstream class-38 contract only for the dispatching branch.
        let metadata = self
            .type_metadata
            .get(entity.entity_type as usize)
            .ok_or(MainBaseType54DeathBlock::TypeMetadataUnavailable)?;
        if !exact_level_one_type54_metadata(metadata)
            || entity.mass_raw != metadata.mass_raw
            || entity.capability_flags != metadata.capability_flags
            || (!native_class0 && entity.model_slots != [Some(LEVEL_ONE_TYPE54_MODEL_ID); 4])
        {
            return Err(MainBaseType54DeathBlock::TypeMetadataMismatch);
        }
        let RetailRuntimeValue::Known(Some(initial_behavior)) = entity.initial_behavior else {
            return Err(MainBaseType54DeathBlock::InitialBehaviorMismatch);
        };
        if initial_behavior.program.class_id != LEVEL_ONE_TYPE54_INITIAL_BEHAVIOR_CLASS {
            return Err(MainBaseType54DeathBlock::InitialBehaviorMismatch);
        }
        if entity.main_base_type54_sea_delta_source
            != RetailRuntimeValue::Known(MainBaseType54SeaDeltaSource::DeriveFromActorModelAndSea)
        {
            return Err(MainBaseType54DeathBlock::SeaDeltaSourceUnsupported(
                entity.main_base_type54_sea_delta_source,
            ));
        }

        if native_class0 {
            if !matches!(
                entity.collision.active_model_slot(),
                RetailRuntimeValue::Known(_)
            ) || entity.model_index.is_none()
            {
                return Err(MainBaseType54DeathBlock::ActiveModelMismatch);
            }
        } else if entity.collision.active_model_slot() != RetailRuntimeValue::Known(0)
            || entity.model_index != Some(LEVEL_ONE_TYPE54_MODEL_ID)
        {
            return Err(MainBaseType54DeathBlock::ActiveModelMismatch);
        }
        if !native_class0 && active_model_extent_raw != LEVEL_ONE_TYPE54_MODEL_EXTENT_RAW {
            return Err(MainBaseType54DeathBlock::ActiveModelExtentMismatch {
                actual: active_model_extent_raw,
            });
        }
        if network_session != MainBaseType54NetworkSession::SoloNetworkingDisabled {
            return Err(MainBaseType54DeathBlock::NetworkSessionUnsupported(
                network_session,
            ));
        }
        match entity
            .collision
            .state_flags_at_0x08
            .masked(DEFERRED_DESTROY_PENDING_STATE_BIT)
        {
            RetailRuntimeValue::Known(0) => {}
            RetailRuntimeValue::Known(_) => {
                return Err(MainBaseType54DeathBlock::DeferredDestroyAlreadyPending)
            }
            RetailRuntimeValue::Unresolved => {
                return Err(MainBaseType54DeathBlock::DeferredDestroyStateUnresolved)
            }
        }
        if self.pending_actor_deferred_destroy_ids.contains(&entity_id) {
            return Err(MainBaseType54DeathBlock::DeferredDestroyAlreadyQueued);
        }
        let context = match entity.current_behavior_context {
            RetailRuntimeValue::Known(Some(context)) => context,
            RetailRuntimeValue::Known(None) => {
                return Err(MainBaseType54DeathBlock::CurrentBehaviorContextAbsent)
            }
            RetailRuntimeValue::Unresolved => {
                return Err(MainBaseType54DeathBlock::CurrentBehaviorContextMismatch)
            }
        };
        let selected_context = authenticate_fresh_level_one_type54_context(context)
            .ok_or(MainBaseType54DeathBlock::CurrentBehaviorContextMismatch)?;
        if native_class0
            && (context.target_handle_at_0x08() != RetailRuntimeValue::Known(None)
                || context.auxiliary_word_at_0x0c() != RetailRuntimeValue::Known(0))
        {
            return Err(MainBaseType54DeathBlock::CurrentBehaviorContextMismatch);
        }
        // Native class0 publishes the exact 9,000-ms Primary timer. Captured
        // first-world fixtures still use Port `None` as the bounded
        // equivalence for that inert wrapper. Class 38 clears Secondary and
        // Tertiary and replaces Primary after successful preparation.
        let tasks_releasable = if native_class0 {
            native_class0_quiet_death_tasks_are_locally_releasable(entity)
        } else {
            ActorTaskSlot::IN_RETAIL_TICK_ORDER
                .into_iter()
                .all(|slot| entity.actor_task_state(slot).is_none())
        };
        if !tasks_releasable {
            return Err(MainBaseType54DeathBlock::UnexpectedPublishedTask);
        }
        let position_raw = entity.position_raw();
        let sea_level_raw = (terrain.header[0] >> 8) as i16;

        // Generic-death prefix: this exact type authors neither a death cue nor
        // a constructor sound attachment, and class-0's death hook is null.
        let entity = &mut self.entities[entity_index];
        entity.collision.health_raw = RetailRuntimeValue::Known(0);
        entity
            .collision
            .state_flags_at_0x08
            .overwrite(DYING_STATE_BIT, DYING_STATE_BIT);
        entity.current_behavior_context = RetailRuntimeValue::Known(Some(selected_context));

        // FUN_0040BDC0 clears bit 0x800 before the synchronous helper. The
        // helper's kind-2 network call occurs after scatter allocation, but is
        // an exact no-op in the authenticated solo session. WorldFx retains
        // the local scatter/surface/sound order and its single RNG draw.
        entity
            .collision
            .state_flags_at_0x08
            .overwrite(0x0000_0800, 0);
        world_fx.emit_scatter_surface_burst_raw(
            position_raw,
            active_model_extent_raw,
            Some(sea_level_raw),
            entity_id,
        );
        let network = MainBaseType54NetworkDisposition::Kind2SuppressedBySoloSession;

        // Class 38 clears the auxiliary slots before FUN_00405040 computes
        // the Primary payload and attempts allocation. The exact Type-54
        // Section-12 row has no optional FUN_00406070 suffix components, so
        // task preparation consumes no additional RNG or external action.
        entity.actor_tasks.clear_slot(ActorTaskSlot::Secondary);
        entity.actor_tasks.clear_slot(ActorTaskSlot::Tertiary);
        let sea_delta_raw =
            change_sea_level_delta_raw(position_raw[1], active_model_extent_raw, terrain.header[0]);
        let task_state = MainBaseType54SeaLevelTaskState::new(sea_delta_raw);
        let tick_sequence = task_state.next_tick_sequence();
        let Some(prepared) = allocator.prepare(task_state) else {
            // FUN_00405040 returns its allocation error. The outer behavior
            // installer then publishes the unnamed fallback, applies 0x1280,
            // and clears Secondary, Tertiary, and Primary. Earlier class-38
            // state, particles, RNG, and sound stay committed.
            entity.publish_behavior_initializer_failure_fallback(selected_context);
            let outcome =
                MainBaseType54DeathOutcome::InitializerFallbackAfterTaskAllocationFailure {
                    entity_id,
                    sea_delta_raw,
                    network,
                };
            return Ok(self.finish_main_base_abort_type54_death(entity_id, outcome));
        };
        let task_id = entity.actor_tasks.replace_prepared(
            ActorTaskSlot::Primary,
            prepared.map(ActorTaskRuntime::ChangeSeaLevel),
        );
        let tick_receipt = MainBaseType54SeaLevelTickReceipt::issue(lease, task_id, tick_sequence);
        let outcome = MainBaseType54DeathOutcome::SeaLevelTaskPublished {
            entity_id,
            sea_delta_raw,
            network,
            tick_receipt,
        };
        Ok(self.finish_main_base_abort_type54_death(entity_id, outcome))
    }

    fn finish_main_base_abort_type54_death(
        &self,
        entity_id: u32,
        outcome: MainBaseType54DeathOutcome,
    ) -> MainBaseType54DeathAdvance {
        match self.main_base_abort_successor_after_callback(entity_id) {
            Ok(next_actor) => MainBaseType54DeathAdvance::Advanced {
                outcome,
                next_actor,
            },
            Err(()) => MainBaseType54DeathAdvance::SuccessorUnavailableAfterCommit { outcome },
        }
    }

    /// Execute the exact fresh-Level-1 spawn-23/type-66 death continuation.
    ///
    /// The production Main Base sweep calls this only after the normal task
    /// pass and replaces the scheduler's old same-family Primary owner with
    /// the newborn progressive Working Factory authority. The former direct
    /// factory-arming bridge is intentionally not part of that transaction.
    pub fn apply_main_base_abort_type66_death(
        &mut self,
        lease: MainBaseAbortActorLease,
        world_fx: &mut WorldFx,
    ) -> Result<MainBaseType66DeathAdvance, MainBaseType66DeathBlock> {
        self.apply_main_base_abort_type66_death_with_allocator(
            lease,
            world_fx,
            &mut HostMainBaseType66PrimaryTaskAllocator,
        )
    }

    fn apply_main_base_abort_type66_death_with_allocator(
        &mut self,
        lease: MainBaseAbortActorLease,
        world_fx: &mut WorldFx,
        allocator: &mut impl MainBaseType66PrimaryTaskAllocator,
    ) -> Result<MainBaseType66DeathAdvance, MainBaseType66DeathBlock> {
        let entity_id = lease.entity_id;
        let Some(entity_index) = self
            .entities
            .iter()
            .position(|entity| entity.id == entity_id)
        else {
            return Err(MainBaseType66DeathBlock::EntityMissing);
        };

        let entity = &self.entities[entity_index];
        let expected_lease =
            observe_main_base_abort_actor(entity, self.allocation_generation).lease;
        if lease != expected_lease {
            return Err(MainBaseType66DeathBlock::ActorLeaseMismatch {
                expected: expected_lease,
                actual: lease,
            });
        }
        let route = classify_main_base_abort_actor(MainBaseAbortActorFacts {
            entity_id,
            entity_type: entity.entity_type,
            capability_flags: entity.capability_flags,
            state_flags: entity
                .collision
                .state_flags_at_0x08
                .masked(ORDINARY_DEATH_STATE_SKIP_MASK),
        });
        if route != (MainBaseAbortActorRoute::OrdinaryDeath { entity_id }) {
            return Err(MainBaseType66DeathBlock::NotOrdinaryRoute(route));
        }
        if !self.fresh_new_game_first_world {
            return Err(MainBaseType66DeathBlock::NotFreshNewGameFirstWorld);
        }
        if entity.entity_type != LEVEL_ONE_TYPE66_ENTITY_TYPE {
            return Err(MainBaseType66DeathBlock::UnsupportedEntityType {
                actual: entity.entity_type,
            });
        }
        if entity.authored_spawn_index != Some(LEVEL_ONE_TYPE66_SPAWN_INDEX) {
            return Err(MainBaseType66DeathBlock::UnauthenticatedSpawn {
                actual: entity.authored_spawn_index,
            });
        }

        // FUN_00410C10's two entry no-ops precede every type/style/runtime
        // access. In particular remote wins for a combined remote|dying word.
        let remote_owned = match entity
            .collision
            .state_flags_at_0x08
            .masked(REMOTE_OWNED_STATE_BIT)
        {
            RetailRuntimeValue::Known(value) => value != 0,
            RetailRuntimeValue::Unresolved => {
                return Err(MainBaseType66DeathBlock::RemoteOwnershipUnresolved)
            }
        };
        if remote_owned {
            let outcome = MainBaseType66DeathOutcome::RemoteOwnedNoOp {
                entity_id,
                entity_type: entity.entity_type,
            };
            return Ok(self.finish_main_base_abort_type66_death(entity_id, outcome));
        }
        let already_dying = match entity.collision.state_flags_at_0x08.masked(DYING_STATE_BIT) {
            RetailRuntimeValue::Known(value) => value != 0,
            RetailRuntimeValue::Unresolved => {
                return Err(MainBaseType66DeathBlock::DyingStateUnresolved)
            }
        };
        if already_dying {
            let outcome = MainBaseType66DeathOutcome::AlreadyDyingNoOp {
                entity_id,
                entity_type: entity.entity_type,
            };
            return Ok(self.finish_main_base_abort_type66_death(entity_id, outcome));
        }

        let metadata = self
            .type_metadata
            .get(entity.entity_type as usize)
            .ok_or(MainBaseType66DeathBlock::TypeMetadataUnavailable)?;
        if !exact_level_one_type66_metadata(metadata)
            || entity.mass_raw != LEVEL_ONE_TYPE66_MASS_RAW
            || entity.capability_flags != LEVEL_ONE_TYPE66_CAPABILITY_FLAGS
        {
            return Err(MainBaseType66DeathBlock::TypeMetadataMismatch);
        }
        if entity.model_slots != LEVEL_ONE_TYPE66_CAPTURED_MODEL_SLOTS
            || entity.collision.active_model_slot() != RetailRuntimeValue::Known(0)
            || entity.model_index != Some(LEVEL_ONE_TYPE66_ACTIVE_MODEL_ID)
        {
            return Err(MainBaseType66DeathBlock::LiveModelMismatch);
        }
        if entity.collision.state_flags_at_0x08
            != RetailStateWord::exact(LEVEL_ONE_TYPE66_CAPTURED_PREABORT_STATE_RAW)
        {
            return Err(MainBaseType66DeathBlock::StateMismatch);
        }
        if entity.collision.health_raw
            != RetailRuntimeValue::Known(LEVEL_ONE_TYPE66_INITIAL_HEALTH_RAW)
            || entity.collision.death_sound_id
                != RetailRuntimeValue::Known(Some(LEVEL_ONE_TYPE66_DEATH_SOUND_ID))
        {
            return Err(MainBaseType66DeathBlock::HealthStateMismatch);
        }
        let RetailRuntimeValue::Known(Some(initial_behavior)) = entity.initial_behavior else {
            return Err(MainBaseType66DeathBlock::InitialBehaviorMismatch);
        };
        if initial_behavior.choice_index != 0
            || initial_behavior.program.class_id != LEVEL_ONE_TYPE66_INITIAL_BEHAVIOR_CLASS
        {
            return Err(MainBaseType66DeathBlock::InitialBehaviorMismatch);
        }
        let context = match entity.current_behavior_context {
            RetailRuntimeValue::Known(Some(context)) => context,
            RetailRuntimeValue::Known(None) => {
                return Err(MainBaseType66DeathBlock::CurrentBehaviorContextAbsent)
            }
            RetailRuntimeValue::Unresolved => {
                return Err(MainBaseType66DeathBlock::CurrentBehaviorContextMismatch)
            }
        };
        let selected_context = authenticate_fresh_level_one_type66_context(context)
            .ok_or(MainBaseType66DeathBlock::CurrentBehaviorContextMismatch)?;

        let factory = match entity.base_factory_runtime {
            RetailRuntimeValue::Known(Some(factory)) => factory,
            RetailRuntimeValue::Known(None) | RetailRuntimeValue::Unresolved => {
                return Err(MainBaseType66DeathBlock::SubMRuntimeUnavailable)
            }
        };
        if factory.status_descriptor != LEVEL_ONE_TYPE66_STATUS_DESCRIPTOR
            || factory.control_value_raw != 0xF412
            || factory.required_scientists != 2
        {
            return Err(MainBaseType66DeathBlock::SubMRuntimeMismatch);
        }
        if factory.production.is_none() {
            return Err(MainBaseType66DeathBlock::FactoryProductionRuntimeUnavailable);
        }
        let Some(live_owner) = factory.live_owner else {
            return Err(MainBaseType66DeathBlock::LiveOwnerUnavailable);
        };
        if live_owner.allocation_identity == 0
            || live_owner.maximum_health_raw != LEVEL_ONE_TYPE66_INITIAL_HEALTH_RAW
        {
            return Err(MainBaseType66DeathBlock::LiveOwnerMismatch);
        }
        if factory.progressive_death != ProgressiveDeathState::idle(0) {
            return Err(MainBaseType66DeathBlock::ProgressiveDeathStateMismatch);
        }
        let Some(primary_task_id) = entity.actor_tasks.task_in_slot(ActorTaskSlot::Primary) else {
            return Err(MainBaseType66DeathBlock::PrimaryTaskMismatch);
        };
        let Some(ActorTaskRuntime::WorkingFactory(primary)) =
            entity.actor_tasks.task_state(primary_task_id)
        else {
            return Err(MainBaseType66DeathBlock::PrimaryTaskMismatch);
        };
        if primary.owner_allocation_identity() != live_owner.allocation_identity
            || entity.actor_tasks.wrapper_flags(primary_task_id)
                != Some(crate::actor_task_owner::ActorTaskWrapperFlags {
                    alive: true,
                    in_callback: false,
                })
        {
            return Err(MainBaseType66DeathBlock::PrimaryTaskMismatch);
        }
        let position_raw = entity.position_raw();

        // Generic-death prefix and current style hook. Type 66's constructor
        // sound attachment is exact null, so the release between these phases
        // is a proven no-op.
        let entity = &mut self.entities[entity_index];
        entity.collision.health_raw = RetailRuntimeValue::Known(0);
        entity
            .collision
            .state_flags_at_0x08
            .overwrite(DYING_STATE_BIT, DYING_STATE_BIT);
        world_fx.queue_fixed_positional_sound_raw(LEVEL_ONE_TYPE66_DEATH_SOUND_ID, position_raw);
        entity.collision.health_raw = RetailRuntimeValue::Known(PROGRESSION_REVIVE_HEALTH_RAW);
        entity
            .collision
            .state_flags_at_0x08
            .overwrite(DYING_STATE_BIT, 0);
        let RetailRuntimeValue::Known(Some(factory)) = &mut entity.base_factory_runtime else {
            unreachable!("preflight authenticated the exact Sub-M runtime")
        };
        let ProgressiveDeathBegin::Revived { state } = factory.progressive_death.begin() else {
            unreachable!("preflight authenticated the idle progression state")
        };
        factory.progressive_death = state;

        // FUN_00425680 draws even for this singleton Always choice. Publish
        // the resulting named class-39 descriptor while preserving the live
        // context target and auxiliary words.
        let mut selector_rng_word = None;
        let selected = select_initial_behavior(
            metadata
                .initializer
                .as_ref()
                .expect("exact metadata retains an initializer")
                .behavior_choices
                .as_ref(),
            |rule| match rule {
                BehaviorWeightRule::Always => 1,
                _ => unreachable!("exact Type-66 metadata has one Always choice"),
            },
            || {
                debug_assert!(selector_rng_word.is_none());
                let word = world_fx.next_shared_retail_random_u16();
                selector_rng_word = Some(word);
                u32::from(word)
            },
        )
        .expect("exact Type-66 metadata has a valid selector")
        .expect("the positive singleton Always choice is selected");
        let selector_rng_word =
            selector_rng_word.expect("the retail selector draws exactly once per invocation");
        debug_assert_eq!(selected.choice_index, 0);
        debug_assert_eq!(
            selected.program.class_id,
            LEVEL_ONE_TYPE66_INITIAL_BEHAVIOR_CLASS
        );
        entity.current_behavior_context = RetailRuntimeValue::Known(Some(selected_context));
        let policy = initial_behavior_state_policy(selected.program);
        entity
            .collision
            .state_flags_at_0x08
            .overwrite(policy.set_bits | policy.clear_bits, policy.set_bits);

        // FUN_004257C0 clears T then S before preparing the replacement P.
        entity.actor_tasks.clear_slot(ActorTaskSlot::Tertiary);
        entity.actor_tasks.clear_slot(ActorTaskSlot::Secondary);
        let task_state = WorkingFactoryTaskState::new(live_owner.allocation_identity);
        let Some(prepared) = allocator.prepare(task_state) else {
            // The outer installer publishes fallback after the committed cue,
            // revive, selector RNG, descriptor publication, and T/S clears.
            // Its shared helper then clears S -> T -> P; no rollback occurs.
            entity.publish_behavior_initializer_failure_fallback(selected_context);
            let outcome =
                MainBaseType66DeathOutcome::InitializerFallbackAfterTaskAllocationFailure {
                    entity_id,
                    death_sound_id: LEVEL_ONE_TYPE66_DEATH_SOUND_ID,
                    selector_rng_word,
                };
            return Ok(self.finish_main_base_abort_type66_death(entity_id, outcome));
        };
        let task_id = entity.actor_tasks.replace_prepared(
            ActorTaskSlot::Primary,
            prepared.map(ActorTaskRuntime::WorkingFactory),
        );
        let task_lease = MainBaseType66WorkingFactoryTaskLease::issue(
            lease,
            task_id,
            live_owner.allocation_identity,
        );
        let outcome = MainBaseType66DeathOutcome::WorkingFactoryTaskPublished {
            entity_id,
            death_sound_id: LEVEL_ONE_TYPE66_DEATH_SOUND_ID,
            selector_rng_word,
            task_lease,
        };
        Ok(self.finish_main_base_abort_type66_death(entity_id, outcome))
    }

    fn finish_main_base_abort_type66_death(
        &self,
        entity_id: u32,
        outcome: MainBaseType66DeathOutcome,
    ) -> MainBaseType66DeathAdvance {
        match self.main_base_abort_successor_after_callback(entity_id) {
            Ok(next_actor) => MainBaseType66DeathAdvance::Advanced {
                outcome,
                next_actor,
            },
            Err(()) => MainBaseType66DeathAdvance::SuccessorUnavailableAfterCommit { outcome },
        }
    }

    /// Execute the exact fresh-Level-1 Type-9 ordinary-death/class-14 path.
    ///
    /// Fresh construction retains exact selected branch/task custody. Death
    /// authenticates and transfers either that production custody or a legacy
    /// dormant receipt, then bridges the accepted capture's exact predecessor
    /// style for each spawn. The synchronous callback is complete:
    /// generic-death prefix, Sub-I reset, session-zero or abort-suppressed
    /// optional-message gate, pair-bit clear, fallible shared task construction,
    /// one Sub-A RNG draw,
    /// literal-speed overwrite, and publish-last Primary replacement.
    pub fn apply_main_base_abort_type9_death(
        &mut self,
        lease: MainBaseAbortActorLease,
        result_screen: MainBaseType9ResultScreenState,
        world_fx: &mut WorldFx,
    ) -> Result<MainBaseType9DeathAdvance, MainBaseType9DeathBlock> {
        self.apply_main_base_abort_type9_death_with_allocator(
            lease,
            result_screen,
            world_fx,
            &mut HostMainBaseType9PrimaryTaskAllocator,
        )
    }

    fn apply_main_base_abort_type9_death_with_allocator(
        &mut self,
        lease: MainBaseAbortActorLease,
        result_screen: MainBaseType9ResultScreenState,
        world_fx: &mut WorldFx,
        allocator: &mut impl MainBaseType9PrimaryTaskAllocator,
    ) -> Result<MainBaseType9DeathAdvance, MainBaseType9DeathBlock> {
        let entity_id = lease.entity_id;
        let Some(entity_index) = self
            .entities
            .iter()
            .position(|entity| entity.id == entity_id)
        else {
            return Err(MainBaseType9DeathBlock::EntityMissing);
        };

        let entity = &self.entities[entity_index];
        let expected_lease =
            observe_main_base_abort_actor(entity, self.allocation_generation).lease;
        if lease != expected_lease {
            return Err(MainBaseType9DeathBlock::ActorLeaseMismatch {
                expected: expected_lease,
                actual: lease,
            });
        }
        let route = classify_main_base_abort_actor(MainBaseAbortActorFacts {
            entity_id,
            entity_type: entity.entity_type,
            capability_flags: entity.capability_flags,
            state_flags: entity
                .collision
                .state_flags_at_0x08
                .masked(ORDINARY_DEATH_STATE_SKIP_MASK),
        });
        if route != (MainBaseAbortActorRoute::OrdinaryDeath { entity_id }) {
            return Err(MainBaseType9DeathBlock::NotOrdinaryRoute(route));
        }
        if !self.fresh_new_game_first_world {
            return Err(MainBaseType9DeathBlock::NotFreshNewGameFirstWorld);
        }
        if entity.entity_type != LEVEL_ONE_TYPE9_ENTITY_TYPE {
            return Err(MainBaseType9DeathBlock::UnsupportedEntityType {
                actual: entity.entity_type,
            });
        }
        let Some(spawn_index) = entity.authored_spawn_index else {
            return Err(MainBaseType9DeathBlock::UnauthenticatedSpawn { actual: None });
        };
        if MainBaseType9CapturedProfile::for_spawn(spawn_index).is_none() {
            return Err(MainBaseType9DeathBlock::UnauthenticatedSpawn {
                actual: Some(spawn_index),
            });
        }

        let remote_owned = match entity
            .collision
            .state_flags_at_0x08
            .masked(REMOTE_OWNED_STATE_BIT)
        {
            RetailRuntimeValue::Known(value) => value != 0,
            RetailRuntimeValue::Unresolved => {
                return Err(MainBaseType9DeathBlock::RemoteOwnershipUnresolved)
            }
        };
        if remote_owned {
            let outcome = MainBaseType9DeathOutcome::RemoteOwnedNoOp {
                entity_id,
                entity_type: entity.entity_type,
            };
            return Ok(self.finish_main_base_abort_type9_death(entity_id, outcome));
        }
        let already_dying = match entity.collision.state_flags_at_0x08.masked(DYING_STATE_BIT) {
            RetailRuntimeValue::Known(value) => value != 0,
            RetailRuntimeValue::Unresolved => {
                return Err(MainBaseType9DeathBlock::DyingStateUnresolved)
            }
        };
        match classify_generic_death_entry(false, already_dying) {
            GenericDeathEntry::RemoteOwnedNoOp => {
                unreachable!("remote ownership returned before the dying-state read")
            }
            GenericDeathEntry::AlreadyDyingNoOp => {
                let outcome = MainBaseType9DeathOutcome::AlreadyDyingNoOp {
                    entity_id,
                    entity_type: entity.entity_type,
                };
                return Ok(self.finish_main_base_abort_type9_death(entity_id, outcome));
            }
            GenericDeathEntry::Dispatch => {}
        }

        let metadata = self
            .type_metadata
            .get(entity.entity_type as usize)
            .ok_or(MainBaseType9DeathBlock::TypeMetadataUnavailable)?;
        if !exact_level_one_type9_metadata(metadata)
            || entity.model_slots != [Some(LEVEL_ONE_TYPE9_MODEL_ID); 4]
            || entity.mass_raw != metadata.mass_raw
            || entity.capability_flags != LEVEL_ONE_TYPE9_CAPABILITY_FLAGS
        {
            return Err(MainBaseType9DeathBlock::TypeMetadataMismatch);
        }
        if entity.collision.active_model_slot() != RetailRuntimeValue::Known(0)
            || entity.model_index != Some(LEVEL_ONE_TYPE9_MODEL_ID)
        {
            return Err(MainBaseType9DeathBlock::ActiveModelMismatch);
        }
        if entity.collision.death_sound_id
            != RetailRuntimeValue::Known(Some(LEVEL_ONE_TYPE9_DEATH_SOUND_ID))
        {
            return Err(MainBaseType9DeathBlock::DeathSoundStateMismatch);
        }
        if metadata.constructor_sound_attachment_id != RetailRuntimeValue::Known(None) {
            return Err(MainBaseType9DeathBlock::ConstructorSoundAttachmentNotExactNull);
        }
        let mut production_indices = self
            .fresh_level1_type9_initial_productions
            .iter()
            .enumerate()
            .filter(|(_, owner)| owner.entity_id() == entity_id)
            .map(|(index, _)| index);
        let production_index = production_indices.next();
        if production_indices.next().is_some() {
            return Err(MainBaseType9DeathBlock::InitialBehaviorProvenanceMismatch);
        }
        let production_owner = production_index
            .map(|index| (index, &self.fresh_level1_type9_initial_productions[index]));
        let (selected_context, captured_profile, component_custody) =
            authenticate_fresh_level_one_type9_exploding_context(
                entity,
                metadata,
                production_owner,
            )
            .ok_or(MainBaseType9DeathBlock::InitialBehaviorProvenanceMismatch)?;
        if component_custody == FreshLevelOneType9DeathComponentCustody::DormantPending
            && ActorTaskSlot::IN_RETAIL_TICK_ORDER
                .into_iter()
                .any(|slot| entity.actor_task_state(slot).is_some())
        {
            return Err(MainBaseType9DeathBlock::UnexpectedPublishedTask);
        }
        match entity.sub_a_propulsion_runtime {
            RetailRuntimeValue::Known(Some(_)) => {}
            RetailRuntimeValue::Known(None) | RetailRuntimeValue::Unresolved => {
                return Err(MainBaseType9DeathBlock::SubARuntimeUnavailable)
            }
        }
        match entity.actor_animation_runtime {
            RetailRuntimeValue::Known(Some(controller))
                if controller.descriptor()
                    == crate::main_base_type9_abort::LEVEL_ONE_TYPE9_SUB_I_DESCRIPTOR => {}
            RetailRuntimeValue::Known(Some(_))
            | RetailRuntimeValue::Known(None)
            | RetailRuntimeValue::Unresolved => {
                return Err(MainBaseType9DeathBlock::ActorAnimationRuntimeUnavailable)
            }
        }
        if entity
            .collision
            .state_flags_at_0x08
            .masked(LEVEL_ONE_TYPE9_PAIR_COLLISION_STATE_BIT)
            == RetailRuntimeValue::Unresolved
        {
            return Err(MainBaseType9DeathBlock::PairCollisionStateUnresolved);
        }
        let message = type9_class14_optional_message(entity.capability_flags, result_screen)?;
        // A same-frame Main Base conversion has already reached the shared
        // idempotent deferred helper. Class 14 publishes its task without
        // calling that helper, so validate and preserve the conversion owner;
        // every other pending owner remains outside this bounded overlap.
        let deferred_destroy_entry = self
            .preflight_main_base_deferred_destroy_entry(
                entity_id,
                entity.collision.state_flags_at_0x08,
            )
            .map_err(MainBaseType9DeathBlock::DeferredDestroyCustody)?;
        if let MainBaseDeferredDestroyEntry::AlreadyPending(owner) = deferred_destroy_entry {
            if owner != MainBaseExternalDeferredDestroyOwner::MainBaseConversion {
                return Err(MainBaseType9DeathBlock::DeferredDestroyOwnerUnsupported(
                    owner,
                ));
            }
        }
        let position_raw = entity.position_raw();

        // This is the transaction's first committed mutation. Selected
        // production must relinquish both the exact branch/task sidecar and
        // component state together before death clears the published graph.
        let components = match component_custody {
            FreshLevelOneType9DeathComponentCustody::DormantPending => self.entities[entity_index]
                .ordinary_type9_pending_initial_selection
                .take()
                .expect("preflight authenticated dormant Type-9 component custody"),
            FreshLevelOneType9DeathComponentCustody::SelectedProduction { sidecar_index } => {
                let owner = self
                    .fresh_level1_type9_initial_productions
                    .remove(sidecar_index);
                debug_assert_eq!(owner.entity_id(), entity_id);
                self.entities[entity_index]
                    .ordinary_type9_selected_component_runtime
                    .take()
                    .expect("preflight authenticated selected Type-9 component custody")
                    .components()
            }
        };

        // Generic-death prefix. The exact constructor attachment is null and
        // the capture-authenticated predecessor style has a null death hook.
        let entity = &mut self.entities[entity_index];
        // The port does not run the preceding 27.8 seconds of ordinary Type-9
        // AI/E870. Bridge the exact sample-5564 post-predecessor matrix into
        // the same allocation-owned `+0x0C..+0x2C` authority before class 14
        // can publish or execute its first callback.
        entity.physical_body_basis_q31 =
            RetailRuntimeValue::Known(captured_profile.physical_body_basis_q31);
        // The normal live-list scheduler runs before the late Main Base abort
        // selector. Both its wait path and its post-callback path clear +0xB2,
        // so the capture-bridged class-14 allocation inherits exact zero here.
        entity.collision.animation_offset_at_0xb2 = RetailRuntimeValue::Known(0);
        entity.collision.health_raw = RetailRuntimeValue::Known(0);
        entity
            .collision
            .state_flags_at_0x08
            .overwrite(DYING_STATE_BIT, DYING_STATE_BIT);
        world_fx.queue_fixed_positional_sound_raw(LEVEL_ONE_TYPE9_DEATH_SOUND_ID, position_raw);
        entity.current_behavior_context = RetailRuntimeValue::Known(Some(selected_context));

        // FUN_0040C3A0's committed pre-constructor prefix.
        entity.actor_tasks.clear_slot(ActorTaskSlot::Secondary);
        entity.actor_tasks.clear_slot(ActorTaskSlot::Tertiary);
        let RetailRuntimeValue::Known(Some(animation)) = &mut entity.actor_animation_runtime else {
            unreachable!("preflight authenticated the exact Sub-I runtime")
        };
        animation.apply_exploding_person_reset();
        entity
            .collision
            .state_flags_at_0x08
            .overwrite(LEVEL_ONE_TYPE9_PAIR_COLLISION_STATE_BIT, 0);
        entity.main_base_type9_death_component_runtime =
            Some(MainBaseType9DeathComponentRuntime { components });

        let task_state =
            SharedRetargetTaskState::new(position_raw, LEVEL_ONE_TYPE9_EXPLODING_LIFETIME_MS);
        let Some(prepared) = allocator.prepare(task_state) else {
            // The failed task wrapper owns no FUN_00406070 suffix: no RNG and
            // no Sub-A writes. The outer installer preserves the committed
            // prefix, publishes the unnamed fallback, and clears S -> T -> P.
            entity.publish_behavior_initializer_failure_fallback(selected_context);
            let outcome =
                MainBaseType9DeathOutcome::InitializerFallbackAfterTaskAllocationFailure {
                    entity_id,
                    death_sound_id: LEVEL_ONE_TYPE9_DEATH_SOUND_ID,
                    message,
                };
            return Ok(self.finish_main_base_abort_type9_death(entity_id, outcome));
        };

        // Successful FUN_00406070 consumes exactly one shared RNG word. Its
        // randomized speed write is real even though FUN_004032A0 immediately
        // replaces the same dword with literal one before Primary publication.
        let sub_a_rng_word = world_fx.next_shared_retail_random_u16();
        let RetailRuntimeValue::Known(Some(sub_a)) = &mut entity.sub_a_propulsion_runtime else {
            unreachable!("preflight authenticated the exact Sub-A runtime")
        };
        sub_a.apply_shared_initializer_rng_reset(
            LEVEL_ONE_TYPE9_SUB_A_DESCRIPTOR.target_speed_base_raw,
            sub_a_rng_word,
        );
        sub_a.apply_shared_initializer_target_speed_write(1);
        let task_id = entity.actor_tasks.replace_prepared(
            ActorTaskSlot::Primary,
            prepared.map(ActorTaskRuntime::SharedRetarget),
        );
        let task_lease = MainBaseType9ExplodingTaskLease::issue(lease, task_id);
        let outcome = MainBaseType9DeathOutcome::ExplodingTaskPublished {
            entity_id,
            death_sound_id: LEVEL_ONE_TYPE9_DEATH_SOUND_ID,
            sub_a_rng_word,
            message,
            task_lease,
        };
        Ok(self.finish_main_base_abort_type9_death(entity_id, outcome))
    }

    fn finish_main_base_abort_type9_death(
        &self,
        entity_id: u32,
        outcome: MainBaseType9DeathOutcome,
    ) -> MainBaseType9DeathAdvance {
        match self.main_base_abort_successor_after_callback(entity_id) {
            Ok(next_actor) => MainBaseType9DeathAdvance::Advanced {
                outcome,
                next_actor,
            },
            Err(()) => MainBaseType9DeathAdvance::SuccessorUnavailableAfterCommit { outcome },
        }
    }

    /// Apply class 14's exact post-unwind owner transition for one surviving
    /// shared-retarget Primary task.
    ///
    /// The shared dispatcher owns elapsed time, RNG cadence, mover execution,
    /// pointer-distinct result mapping, and strict timeout comparison. This
    /// method owns only the authenticated style-0 -> style-1 transition and
    /// `FUN_0040C470` terminal initializer.
    pub fn complete_main_base_abort_type9_exploding_transition(
        &mut self,
        task_lease: MainBaseType9ExplodingTaskLease,
        request: SharedRetargetTransitionRequest,
    ) -> Result<MainBaseType9TerminalOutcome, MainBaseType9TerminalBlock> {
        validate_exploding_transition_request(task_lease, request)?;
        let entity_id = task_lease.actor().entity_id;
        let Some(entity_index) = self
            .entities
            .iter()
            .position(|entity| entity.id == entity_id)
        else {
            return Err(MainBaseType9TerminalBlock::EntityMissing);
        };
        let entity = &self.entities[entity_index];
        let expected_lease =
            observe_main_base_abort_actor(entity, self.allocation_generation).lease;
        if task_lease.actor() != expected_lease {
            return Err(MainBaseType9TerminalBlock::ActorLeaseMismatch {
                expected: expected_lease,
                actual: task_lease.actor(),
            });
        }
        if entity.actor_tasks.task_in_slot(ActorTaskSlot::Primary) != Some(task_lease.task_id()) {
            return Err(MainBaseType9TerminalBlock::PrimaryTaskMissingOrReplaced);
        }
        let Some(ActorTaskRuntime::SharedRetarget(task)) =
            entity.actor_tasks.state_in_slot(ActorTaskSlot::Primary)
        else {
            return Err(MainBaseType9TerminalBlock::WrongTaskFamily);
        };
        if task.lifetime_ms() != LEVEL_ONE_TYPE9_EXPLODING_LIFETIME_MS {
            return Err(MainBaseType9TerminalBlock::TransitionLifetimeMismatch {
                actual: task.lifetime_ms(),
            });
        }
        if task.elapsed_ms() != request.committed_prefix.elapsed_ms {
            return Err(MainBaseType9TerminalBlock::TransitionElapsedMismatch {
                expected: task.elapsed_ms(),
                actual: request.committed_prefix.elapsed_ms,
            });
        }
        if let SharedRetarget::Replaced {
            target_position_raw,
            ..
        } = request.committed_prefix.retarget
        {
            if task.private_state().target_position_raw != target_position_raw {
                return Err(MainBaseType9TerminalBlock::TransitionRetargetMismatch);
            }
        }
        let Some(wrapper) = entity.actor_tasks.wrapper_flags(task_lease.task_id()) else {
            return Err(MainBaseType9TerminalBlock::PrimaryTaskMissingOrReplaced);
        };
        if wrapper.in_callback {
            return Err(MainBaseType9TerminalBlock::TaskStillInCallback);
        }
        let context = match entity.current_behavior_context {
            RetailRuntimeValue::Known(Some(context)) => context,
            RetailRuntimeValue::Known(None) | RetailRuntimeValue::Unresolved => {
                return Err(MainBaseType9TerminalBlock::BehaviorContextMismatch)
            }
        };
        let terminal_context = exploding_person_terminal_context(context)
            .ok_or(MainBaseType9TerminalBlock::BehaviorContextMismatch)?;
        match entity
            .collision
            .state_flags_at_0x08
            .masked(LEVEL_ONE_TYPE9_OWNER_TRANSITION_SUPPRESSION_BIT)
        {
            RetailRuntimeValue::Known(0) => {}
            RetailRuntimeValue::Known(_) => {
                return Err(MainBaseType9TerminalBlock::OwnerTransitionSuppressed)
            }
            RetailRuntimeValue::Unresolved => {
                return Err(MainBaseType9TerminalBlock::OwnerTransitionSuppressionStateUnresolved)
            }
        }
        match entity
            .collision
            .state_flags_at_0x08
            .masked(DEFERRED_DESTROY_PENDING_STATE_BIT)
        {
            RetailRuntimeValue::Known(0) => {}
            RetailRuntimeValue::Known(_) => {
                return Err(MainBaseType9TerminalBlock::DeferredDestroyAlreadyPending)
            }
            RetailRuntimeValue::Unresolved => {
                return Err(MainBaseType9TerminalBlock::DeferredDestroyStateUnresolved)
            }
        }
        if self.pending_actor_deferred_destroy_ids.contains(&entity_id) {
            return Err(MainBaseType9TerminalBlock::DeferredDestroyAlreadyQueued);
        }

        let entity = &mut self.entities[entity_index];
        entity.current_behavior_context = RetailRuntimeValue::Known(Some(terminal_context));
        for slot in [
            ActorTaskSlot::Primary,
            ActorTaskSlot::Secondary,
            ActorTaskSlot::Tertiary,
        ] {
            entity.actor_tasks.clear_slot(slot);
        }
        entity.mark_actor_deferred_destroy_pending();
        self.queue_actor_deferred_destroy(entity_id);
        Ok(MainBaseType9TerminalOutcome {
            entity_id,
            reason: request.reason,
        })
    }

    /// Tick one receipt-authenticated class-38 Primary callback.
    ///
    /// `FUN_00401120` first accumulates whole milliseconds in task state
    /// `+0x2C`; `FUN_00405160` then applies `FUN_004013A0`. A nonzero remainder
    /// issues the next one-shot receipt. Exact completion stages the shared
    /// deferred destroy once and issues no replacement authority. The Primary
    /// wrapper survives callback unwind with a zero remainder; the following
    /// deferred entity sweep owns its eventual unlink and destruction.
    pub fn tick_main_base_abort_type54_sea_level(
        &mut self,
        receipt: MainBaseType54SeaLevelTickReceipt,
        terrain: &mut TerrainGrid,
        elapsed_micros: u32,
    ) -> Result<MainBaseType54SeaLevelTickOutcome, MainBaseType54SeaLevelTickFailure> {
        let (task_lease, sequence) = receipt.into_parts();
        let actor = task_lease.actor();
        let entity_id = actor.entity_id;
        let Some(entity_index) = self
            .entities
            .iter()
            .position(|entity| entity.id == entity_id)
        else {
            return Err(MainBaseType54SeaLevelTickFailure {
                receipt: MainBaseType54SeaLevelTickReceipt::issue(
                    actor,
                    task_lease.task_id(),
                    sequence,
                ),
                error: MainBaseType54SeaLevelTickBlock::EntityMissing,
            });
        };
        let entity = &self.entities[entity_index];
        let expected_actor =
            observe_main_base_abort_actor(entity, self.allocation_generation).lease;
        let fail = |error| MainBaseType54SeaLevelTickFailure {
            receipt: MainBaseType54SeaLevelTickReceipt::issue(
                actor,
                task_lease.task_id(),
                sequence,
            ),
            error,
        };
        if actor != expected_actor {
            return Err(fail(MainBaseType54SeaLevelTickBlock::ActorLeaseMismatch {
                expected: expected_actor,
                actual: actor,
            }));
        }
        if entity.actor_tasks.task_in_slot(ActorTaskSlot::Primary) != Some(task_lease.task_id()) {
            return Err(fail(
                MainBaseType54SeaLevelTickBlock::PrimaryTaskMissingOrReplaced,
            ));
        }
        let Some(task_runtime) = entity.actor_tasks.state_in_slot(ActorTaskSlot::Primary) else {
            return Err(fail(
                MainBaseType54SeaLevelTickBlock::PrimaryTaskMissingOrReplaced,
            ));
        };
        let ActorTaskRuntime::ChangeSeaLevel(task_state) = task_runtime else {
            return Err(fail(MainBaseType54SeaLevelTickBlock::WrongTaskFamily));
        };
        if task_state.next_tick_sequence() != sequence {
            return Err(fail(
                MainBaseType54SeaLevelTickBlock::ReceiptSequenceMismatch {
                    expected: task_state.next_tick_sequence(),
                    actual: sequence,
                },
            ));
        }
        match entity
            .collision
            .state_flags_at_0x08
            .masked(DEFERRED_DESTROY_PENDING_STATE_BIT)
        {
            RetailRuntimeValue::Known(0) => {}
            RetailRuntimeValue::Known(_) => {
                return Err(fail(
                    MainBaseType54SeaLevelTickBlock::DeferredDestroyAlreadyPending,
                ))
            }
            RetailRuntimeValue::Unresolved => {
                return Err(fail(
                    MainBaseType54SeaLevelTickBlock::DeferredDestroyStateUnresolved,
                ))
            }
        }
        if self.pending_actor_deferred_destroy_ids.contains(&entity_id) {
            return Err(fail(
                MainBaseType54SeaLevelTickBlock::DeferredDestroyAlreadyQueued,
            ));
        }

        let visit = ActorTaskVisit {
            slot: ActorTaskSlot::Primary,
            task_id: task_lease.task_id(),
        };
        let entity = &mut self.entities[entity_index];
        let Some(elapsed_ms) = entity.actor_tasks.begin_exact_visit_with(visit, |runtime| {
            let ActorTaskRuntime::ChangeSeaLevel(state) = runtime else {
                unreachable!("preflight authenticated the exact Change-Sea-Level task")
            };
            state.accumulate_elapsed_prefix(elapsed_micros)
        }) else {
            return Err(fail(MainBaseType54SeaLevelTickBlock::TaskVisitUnavailable));
        };

        // FUN_00405160 and its terrain write execute only after the wrapper
        // has entered the callback phase. Completion also stages the entity
        // flag in this phase; wrapper unwind remains the final owner action.
        let runtime = entity
            .actor_tasks
            .exact_callback_state_mut(visit)
            .expect("an exact visit must expose its authenticated in-callback state");
        let ActorTaskRuntime::ChangeSeaLevel(state) = runtime else {
            unreachable!("preflight authenticated the exact Change-Sea-Level task")
        };
        let complete = state.tick_transition(terrain, elapsed_micros);
        if !complete {
            state.advance_tick_sequence();
        }
        let remaining_delta_raw = state.remaining_delta_raw();
        let next_sequence = state.next_tick_sequence();

        if complete {
            debug_assert_eq!(
                entity
                    .actor_tasks
                    .wrapper_flags(task_lease.task_id())
                    .map(|flags| flags.in_callback),
                Some(true)
            );
            entity.mark_actor_deferred_destroy_pending();
            let final_sea_level_raw = terrain.header[0];
            // Both the state-word write and global deferred-count/queue side
            // belong to FUN_00410B70 inside FUN_00405160's callback.
            self.queue_actor_deferred_destroy(entity_id);
            let entity = &mut self.entities[entity_index];
            debug_assert_eq!(
                entity
                    .actor_tasks
                    .wrapper_flags(task_lease.task_id())
                    .map(|flags| flags.in_callback),
                Some(true)
            );
            let survived = entity.actor_tasks.finish_exact_visit(visit);
            debug_assert!(survived);
            Ok(MainBaseType54SeaLevelTickOutcome::DeferredDestroyStaged {
                entity_id,
                elapsed_ms,
                final_sea_level_raw,
            })
        } else {
            let survived = entity.actor_tasks.finish_exact_visit(visit);
            debug_assert!(survived);
            Ok(MainBaseType54SeaLevelTickOutcome::Continuing {
                entity_id,
                elapsed_ms,
                remaining_delta_raw,
                next_receipt: MainBaseType54SeaLevelTickReceipt::issue(
                    actor,
                    task_lease.task_id(),
                    next_sequence,
                ),
            })
        }
    }

    fn finish_main_base_abort_quiet_death(
        &self,
        entity_id: u32,
        outcome: MainBaseAbortQuietDeathOutcome,
    ) -> MainBaseAbortQuietDeathAdvance {
        match self.main_base_abort_successor_after_callback(entity_id) {
            Ok(next_actor) => MainBaseAbortQuietDeathAdvance::Advanced {
                outcome,
                next_actor,
            },
            Err(()) => MainBaseAbortQuietDeathAdvance::SuccessorUnavailableAfterCommit { outcome },
        }
    }

    fn finish_main_base_abort_type93_death(
        &self,
        entity_id: u32,
        outcome: MainBaseType93DeathOutcome,
    ) -> MainBaseType93DeathAdvance {
        match self.main_base_abort_successor_after_callback(entity_id) {
            Ok(next_actor) => MainBaseType93DeathAdvance::Advanced {
                outcome,
                next_actor,
            },
            Err(()) => MainBaseType93DeathAdvance::SuccessorUnavailableAfterCommit { outcome },
        }
    }

    pub(crate) fn main_base_abort_successor_after_callback(
        &self,
        entity_id: u32,
    ) -> Result<Option<MainBaseAbortActorObservation>, ()> {
        let entity_index = self
            .entities
            .iter()
            .position(|entity| entity.id == entity_id)
            .ok_or(())?;
        Ok(self
            .entities
            .get(entity_index + 1)
            .map(|entity| observe_main_base_abort_actor(entity, self.allocation_generation)))
    }

    /// Execute only the metadata-authenticated `FUN_0041CF90` alternate route.
    ///
    /// Exact authored absence of Sub-N is a no-op. Present Sub-N is admitted
    /// only through the retained loader-owned runtime. Retail writes the
    /// timer before testing `+0x4C`, so a known-false constructor gate needs no
    /// later descriptor lookup and commits with zero publications. A true gate
    /// is descriptor-preflighted before mutation: this deliberately fail-closed
    /// host boundary avoids returning a partially committed timer when the
    /// external terrain transaction cannot be authenticated. The ordinary
    /// death family remains outside this bounded adapter.
    fn commit_main_base_abort_alternate_cleanup(
        &mut self,
        lease: MainBaseAbortActorLease,
        effects: &mut impl MainBaseAbortAlternateCleanupEffects,
    ) -> Result<MainBaseAbortAlternateCleanupOutcome, MainBaseAbortAlternateCleanupBlock> {
        let entity_id = lease.entity_id;
        let Some(entity_index) = self
            .entities
            .iter()
            .position(|entity| entity.id == entity_id)
        else {
            return Err(MainBaseAbortAlternateCleanupBlock::EntityMissing);
        };

        let entity = &self.entities[entity_index];
        let expected_lease =
            observe_main_base_abort_actor(entity, self.allocation_generation).lease;
        if lease != expected_lease {
            return Err(MainBaseAbortAlternateCleanupBlock::ActorLeaseMismatch {
                expected: expected_lease,
                actual: lease,
            });
        }
        let route = classify_main_base_abort_actor(MainBaseAbortActorFacts {
            entity_id: entity.id,
            entity_type: entity.entity_type,
            capability_flags: entity.capability_flags,
            state_flags: entity
                .collision
                .state_flags_at_0x08
                .masked(ORDINARY_DEATH_STATE_SKIP_MASK),
        });
        if route != (MainBaseAbortActorRoute::AlternateCleanup { entity_id }) {
            return Err(MainBaseAbortAlternateCleanupBlock::NotAlternateRoute(route));
        }

        let entity_type = entity.entity_type;
        let metadata = self
            .type_metadata
            .get(entity_type as usize)
            .ok_or(MainBaseAbortAlternateCleanupBlock::TypeMetadataUnavailable)?;
        let RetailRuntimeValue::Known(topology) = metadata.common_mover_topology else {
            return Err(MainBaseAbortAlternateCleanupBlock::ComponentTopologyUnresolved);
        };
        let runtime_before = match (topology.sub_n, entity.sub_n_runtime) {
            (false, RetailRuntimeValue::Known(None)) if metadata.sub_n_payload.is_none() => {
                return Ok(MainBaseAbortAlternateCleanupOutcome::ExactNoSubN {
                    entity_id,
                    entity_type,
                });
            }
            (true, RetailRuntimeValue::Known(Some(runtime))) => runtime,
            (_, RetailRuntimeValue::Unresolved) => {
                return Err(MainBaseAbortAlternateCleanupBlock::SubNRuntimeCustodyUnavailable);
            }
            (false, RetailRuntimeValue::Known(None | Some(_)))
            | (true, RetailRuntimeValue::Known(None)) => {
                return Err(MainBaseAbortAlternateCleanupBlock::SubNDescriptorRuntimeMismatch);
            }
        };
        let descriptor_attachment = match runtime_before.terrain_patch_present() {
            RetailRuntimeValue::Unresolved => {
                return Err(MainBaseAbortAlternateCleanupBlock::SubNRuntimeCustodyUnavailable);
            }
            RetailRuntimeValue::Known(false) => None,
            RetailRuntimeValue::Known(true) => {
                let payload = metadata
                    .sub_n_payload
                    .ok_or(MainBaseAbortAlternateCleanupBlock::SubNDescriptorUnavailable)?;
                let descriptor_attachment = sub_n_descriptor_attachment(payload);
                if runtime_before.descriptor_attachment_at_birth()
                    != RetailRuntimeValue::Known(descriptor_attachment)
                {
                    return Err(MainBaseAbortAlternateCleanupBlock::SubNDescriptorRuntimeMismatch);
                }
                Some(descriptor_attachment)
            }
        };
        let source_position_raw = entity.position_raw();
        let entity = &mut self.entities[entity_index];
        let RetailRuntimeValue::Known(Some(runtime)) = &mut entity.sub_n_runtime else {
            unreachable!("Sub-N custody was authenticated above")
        };
        let RetailRuntimeValue::Known(commit) = runtime
            .commit_main_base_abort_alternate_cleanup(source_position_raw, descriptor_attachment)
        else {
            return Err(MainBaseAbortAlternateCleanupBlock::SubNRuntimeCustodyUnavailable);
        };
        let runtime = *runtime;

        let terrain_publications = match commit.cells_x_major {
            Some(cells) => {
                let count = cells.len();
                for cell in cells {
                    effects.clear_and_publish_old_terrain_attribute(cell);
                }
                count
            }
            None => 0,
        };
        Ok(MainBaseAbortAlternateCleanupOutcome::Applied {
            entity_id,
            runtime,
            terrain_publications,
        })
    }

    /// Execute the alternate callback and sample its intrusive-list successor
    /// only after the complete callback has returned.
    pub fn apply_main_base_abort_alternate_cleanup(
        &mut self,
        lease: MainBaseAbortActorLease,
        effects: &mut impl MainBaseAbortAlternateCleanupEffects,
    ) -> Result<MainBaseAbortAlternateCleanupAdvance, MainBaseAbortAlternateCleanupBlock> {
        let entity_id = lease.entity_id;
        let outcome = self.commit_main_base_abort_alternate_cleanup(lease, effects)?;
        Ok(
            match self.main_base_abort_successor_after_callback(entity_id) {
                Ok(next_actor) => MainBaseAbortAlternateCleanupAdvance::Advanced {
                    outcome,
                    next_actor,
                },
                Err(()) => MainBaseAbortAlternateCleanupAdvance::SuccessorUnavailableAfterCommit {
                    outcome,
                },
            },
        )
    }

    /// Apply type 46's dying model-slot selection (`0x4000` state).
    ///
    /// Preserve the infection bit while selecting native dying slot1 or3.
    /// The first-world rows happen to share model67; their selector bits remain
    /// distinct, so a missing authored slot cannot use its sibling as fallback.
    pub fn switch_player_to_dying_model(&mut self) -> Option<usize> {
        let player = self.player_mut()?;
        let RetailRuntimeValue::Known(high) = player
            .collision
            .state_flags_at_0x08
            .masked(ACTIVE_MODEL_SLOT_HIGH_STATE_BIT)
        else {
            return None;
        };
        player.select_active_model_slot(if high == 0 { 1 } else { 3 })
    }

    /// Remove the dead player and allocations directly attached to it.
    ///
    /// Retail's `"Dead:"` initializer also kills owned subordinate entities.
    /// The entity-owned Sub-J array is the exact ordered teardown authority;
    /// inverse relation backlinks cannot add or recover membership.
    pub fn remove_player_and_attached_entities(&mut self) -> bool {
        let Some(player_id) = self.player_id else {
            return false;
        };
        let attachment_ids = match self.player().map(|player| &player.sub_j_attachment_runtime) {
            Some(RetailRuntimeValue::Known(Some(runtime))) => runtime.ordered_entity_ids().to_vec(),
            Some(RetailRuntimeValue::Known(None)) => Vec::new(),
            Some(RetailRuntimeValue::Unresolved) | None => return false,
        };
        let mut removed_ids = vec![player_id];
        removed_ids.extend(attachment_ids);
        self.player_id = None;
        self.remove_live_entity_ids(&removed_ids);
        self.beam_timer_ms = 0;
        self.cargo_drop_proxies.retain(|proxy| {
            self.entities
                .iter()
                .any(|entity| entity.id == proxy.proxy_id || entity.id == proxy.cargo_id)
        });
        true
    }

    pub fn iter(&self) -> impl Iterator<Item = &Entity> {
        self.entities
            .iter()
            .filter(|entity| entity.attached_to.is_none())
    }

    /// Iterate the complete allocation, including cargo hidden from ordinary
    /// world rendering and collision scans.
    pub fn iter_all(&self) -> impl Iterator<Item = &Entity> {
        self.entities.iter()
    }

    /// `FUN_0042E210` live-list capability census used by overlay-51 selectors
    /// 3/5/6. Walks the full allocation, including cargo. Sub-M `+0x68` is
    /// added into `+0x1A8` without the dying gate; capability buckets still
    /// exclude dying bit `0x4000` and zero `+0x08`.
    pub fn fun_0042e210_capability_census(&self) -> Fun0042e210CapabilityCensus {
        fun_0042e210_capability_census(self.iter_all().map(|entity| Fun0042e210EntitySample {
            capability: entity.capability_flags,
            state: entity.collision.state_flags_at_0x08,
            sub_m_native_count_raw: match entity.base_factory_runtime {
                RetailRuntimeValue::Known(Some(runtime)) => Some(runtime.sub_m_native_count_raw()),
                RetailRuntimeValue::Known(None) | RetailRuntimeValue::Unresolved => None,
            },
        }))
    }

    /// Publish leftover `FUN_0044C920` follow positions for sound-11 owners
    /// that did not visit `FUN_00412DA0` this frame.
    pub fn publish_remaining_constructor_sound_follow_positions(&mut self) {
        for entity in &mut self.entities {
            if entity.collision.constructor_sound_follow_published {
                entity.collision.constructor_sound_follow_published = false;
                continue;
            }
            crate::entity_positional_audio::publish_constructor_sound_follow_position(entity);
            entity.collision.constructor_sound_follow_published = false;
        }
    }

    /// Borrow the immutable construction record for one cumulative entity
    /// type. Live adapters use this only to authenticate component topology;
    /// the metadata is never a substitute for per-allocation provenance.
    pub(crate) fn type_runtime_metadata(
        &self,
        entity_type: u32,
    ) -> Option<&EntityTypeRuntimeMetadata> {
        self.type_metadata.get(entity_type as usize)
    }

    #[cfg(test)]
    pub(crate) fn type_runtime_metadata_mut_for_test(
        &mut self,
        entity_type: u32,
    ) -> Option<&mut EntityTypeRuntimeMetadata> {
        self.type_metadata.get_mut(entity_type as usize)
    }

    /// Preflight retail/demo-matched `FUN_004180F0` without consuming its
    /// singleton behavior-selector draw or changing the live list.
    pub(crate) fn preflight_type17_missing_relation_materialiser(
        &self,
        subject_id: u32,
        expected_relation_owner_id: Option<u32>,
        terrain: &TerrainGrid,
        type_default_state_flags_at_0xc0: u32,
    ) -> Result<Type17MissingRelationMaterialiserPlan, Type17MissingRelationMaterialiserBlock> {
        let subject = self
            .entities
            .iter()
            .find(|entity| entity.id == subject_id)
            .ok_or(Type17MissingRelationMaterialiserBlock::SubjectUnavailable)?;
        if subject.attached_to != expected_relation_owner_id {
            return Err(Type17MissingRelationMaterialiserBlock::RelationLeaseChanged);
        }
        if let Some(relation_owner_id) = expected_relation_owner_id {
            if self
                .entities
                .iter()
                .any(|entity| entity.id == relation_owner_id)
            {
                return Err(
                    Type17MissingRelationMaterialiserBlock::RelationOwnerPresent {
                        relation_owner_id,
                    },
                );
            }
        }
        match subject
            .collision
            .state_flags_at_0x08
            .masked(REMOTE_OWNED_STATE_BIT | 0x0000_1000)
        {
            RetailRuntimeValue::Known(0x0000_1000) => {}
            RetailRuntimeValue::Known(_) | RetailRuntimeValue::Unresolved => {
                return Err(Type17MissingRelationMaterialiserBlock::SubjectStateUnresolvedOrRemote)
            }
        }
        let metadata = self
            .type_metadata
            .get(CARGO_DROP_PROXY_ENTITY_TYPE as usize)
            .ok_or(Type17MissingRelationMaterialiserBlock::MissingType93Metadata)?;
        let initial_behavior = authenticate_type93_materialiser_metadata(metadata)
            .ok_or(Type17MissingRelationMaterialiserBlock::UnexpectedType93Metadata)?;
        let [x_raw, _, z_raw] = subject.position_raw();
        let target_raw = [x_raw, terrain.bilinear_height_raw(x_raw, z_raw), z_raw];
        let proxy_initial_state = resolve_entity_initializer_with_selected_behavior(
            EntityInitializerRequest {
                metadata: Some(metadata),
                spawn_param: 0,
                authored_position_raw: target_raw,
                terrain: Some(terrain),
                resource_domain: ResourceDomainRelation::Current,
            },
            Some(initial_behavior),
        )
        .state_flags;
        Ok(Type17MissingRelationMaterialiserPlan {
            subject_id,
            expected_relation_owner_id,
            proxy_id: self.next_entity_id,
            target_raw,
            initial_behavior,
            proxy_initial_state,
            type_default_state_flags_at_0xc0,
        })
    }

    /// Publish a preflighted Type-93 allocation, then perform retail's
    /// release-and-reattach suffix. The only fallible retail boundary is the
    /// allocation itself; bounded Rust storage makes that transaction
    /// infallible after this stale-lease revalidation.
    pub(crate) fn commit_type17_missing_relation_materialiser(
        &mut self,
        attempt: Type17MaterialiserAttempt,
    ) -> bool {
        let Type17MaterialiserAttempt {
            plan,
            construction_stamp_at_0xb4,
        } = attempt;
        let Some(subject_index) = self
            .entities
            .iter()
            .position(|entity| entity.id == plan.subject_id)
        else {
            return false;
        };
        let subject = &self.entities[subject_index];
        if self.next_entity_id != plan.proxy_id
            || subject.attached_to != plan.expected_relation_owner_id
            || !matches!(
                subject
                    .collision
                    .state_flags_at_0x08
                    .masked(REMOTE_OWNED_STATE_BIT | 0x0000_1000),
                RetailRuntimeValue::Known(0x0000_1000)
            )
            || plan
                .expected_relation_owner_id
                .is_some_and(|owner_id| self.entities.iter().any(|entity| entity.id == owner_id))
        {
            return false;
        }
        let Some(metadata) = self
            .type_metadata
            .get(CARGO_DROP_PROXY_ENTITY_TYPE as usize)
            .cloned()
        else {
            return false;
        };
        if authenticate_type93_materialiser_metadata(&metadata) != Some(plan.initial_behavior) {
            return false;
        }

        if subject.collision.active_model_slot() == RetailRuntimeValue::Unresolved {
            return false;
        }
        let Some(proxy) = build_type93_materialiser_entity(
            &metadata,
            plan.proxy_id,
            plan.target_raw,
            plan.initial_behavior,
            plan.proxy_initial_state,
            construction_stamp_at_0xb4,
        ) else {
            return false;
        };

        let materialiser = self.publish_constructed_type93_materialiser(proxy);
        let subject = &mut self.entities[subject_index];
        subject.collision.state_flags_at_0x08 = relation_release_state_word_after(
            subject.collision.state_flags_at_0x08,
            plan.type_default_state_flags_at_0xc0,
        );
        subject.collision.default_state_flags_at_0xc8 =
            RetailRuntimeValue::Known(plan.type_default_state_flags_at_0xc0);
        subject.attached_to = None;
        self.commit_type93_materialiser_output_link(
            plan.proxy_id,
            plan.subject_id,
            materialiser.construction,
            Type93LifecyclePurpose::Type17MissingRelation {
                type_default_state_flags_at_0xc0: plan.type_default_state_flags_at_0xc0,
            },
            // The Type17 Class12 graph has no native person/worker CD70
            // attachment callback; its relation projection is sufficient.
            |_| {},
        )
    }

