    #[test]
    fn sub_h_construction_uses_authored_count_and_surface_policy() {
        use crate::sub_h_external_frame::SubHSurfacePolicy;
        for count in [0, 1, 6, 8, 16] {
            let metadata = sub_h_metadata(count);
            let RetailRuntimeValue::Known(Some(runtime)) =
                sub_h_external_frame_runtime_from_constructor(Some(&metadata))
            else {
                panic!("authored Sub-H did not construct")
            };
            assert_eq!(runtime.cursor(), 0);
            assert!(runtime.is_enabled());
            assert_eq!(runtime.surface_policy(), SubHSurfacePolicy::Terrain);
            assert_eq!(runtime.records().len(), count);
            assert!(runtime
                .records()
                .iter()
                .all(|record| *record == Default::default()));
        }
        for mode in [0, 1, -1, -128, 127] {
            let mut metadata = sub_h_metadata(6);
            let RetailRuntimeValue::Known(mut topology) = metadata.common_mover_topology else {
                unreachable!()
            };
            topology.sub_c = true;
            metadata.common_mover_topology = RetailRuntimeValue::Known(topology);
            metadata.sub_c_lift_descriptor = RetailRuntimeValue::Known(Some(SubCLiftDescriptor {
                surface_mode_raw: mode,
                ..INTRO2_TYPE26_SUB_C
            }));
            let RetailRuntimeValue::Known(Some(runtime)) =
                sub_h_external_frame_runtime_from_constructor(Some(&metadata))
            else {
                panic!("authored surface policy did not construct")
            };
            assert_eq!(
                runtime.surface_policy(),
                if mode == 0 {
                    SubHSurfacePolicy::Terrain
                } else {
                    SubHSurfacePolicy::TerrainAndWater
                }
            );
        }
    }

    #[test]
    fn sub_h_construction_keeps_missing_inconsistent_and_absent_data_distinct() {
        let mut absent = EntityTypeRuntimeMetadata::default();
        absent.common_mover_topology = RetailRuntimeValue::Known(Default::default());
        absent.sub_h_external_frame_descriptor = RetailRuntimeValue::Known(None);
        assert_eq!(
            sub_h_external_frame_runtime_from_constructor(Some(&absent)),
            RetailRuntimeValue::Known(None)
        );
        absent.sub_h_external_frame_descriptor = RetailRuntimeValue::Unresolved;
        assert_eq!(
            sub_h_external_frame_runtime_from_constructor(Some(&absent)),
            RetailRuntimeValue::Known(None),
            "known component absence needs no descriptor decoding"
        );
        assert_eq!(
            sub_h_external_frame_runtime_from_constructor(None),
            RetailRuntimeValue::Unresolved
        );
        assert_eq!(
            sub_h_external_frame_runtime_from_constructor(Some(&sub_h_metadata(17))),
            RetailRuntimeValue::Unresolved
        );
        let mut missing_c = sub_h_metadata(6);
        missing_c.sub_c_lift_descriptor = RetailRuntimeValue::Unresolved;
        assert_eq!(
            sub_h_external_frame_runtime_from_constructor(Some(&missing_c)),
            RetailRuntimeValue::Unresolved
        );
        let mut mismatched_c = sub_h_metadata(6);
        mismatched_c.sub_c_lift_descriptor = RetailRuntimeValue::Known(Some(INTRO2_TYPE26_SUB_C));
        assert_eq!(
            sub_h_external_frame_runtime_from_constructor(Some(&mismatched_c)),
            RetailRuntimeValue::Unresolved
        );
        let mut mismatched_h = sub_h_metadata(6);
        mismatched_h.common_mover_topology = RetailRuntimeValue::Known(Default::default());
        assert_eq!(
            sub_h_external_frame_runtime_from_constructor(Some(&mismatched_h)),
            RetailRuntimeValue::Unresolved
        );
    }

    #[test]
    fn exact_sub_j_constructor_starts_empty_with_authored_capacity() {
        let mut metadata = EntityTypeRuntimeMetadata::default();
        set_sub_j_descriptor(&mut metadata, 1);
        let RetailRuntimeValue::Known(Some(runtime)) =
            sub_j_attachment_runtime_from_constructor(Some(&metadata), None, None)
        else {
            panic!("exact Sub-J descriptor did not construct its runtime")
        };
        assert_eq!(runtime.authored_slot_count(), 1);
        assert_eq!(runtime.capacity(), 1);
        assert!(runtime.is_empty());
        assert_eq!(runtime.policy_raw_at_0x0c(), 0);

        metadata.sub_j_attachment_descriptor = RetailRuntimeValue::Known(None);
        assert_eq!(
            sub_j_attachment_runtime_from_constructor(Some(&metadata), None, None),
            RetailRuntimeValue::Known(None)
        );
        assert_eq!(
            sub_j_attachment_runtime_from_constructor(
                Some(&EntityTypeRuntimeMetadata::default()),
                None,
                None,
            ),
            RetailRuntimeValue::Unresolved
        );
    }

    #[test]
    fn metadata_backed_type17_entity_owns_the_ordered_sub_j_runtime() {
        let level = make_level(&[17]);
        let mut metadata = vec![EntityTypeRuntimeMetadata::default(); 18];
        set_sub_j_descriptor(&mut metadata[17 as usize], 1);
        let manager = EntityManager::from_level_with_type_metadata(&level, &metadata, None);
        let type17 = manager.iter_all().next().expect("type-17 allocation");
        let RetailRuntimeValue::Known(Some(runtime)) = &type17.sub_j_attachment_runtime else {
            panic!("type-17 allocation lost its exact Sub-J runtime")
        };
        assert_eq!(runtime.capacity(), 1);
        assert!(runtime.ordered_entity_ids().is_empty());
        assert_eq!(runtime.policy_raw_at_0x0c(), 0);
    }

    #[test]
    fn binary_heading_inverse_preserves_boundaries_and_wraps() {
        for raw in [0x0000, 0x0fff, 0x1000, 0x7fff, 0x8000, 0xefff, 0xffff] {
            assert_eq!(
                radians_to_binary_angle(binary_angle_to_radians(raw)),
                raw,
                "heading {raw:04x}"
            );
        }
        assert_eq!(radians_to_binary_angle(std::f32::consts::TAU), 0);
        assert_eq!(
            radians_to_binary_angle(-std::f32::consts::TAU / 65_536.0),
            0xffff
        );
    }

    #[test]
    fn level_constructor_retains_all_authored_rotation_words() {
        let mut level = make_level(&[17]);
        level.entities[0].rotation = [0xd7b1, 0x8123, 0x7fed];

        let manager = EntityManager::from_level(&level, &[[1, 0, 0, 0]; 18], None);
        let entity = manager.iter().next().expect("authored entity");

        assert_eq!(entity.heading_raw(), 0xd7b1);
        assert_eq!(
            entity.rotation_heading_pitch_roll_raw(),
            [0xd7b1_u16 as i16, 0x8123_u16 as i16, 0x7fed]
        );
    }

    #[test]
    fn contiguous_rotation_commit_preserves_wrapping_words_and_heading_compatibility() {
        let mut entity = Entity::unresolved_port_entity(1, EntityKind::Unknown(17), 17);
        entity.set_rotation_heading_pitch_roll_raw([i16::MAX, i16::MIN, -1]);

        let deltas = [1_i16, -1, 2];
        let wrapped = std::array::from_fn(|axis| {
            entity.rotation_heading_pitch_roll_raw()[axis].wrapping_add(deltas[axis])
        });
        entity.set_rotation_heading_pitch_roll_raw(wrapped);

        assert_eq!(wrapped, [i16::MIN, i16::MAX, 1]);
        assert_eq!(entity.rotation_heading_pitch_roll_raw(), wrapped);
        assert_eq!(entity.heading_raw(), 0x8000);
        assert_eq!(entity.heading, binary_angle_to_radians(0x8000));

        entity.heading = binary_angle_to_radians(0x1234);
        assert_eq!(
            entity.rotation_heading_pitch_roll_raw(),
            [0x1234, i16::MAX, 1],
            "direct compatibility heading writes remain the live heading authority"
        );
    }

    #[test]
    fn attached_mass_uses_each_owners_authoritative_list_without_recursing() {
        let mut owner = Entity::unresolved_port_entity(10, EntityKind::Unknown(17), 17);
        owner.mass_raw = 999;
        let mut owner_runtime =
            SubJAttachmentRuntime::from_descriptor(&sub_j_descriptor(2)).unwrap();
        owner_runtime.append(12).unwrap();
        owner_runtime.append(11).unwrap();
        owner.sub_j_attachment_runtime = RetailRuntimeValue::Known(Some(owner_runtime));
        let mut first_child = Entity::unresolved_port_entity(11, EntityKind::Unknown(61), 61);
        first_child.mass_raw = 99;
        first_child.attached_to = Some(owner.id);
        let mut child_runtime =
            SubJAttachmentRuntime::from_descriptor(&sub_j_descriptor(1)).unwrap();
        child_runtime.append(13).unwrap();
        first_child.sub_j_attachment_runtime = RetailRuntimeValue::Known(Some(child_runtime));
        let mut second_child = Entity::unresolved_port_entity(12, EntityKind::Unknown(61), 61);
        second_child.mass_raw = 51;
        second_child.attached_to = Some(owner.id);
        let mut grandchild = Entity::unresolved_port_entity(13, EntityKind::Unknown(61), 61);
        grandchild.mass_raw = 200;
        grandchild.attached_to = Some(first_child.id);
        let mut unrelated = Entity::unresolved_port_entity(14, EntityKind::Unknown(61), 61);
        unrelated.sub_j_attachment_runtime = RetailRuntimeValue::Known(None);
        let manager = EntityManager::from_entities_for_test(vec![
            owner,
            first_child,
            second_child,
            grandchild,
            unrelated,
        ]);

        assert_eq!(manager.attached_mass_for_entity(10), 150);
        assert_eq!(manager.attached_mass_for_entity(11), 200);
        assert_eq!(manager.attached_mass_for_entity(14), 0);
    }

