    fn actor_animation_state(manager: &EntityManager, entity_id: u32) -> (u8, i32, u16) {
        let entity = manager
            .iter_all()
            .find(|entity| entity.id == entity_id)
            .expect("the animation fixture allocation remains live");
        let RetailRuntimeValue::Known(Some(controller)) = entity.actor_animation_runtime else {
            panic!("the animation fixture must retain an exact Sub-I controller")
        };
        (
            controller.phase(),
            controller.countdown_millis(),
            controller.output(),
        )
    }

    #[test]
    fn exact_animation_claim_excludes_only_claimed_and_advances_unclaimed_actor() {
        let level = make_level(&[9, 9]);
        let metadata = exact_type9_animation_metadata();
        let mut manager = EntityManager::from_level_with_type_metadata(&level, &metadata, None);
        let entity_ids = manager
            .iter_all()
            .map(|entity| entity.id)
            .collect::<Vec<_>>();
        assert_eq!(entity_ids.len(), 2);
        let claim = manager
            .main_base_abort_actor_observation(entity_ids[0])
            .expect("the claimed actor must be live")
            .lease;

        manager.advance_unclaimed_actor_animations(20_000, &[claim]);

        assert_eq!(actor_animation_state(&manager, entity_ids[0]), (0, 0, 0));
        let (phase, countdown, _) = actor_animation_state(&manager, entity_ids[1]);
        assert_eq!((phase, countdown), (1, 80));
    }

    #[test]
    fn same_entity_id_from_a_different_allocation_domain_is_not_excluded() {
        let level = make_level(&[9]);
        let metadata = exact_type9_animation_metadata();
        let stale_manager = EntityManager::from_level_with_type_metadata(&level, &metadata, None);
        let mut current_manager =
            EntityManager::from_level_with_type_metadata(&level, &metadata, None);
        let entity_id = stale_manager.iter_all().next().unwrap().id;
        assert_eq!(current_manager.iter_all().next().unwrap().id, entity_id);
        let stale = stale_manager
            .main_base_abort_actor_observation(entity_id)
            .unwrap()
            .lease;
        let current = current_manager
            .main_base_abort_actor_observation(entity_id)
            .unwrap()
            .lease;
        assert_ne!(stale.allocation_identity, current.allocation_identity);

        current_manager.advance_unclaimed_actor_animations(20_000, &[stale]);

        let (phase, countdown, _) = actor_animation_state(&current_manager, entity_id);
        assert_eq!((phase, countdown), (1, 80));
    }

    #[test]
    fn neutral_animation_fallback_preserves_newly_published_behavior_modes() {
        let level = make_level(&[9, 9, 9]);
        let metadata = exact_type9_animation_metadata();
        let mut manager = EntityManager::from_level_with_type_metadata(&level, &metadata, None);
        for (index, entity) in manager.entities.iter_mut().enumerate() {
            entity.velocity = [1., 2., 3.];
            let RetailRuntimeValue::Known(Some(animation)) = &mut entity.actor_animation_runtime
            else {
                panic!("exact Sub-I fixture");
            };
            match index {
                0 => animation.apply_attract_attention_forced_stop(),
                1 => animation.apply_relation_attach(42),
                2 => animation.apply_exploding_person_reset(),
                _ => unreachable!(),
            }
        }
        let before: Vec<_> = manager
            .iter_all()
            .map(|entity| (entity.actor_animation_runtime, entity.velocity))
            .collect();
        manager.advance_unclaimed_actor_animations(20_000, &[]);
        assert_eq!(
            manager
                .iter_all()
                .map(|entity| (entity.actor_animation_runtime, entity.velocity))
                .collect::<Vec<_>>(),
            before
        );
    }

    #[test]
    fn non_actor_and_inactive_animation_state_remain_unchanged() {
        let descriptor = ActorAnimationDescriptor {
            capability_bit_3_sound_id: 72,
            capability_mask_0x201_sound_id: 0,
            attention_stop_sound_id: 72,
            variable_binding: 1,
            frames_per_direction: 4,
        };
        let unresolved = Entity::unresolved_port_entity(70, EntityKind::Unknown(70), 70);
        let mut exact_absent = Entity::unresolved_port_entity(71, EntityKind::Unknown(71), 71);
        exact_absent.actor_animation_runtime = RetailRuntimeValue::Known(None);
        let mut inactive = Entity::unresolved_port_entity(72, EntityKind::Unknown(9), 9);
        inactive.actor_animation_runtime = RetailRuntimeValue::Known(Some(
            ActorAnimationController::from_descriptor(descriptor).unwrap(),
        ));
        inactive.active = false;
        let mut manager =
            EntityManager::from_entities_for_test(vec![unresolved, exact_absent, inactive]);
        let before = manager
            .iter_all()
            .map(|entity| entity.actor_animation_runtime)
            .collect::<Vec<_>>();

        manager.advance_unclaimed_actor_animations(20_000, &[]);

        assert_eq!(
            manager
                .iter_all()
                .map(|entity| entity.actor_animation_runtime)
                .collect::<Vec<_>>(),
            before
        );
    }

    #[test]
    fn exact_type_9_sub_i_publishes_selector_one_and_compatibility_metadata_does_not() {
        let mut level = make_level(&[9]);
        level.entities[0].rotation[0] = 0xb000;
        let metadata = exact_type9_animation_metadata();

        let mut exact = EntityManager::from_level_with_type_metadata(&level, &metadata, None);
        exact.advance_actor_animations(20_000);
        let entity = exact.iter().next().unwrap();
        assert_eq!(entity.heading_raw(), 0xb000);
        assert_eq!(entity.presentation_anim_vars(1).dynamic[1], 1);

        let mut compatibility = EntityManager::from_level(&level, &[[1, 0, 0, 0]; 10], None);
        compatibility.advance_actor_animations(20_000);
        let entity = compatibility.iter().next().unwrap();
        assert_eq!(
            entity.actor_animation_runtime,
            RetailRuntimeValue::Unresolved
        );
        assert_eq!(entity.presentation_anim_vars(1).dynamic[1], 0);
    }

