    fn make_level(types: &[u32]) -> LevelDescriptor {
        let entities: Vec<EntitySpawn> = types
            .iter()
            .enumerate()
            .map(|(i, &et)| EntitySpawn {
                index: i,
                entity_type: et,
                pos_data_1: [128, 0, 128, 0],
                pos_data_2: [0; 4],
                param: 0,
                rotation: [0; 3],
                extra: [0; 40],
                initial_damage_buffer_raw: 0,
                model_overrides: [0; 4],
                has_animation: false,
                anim_frames: 0,
                animation: None,
                has_config: false,
                config: None,
            })
            .collect();

        LevelDescriptor {
            raw_header: [0; 0xD0],
            name: "Test".into(),
            world_style: 0,
            terrain_sprite_base: 0,
            sky_color_index: 0,
            sky_model: 0,
            main_base_abort_sky_color_index: 0,
            main_base_abort_sky_model: 0,
            terrain_draw_depth: 30,
            sub_count: entities.len() as u32,
            campaign_record_count: 0,
            entities,
            campaign_records: vec![],
        }
    }

    fn main_base_abort_controller(
        generation: u64,
        level: &LevelDescriptor,
    ) -> crate::main_base_abort::MainBaseAbortControllerStorage {
        let mut progress = crate::power_up_contact::PlayerCampaignProgress::new();
        progress.set_current_control_slot(Some(1));
        crate::main_base_abort::MainBaseAbortControllerStorage::from_loaded_level(
            std::num::NonZeroU64::new(generation).unwrap(),
            level,
            false,
            &mut progress,
        )
        .unwrap()
        .0
    }

