    #[derive(Default)]
    struct RecordingMainBaseType61StaticRadial {
        preflights: Vec<([i16; 3], crate::radial_damage::RadialDamageTemplate)>,
        commits: Vec<([i16; 3], crate::radial_damage::RadialDamageTemplate)>,
    }

    impl MainBaseType61StaticRadialEffects for RecordingMainBaseType61StaticRadial {
        type Prepared = ([i16; 3], crate::radial_damage::RadialDamageTemplate);

        fn preflight_static_radial(
            &mut self,
            origin_raw: [i16; 3],
            template: crate::radial_damage::RadialDamageTemplate,
        ) -> Option<Self::Prepared> {
            self.preflights.push((origin_raw, template));
            Some((origin_raw, template))
        }

        fn commit_static_radial(&mut self, world_fx: &mut WorldFx, prepared: Self::Prepared) {
            self.commits.push(prepared);
            let _ = world_fx.next_shared_retail_random_u16();
        }
    }

    fn main_base_type61_request(
        manager: &EntityManager,
        entity_id: u32,
        terrain: &TerrainGrid,
    ) -> MainBaseType61DeathRequest {
        let entity = manager
            .entities
            .iter()
            .find(|entity| entity.id == entity_id)
            .expect("composition Type-61 actor remains linked");
        let captured = entity
            .authored_spawn_index
            .and_then(crate::main_base_type61_abort::MainBaseType61CapturedSpawn::for_spawn)
            .expect("composition fixture owns an exact Type-61 spawn");
        MainBaseType61DeathRequest {
            active_model_extent_raw: captured.active_model_extent_raw,
            sea_level_raw: Some((terrain.header[0] >> 8) as i16),
            logical_owner: MainBaseType61LogicalOwner {
                entity_id,
                entity_type: entity.entity_type,
            },
            network_session: MainBaseType61NetworkSession::SoloNetworkingDisabled,
        }
    }

    fn exact_fresh_quiet_death_manager() -> EntityManager {
        let authored = [
            (0_usize, 52_u32),
            (1, 52),
            (2, 52),
            (3, 52),
            (4, 62),
            (5, 68),
            (7, 52),
            (21, 52),
            (25, 62),
            (26, 62),
            (27, 52),
            (28, 52),
            (29, 52),
            (30, 52),
            (31, 52),
        ];
        let mut level = make_level(&authored.map(|(_, entity_type)| entity_type));
        for (spawn, (spawn_index, _)) in level.entities.iter_mut().zip(authored) {
            spawn.index = spawn_index;
        }

        let mut metadata = vec![EntityTypeRuntimeMetadata::default(); 69];
        for entity_type in [52_u32, 62, 68] {
            metadata[entity_type as usize] = exact_fresh_quiet_death_metadata_fixture(entity_type);
        }

        let mut manager = EntityManager::from_level_with_type_metadata(&level, &metadata, None);
        manager.fresh_new_game_first_world = true;
        for entity_index in 0..manager.entities.len() {
            let entity_id = manager.entities[entity_index].id;
            let class_id =
                fresh_level_one_quiet_death_profile(manager.entities[entity_index].entity_type)
                    .unwrap()
                    .initial_behavior_class_id;
            assert!(manager
                .bind_captured_fresh_initial_behavior_success(entity_id, class_id)
                .is_some());
            manager.entities[entity_index]
                .collision
                .state_flags_at_0x08
                .overwrite(
                    REMOTE_OWNED_STATE_BIT
                        | DYING_STATE_BIT
                        | DEFERRED_DESTROY_STATE_WRITE_MASK
                        | ORDINARY_DEATH_STATE_SKIP_MASK,
                    0,
                );
        }
        manager
    }

