    fn exact_level_one_type17_context(class_id: u8, target_handle: u32) -> BehaviorContextRuntime {
        let program = behavior_program(u32::from(class_id)).expect("weighted Type-17 behavior");
        let style = *audited_behavior_style(u32::from(class_id), 1)
            .expect("captured Type-17 variant-one predecessor style");
        BehaviorContextRuntime::named_audited(
            program,
            1,
            RetailRuntimeValue::Known(BehaviorChoiceListSource::TypeDefault),
            RetailRuntimeValue::Known(Some(target_handle)),
            RetailRuntimeValue::Known(0),
            style,
        )
        .expect("captured Type-17 predecessor context")
    }

    fn bind_detached_level_one_type17_predecessor(entity: &mut Entity, class_id: u8) {
        entity.collision.health_raw =
            RetailRuntimeValue::Known(TYPE17_STANDARD_DEATH_INITIAL_HEALTH_RAW);
        entity.collision.death_sound_id =
            RetailRuntimeValue::Known(Some(TYPE17_STANDARD_DEATH_SOUND_ID));
        entity.collision.default_state_flags_at_0xc8 =
            RetailRuntimeValue::Known(TYPE17_STANDARD_DEATH_INITIALIZER_STATE_FLAGS_RAW);
        entity.actor_common_axis_descriptor = RetailRuntimeValue::Known(match class_id {
            9 => TYPE17_CAPTURE_PEOPLE_LIVE_AXIS_DESCRIPTOR,
            33 => TYPE17_FOLLOW_BEACONS_LIVE_AXIS_DESCRIPTOR,
            _ => panic!("the accepted Main Base census contains only class 9/33"),
        });
        entity.sub_a_propulsion_runtime =
            RetailRuntimeValue::Known(Some(SubAPropulsionRuntime::from_retail_words(
                RetailRuntimeValue::Known(i32::from(TYPE17_MODEL256_SUB_A_TARGET_SPEED_BASE_RAW)),
                1,
                100,
            )));
        entity.sub_h_external_frame_runtime = RetailRuntimeValue::Known(Some(
            SubHRuntimeState::new(TYPE17_MODEL256_SUB_H_RECORD_COUNT)
                .expect("the exact Type-17 descriptor has eight records"),
        ));
        entity.current_behavior_context = RetailRuntimeValue::Known(Some(
            exact_level_one_type17_context(class_id, entity.id.wrapping_add(1)),
        ));
        // The accepted sample retained one live Primary and null auxiliary
        // slots. Its v1 GoToJob/Follow task-private payload is not required by
        // standard death and has no public forgeable constructor, so this
        // detached fixture authenticates the exact context/runtime surface
        // without inventing retail handles.
        entity.collision.state_flags_at_0x08 = RetailStateWord::exact(0x0146_8825);
    }

