    #[test]
    fn exact_attract_attention_even_and_odd_mints_extract_and_round_trip_linearly() {
        for odd_parity in [false, true] {
            let mut manager = exact_level_one_type9_attract_attention_manager(odd_parity);
            let owner = manager
                .fresh_level1_type9_initial_productions
                .first()
                .expect("exact Attract fixture retains one construction owner");
            let entity_id = owner.entity_id();
            let entity = manager
                .entities
                .iter()
                .find(|entity| entity.id == entity_id)
                .expect("Attract construction owner denotes its live actor");
            let metadata = manager.type_metadata[entity.entity_type as usize].clone();
            assert_eq!(
                owner.successful_attract_attention_owners().and_then(
                    crate::ordinary_type9_attract_attention_initializer::
                        OrdinaryType9AttractAttentionInitialOwners::candidate,
                ).is_some(),
                odd_parity
            );
            assert!(owner.authenticates_finalized_attract_attention_mint(entity, &metadata));
            assert_eq!(
                owner.successful_scheduler_branch(),
                Some(FreshLevel1Type9PublishedSchedulerBranch::AttractAttention)
            );

            let mut adopted = manager
                .take_fresh_level1_type9_scheduler_productions()
                .expect("exact Attract mint enters scheduler extraction");
            assert_eq!(adopted.len(), 1);
            assert!(manager.fresh_level1_type9_initial_productions.is_empty());
            let (_, branch, owner) = adopted.pop().unwrap();
            assert_eq!(
                branch,
                FreshLevel1Type9PublishedSchedulerBranch::AttractAttention
            );
            let (provenance, owners) = owner
                .into_successful_attract_attention_parts()
                .expect("published Attract owner decomposes without reminting leases");
            let entity = manager
                .entities
                .iter()
                .find(|entity| entity.id == entity_id)
                .unwrap();
            assert!(provenance.authenticates_initial_publication(entity, &metadata, &owners));
            let restored =
                FreshLevel1Type9InitialProductionOwner::from_successful_attract_attention_parts(
                    provenance, owners,
                );
            assert!(restored.authenticates_retained_entity(entity));
            assert!(restored.authenticates_finalized_attract_attention_mint(entity, &metadata));
        }
    }

    #[test]
    fn attract_attention_scheduler_extraction_rejects_tampered_mints_atomically() {
        for odd_parity in [false, true] {
            let mut manager = exact_level_one_type9_attract_attention_manager(odd_parity);
            let entity_id = manager.fresh_level1_type9_initial_productions[0].entity_id();
            let entity = manager
                .entities
                .iter_mut()
                .find(|entity| entity.id == entity_id)
                .unwrap();
            let primary = entity
                .actor_tasks
                .task_in_slot(ActorTaskSlot::Primary)
                .unwrap();
            let Some(ActorTaskRuntime::SharedRetarget(state)) =
                entity.actor_tasks.task_state_mut(primary)
            else {
                panic!("exact Attract Primary is SharedRetarget")
            };
            state.before_callback(1_000);

            let before = manager
                .fresh_level1_type9_initial_productions
                .iter()
                .map(FreshLevel1Type9InitialProductionOwner::entity_id)
                .collect::<Vec<_>>();
            assert_eq!(
                manager.take_fresh_level1_type9_scheduler_productions(),
                Err(entity_id)
            );
            assert_eq!(
                manager
                    .fresh_level1_type9_initial_productions
                    .iter()
                    .map(FreshLevel1Type9InitialProductionOwner::entity_id)
                    .collect::<Vec<_>>(),
                before,
                "a failed Attract mint must not drain or reorder the sidecar"
            );
        }
    }

    #[test]
    fn attract_attention_scheduler_extraction_rejects_foreign_sub_a_and_animation_mints() {
        for odd_parity in [false, true] {
            for tamper in 0..3 {
                let mut manager = exact_level_one_type9_attract_attention_manager(odd_parity);
                let entity_id = manager.fresh_level1_type9_initial_productions[0].entity_id();
                let entity = manager
                    .entities
                    .iter_mut()
                    .find(|entity| entity.id == entity_id)
                    .unwrap();
                match tamper {
                    0 | 1 => {
                        let RetailRuntimeValue::Known(Some(sub_a)) =
                            entity.sub_a_propulsion_runtime
                        else {
                            panic!("exact Attract mint has Sub-A propulsion")
                        };
                        entity.sub_a_propulsion_runtime = RetailRuntimeValue::Known(Some(
                            SubAPropulsionRuntime::from_retail_words(
                                sub_a.target_speed_raw(),
                                if tamper == 0 {
                                    -sub_a.direction_multiplier()
                                } else {
                                    sub_a.direction_multiplier()
                                },
                                if tamper == 1 {
                                    sub_a.drive_scale_percent() + 1
                                } else {
                                    sub_a.drive_scale_percent()
                                },
                            ),
                        ));
                    }
                    2 => {
                        let RetailRuntimeValue::Known(Some(animation)) =
                            entity.actor_animation_runtime
                        else {
                            panic!("exact Attract mint has an animation controller")
                        };
                        let mut descriptor = animation.descriptor();
                        descriptor.attention_stop_sound_id ^= 1;
                        let mut foreign = ActorAnimationController::from_descriptor(descriptor)
                            .expect("tampered descriptor retains a valid variable binding");
                        foreign.apply_attract_attention_forced_stop();
                        entity.actor_animation_runtime = RetailRuntimeValue::Known(Some(foreign));
                    }
                    _ => unreachable!(),
                }

                let before = manager
                    .fresh_level1_type9_initial_productions
                    .iter()
                    .map(FreshLevel1Type9InitialProductionOwner::entity_id)
                    .collect::<Vec<_>>();
                assert_eq!(
                    manager.take_fresh_level1_type9_scheduler_productions(),
                    Err(entity_id)
                );
                assert_eq!(
                    manager
                        .fresh_level1_type9_initial_productions
                        .iter()
                        .map(FreshLevel1Type9InitialProductionOwner::entity_id)
                        .collect::<Vec<_>>(),
                    before,
                    "a foreign Attract runtime must not drain or reorder the sidecar"
                );
            }
        }
    }

