    pub(crate) fn exact_level_one_type9_selected_mixed_manager() -> EntityManager {
        for skipped_words in 0..=1_024 {
            let mut world_fx = WorldFx::new();
            for _ in 0..skipped_words {
                world_fx.next_shared_retail_random_u16();
            }
            let manager = exact_level_one_type9_abort_manager_with_world_fx(&mut world_fx, true);
            let branches = manager
                .fresh_level1_type9_initial_productions
                .iter()
                .filter_map(FreshLevel1Type9InitialProductionOwner::successful_scheduler_branch)
                .collect::<Vec<_>>();
            if branches
                .iter()
                .any(|branch| *branch == FreshLevel1Type9PublishedSchedulerBranch::Wander)
                && branches
                    .iter()
                    .any(|branch| *branch != FreshLevel1Type9PublishedSchedulerBranch::Wander)
            {
                return manager;
            }
        }
        panic!("bounded shared-RNG seed search must produce mixed selected Type-9 branches")
    }

    fn exact_level_one_type9_abort_manager_with_world_fx(
        world_fx: &mut WorldFx,
        force_run_away_candidate: bool,
    ) -> EntityManager {
        let mut types = vec![0; 35];
        types[FIRST_WORLD_MAIN_BASE_SPAWN_INDEX] = MAIN_BASE_ENTITY_TYPE;
        for spawn_index in crate::main_base_type9_abort::LEVEL_ONE_TYPE9_SPAWN_INDICES {
            types[spawn_index] = LEVEL_ONE_TYPE9_ENTITY_TYPE;
        }
        let mut level = make_level(&types);
        level.name.clear();
        level.entities[FIRST_WORLD_MAIN_BASE_SPAWN_INDEX].pos_data_1 = [0x00, 0x50, 0x00, 0x00];
        level.entities[FIRST_WORLD_MAIN_BASE_SPAWN_INDEX].pos_data_2[..2]
            .copy_from_slice(&[0x00, 0x3c]);

        let mut metadata = vec![EntityTypeRuntimeMetadata::default(); 55];
        metadata[0] = exact_initializer_metadata([0; 4]);
        metadata[PLAYER_ENTITY_TYPE as usize] = exact_initializer_metadata([0; 4]);
        if force_run_away_candidate {
            // The compact test level omits the retail world's ordinary
            // baddies. Give its already-published type-zero fixtures only the
            // selector capability needed to make Run Away reachable; the
            // Type-9 owner metadata and constructor contract remain exact.
            metadata[0].capability_flags =
                crate::ordinary_type9_initial_selection::LEVEL_ONE_TYPE9_BADDIE_NEARBY_CAPABILITY_MASK;
        }
        metadata[MAIN_BASE_ENTITY_TYPE as usize] = exact_initializer_metadata([0; 4]);
        metadata[LEVEL_ONE_TYPE9_ENTITY_TYPE as usize] = exact_level_one_type9_metadata_fixture();
        let mut manager = EntityManager::from_fresh_new_game_level_with_type_metadata(
            &level,
            &metadata,
            Some(&flat_terrain(0)),
            0,
            world_fx,
        )
        .expect("the exact Type-9 fixture contains no Type-17 births");
        for spawn_index in crate::main_base_type9_abort::LEVEL_ONE_TYPE9_SPAWN_INDICES {
            let entity = manager
                .entities
                .iter_mut()
                .find(|entity| entity.authored_spawn_index == Some(spawn_index))
                .expect("all six authored Type-9 spawns were constructed");
            entity.collision.state_flags_at_0x08 = RetailStateWord::exact(0x00C6_8825);
            // This fixture starts at the captured pre-abort boundary, after
            // the native birth's first scheduler publication.
            entity.collision.fresh_level1_type9_first_scheduler_pending = false;
        }
        manager
    }

    #[test]
    fn native_fresh_type9_initializes_transient_mass_without_changing_generic_births() {
        let mut types = vec![0; 35];
        types[FIRST_WORLD_MAIN_BASE_SPAWN_INDEX] = MAIN_BASE_ENTITY_TYPE;
        for spawn_index in crate::ordinary_type9_live::FRESH_LEVEL1_ORDINARY_TYPE9_SPAWN_INDICES {
            types[spawn_index] = LEVEL_ONE_TYPE9_ENTITY_TYPE;
        }
        // Matching type/model alone does not authorize the native birth policy.
        types[11] = LEVEL_ONE_TYPE9_ENTITY_TYPE;
        let mut level = make_level(&types);
        level.name.clear();
        level.entities[FIRST_WORLD_MAIN_BASE_SPAWN_INDEX].pos_data_1 = [0x00, 0x50, 0x00, 0x00];
        level.entities[FIRST_WORLD_MAIN_BASE_SPAWN_INDEX].pos_data_2[..2]
            .copy_from_slice(&[0x00, 0x3c]);
        assert!(is_retail_first_world(&level));
        let mut metadata = vec![EntityTypeRuntimeMetadata::default(); 55];
        metadata[0] = exact_initializer_metadata([0; 4]);
        metadata[PLAYER_ENTITY_TYPE as usize] = exact_initializer_metadata([0; 4]);
        metadata[MAIN_BASE_ENTITY_TYPE as usize] = exact_initializer_metadata([0; 4]);
        metadata[LEVEL_ONE_TYPE9_ENTITY_TYPE as usize] = exact_level_one_type9_metadata_fixture();
        let terrain = flat_terrain(0);
        let fresh = EntityManager::from_fresh_new_game_level_with_type_metadata(
            &level,
            &metadata,
            Some(&terrain),
            0,
            &mut WorldFx::new(),
        )
        .unwrap();
        let direct =
            EntityManager::from_level_with_type_metadata(&level, &metadata, Some(&terrain));
        let mut admitted_count = 0;
        for entity in fresh.iter_all().filter(|entity| entity.entity_type == 9) {
            let admitted = entity.authored_spawn_index.is_some_and(|index| {
                crate::ordinary_type9_live::FRESH_LEVEL1_ORDINARY_TYPE9_SPAWN_INDICES
                    .contains(&index)
            });
            assert_eq!(
                entity.collision.fresh_level1_type9_first_scheduler_pending,
                admitted
            );
            assert_eq!(
                entity.collision.animation_offset_at_0xb2,
                if admitted {
                    RetailRuntimeValue::Known(0)
                } else {
                    RetailRuntimeValue::Unresolved
                }
            );
            admitted_count += usize::from(admitted);
        }
        assert_eq!(admitted_count, 6);
        for entity in direct.iter_all().filter(|entity| entity.entity_type == 9) {
            assert!(!entity.collision.fresh_level1_type9_first_scheduler_pending);
            assert_eq!(
                entity.collision.animation_offset_at_0xb2,
                RetailRuntimeValue::Unresolved
            );
        }
    }

    #[test]
    fn exact_fresh_type9_run_away_load_adoption_is_atomic_and_authenticated() {
        let mut manager = exact_level_one_type9_run_away_manager();
        let run_away_ids = manager
            .fresh_level1_type9_initial_productions
            .iter()
            .filter(|owner| owner.successful_run_away_selection().is_some())
            .map(FreshLevel1Type9InitialProductionOwner::entity_id)
            .collect::<Vec<_>>();
        assert!(
            !run_away_ids.is_empty(),
            "the exact deterministic cohort exercises Run Away"
        );
        let retained_before = manager.fresh_level1_type9_initial_productions.len();
        let mut scheduler = SpecializedActorTaskScheduler::new();
        assert_eq!(
            scheduler.adopt_fresh_level1_type9_run_away(&mut manager),
            Ok(run_away_ids.len())
        );
        assert_eq!(scheduler.registered_len(), run_away_ids.len());
        assert_eq!(
            manager.fresh_level1_type9_initial_productions.len(),
            retained_before - run_away_ids.len()
        );
        assert!(manager
            .fresh_level1_type9_initial_productions
            .iter()
            .all(|owner| owner.successful_run_away_selection().is_none()));

        let mut corrupted = exact_level_one_type9_run_away_manager();
        let corrupt_id = corrupted
            .fresh_level1_type9_initial_productions
            .iter()
            .find(|owner| owner.successful_run_away_selection().is_some())
            .map(FreshLevel1Type9InitialProductionOwner::entity_id)
            .expect("the exact cohort retains one selected Run Away owner");
        corrupted
            .entities
            .iter_mut()
            .find(|entity| entity.id == corrupt_id)
            .expect("the retained owner denotes a live entity")
            .current_behavior_context = RetailRuntimeValue::Unresolved;
        let sidecars_before = corrupted
            .fresh_level1_type9_initial_productions
            .iter()
            .map(FreshLevel1Type9InitialProductionOwner::entity_id)
            .collect::<Vec<_>>();
        let mut rejected_scheduler = SpecializedActorTaskScheduler::new();
        assert_eq!(
            rejected_scheduler.adopt_fresh_level1_type9_run_away(&mut corrupted),
            Err(
                OrdinaryType9RunAwayLoadAdoptionError::OwnerAuthenticationFailed {
                    entity_id: corrupt_id,
                }
            )
        );
        assert_eq!(rejected_scheduler.registered_len(), 0);
        assert_eq!(
            corrupted
                .fresh_level1_type9_initial_productions
                .iter()
                .map(FreshLevel1Type9InitialProductionOwner::entity_id)
                .collect::<Vec<_>>(),
            sidecars_before,
            "failed batch authentication must not drain or reorder any sidecar"
        );
    }

