    pub(crate) fn terminal_abort_composition_manager() -> EntityManager {
        terminal_abort_composition_manager_with_prefix(false)
    }

    fn full_terminal_abort_composition_manager() -> EntityManager {
        terminal_abort_composition_manager_with_prefix(true)
    }

    fn terminal_abort_composition_manager_with_prefix(include_prefix: bool) -> EntityManager {
        let suffix_types = [
            MAIN_BASE_ENTITY_TYPE,
            FOLLOW_BEACON_ENTITY_TYPE,
            LEVEL_ONE_TYPE54_ENTITY_TYPE,
            LEVEL_ONE_TYPE9_ENTITY_TYPE,
            LEVEL_ONE_TYPE9_ENTITY_TYPE,
            TYPE47_COMMON_DYING_ENTITY_TYPE,
            TYPE47_COMMON_DYING_ENTITY_TYPE,
            TYPE47_COMMON_DYING_ENTITY_TYPE,
            LEVEL_ONE_TYPE9_ENTITY_TYPE,
            LEVEL_ONE_TYPE9_ENTITY_TYPE,
            LEVEL_ONE_TYPE9_ENTITY_TYPE,
            TYPE17_IMPACT_ENTITY_TYPE,
            TYPE17_IMPACT_ENTITY_TYPE,
            TYPE17_IMPACT_ENTITY_TYPE,
            TYPE17_IMPACT_ENTITY_TYPE,
            FOLLOW_BEACON_ENTITY_TYPE,
            LEVEL_ONE_TYPE9_ENTITY_TYPE,
            LEVEL_ONE_TYPE66_ENTITY_TYPE,
            crate::hive_controller::HIVE_ENTITY_TYPE,
            62,
            62,
            FOLLOW_BEACON_ENTITY_TYPE,
            FOLLOW_BEACON_ENTITY_TYPE,
            FOLLOW_BEACON_ENTITY_TYPE,
            FOLLOW_BEACON_ENTITY_TYPE,
            FOLLOW_BEACON_ENTITY_TYPE,
            LEVEL_ONE_TYPE61_ENTITY_TYPE,
            LEVEL_ONE_TYPE61_ENTITY_TYPE,
            LEVEL_ONE_TYPE61_ENTITY_TYPE,
        ];
        let types = if include_prefix {
            [
                FOLLOW_BEACON_ENTITY_TYPE,
                FOLLOW_BEACON_ENTITY_TYPE,
                FOLLOW_BEACON_ENTITY_TYPE,
                FOLLOW_BEACON_ENTITY_TYPE,
                62,
                68,
            ]
            .into_iter()
            .chain(suffix_types)
            .collect::<Vec<_>>()
        } else {
            suffix_types.to_vec()
        };
        let mut level = make_level(&types);
        if include_prefix {
            level.name.clear();
        } else {
            for (spawn, spawn_index) in level.entities.iter_mut().zip(6_usize..=34) {
                spawn.index = spawn_index;
            }
        }
        let level_index = |spawn_index: usize| {
            if include_prefix {
                spawn_index
            } else {
                spawn_index - 6
            }
        };
        let entity_index_for_spawn = |spawn_index: usize| {
            if include_prefix {
                spawn_index + 1
            } else {
                spawn_index - 6
            }
        };
        let entity_id_for_spawn =
            |spawn_index: usize| (entity_index_for_spawn(spawn_index) + 1) as u32;
        if include_prefix {
            let main_base_level_index = level_index(FIRST_WORLD_MAIN_BASE_SPAWN_INDEX);
            level.entities[main_base_level_index].pos_data_1 = [0x00, 0x50, 0x00, 0x00];
            level.entities[main_base_level_index].pos_data_2[..2].copy_from_slice(&[0x00, 0x3c]);
        }
        let type54_x = (-23_040_i16).to_le_bytes();
        let type54_y = (-1_248_i16).to_le_bytes();
        let type54_z = (-4_096_i16).to_le_bytes();
        let type54_level_index = level_index(LEVEL_ONE_TYPE54_SPAWN_INDEX);
        level.entities[type54_level_index].pos_data_1[..2].copy_from_slice(&type54_x);
        level.entities[type54_level_index].pos_data_1[2..4].copy_from_slice(&type54_y);
        level.entities[type54_level_index].pos_data_2[..2].copy_from_slice(&type54_z);
        let factory_level_index = level_index(LEVEL_ONE_TYPE66_SPAWN_INDEX);
        level.entities[factory_level_index].model_overrides = [227, 225, 227, 225];
        level.entities[factory_level_index].has_config = true;
        level.entities[factory_level_index].config = Some(exact_level_one_type66_factory_config());
        let type67_position_raw = [-17_920_i16, -256_i16, -32_768_i16];
        let hive_level_index = level_index(24);
        level.entities[hive_level_index].pos_data_1[..2]
            .copy_from_slice(&type67_position_raw[0].to_le_bytes());
        level.entities[hive_level_index].pos_data_1[2..4]
            .copy_from_slice(&type67_position_raw[1].to_le_bytes());
        level.entities[hive_level_index].pos_data_2[..2]
            .copy_from_slice(&type67_position_raw[2].to_le_bytes());
        let type61_start = level_index(32);
        for (spawn, captured) in level.entities[type61_start..type61_start + 3]
            .iter_mut()
            .zip(LEVEL_ONE_TYPE61_CAPTURED_SPAWNS)
        {
            spawn.pos_data_1[..2].copy_from_slice(&captured.position_raw[0].to_le_bytes());
            spawn.pos_data_1[2..4].copy_from_slice(&captured.position_raw[1].to_le_bytes());
            spawn.pos_data_2[..2].copy_from_slice(&captured.position_raw[2].to_le_bytes());
            spawn.rotation = captured.rotation_raw;
            spawn.extra[8..12].copy_from_slice(&captured.power_up_payload_packed.to_le_bytes());
            if captured.active_model_id != LEVEL_ONE_TYPE61_AUTHORED_MODEL_ID {
                spawn.model_overrides = [captured.active_model_id as u32; 4];
            }
        }

        let mut metadata =
            vec![EntityTypeRuntimeMetadata::default(); CARGO_DROP_PROXY_ENTITY_TYPE as usize + 1];
        metadata[PLAYER_ENTITY_TYPE as usize] = EntityTypeRuntimeMetadata {
            model_slots: [41; 4],
            capability_flags: crate::main_base_abort::ALTERNATE_CLEANUP_CAPABILITY_MASK,
            common_mover_topology: RetailRuntimeValue::Known(
                CommonMoverComponentTopology::default(),
            ),
            ..EntityTypeRuntimeMetadata::default()
        };
        metadata[MAIN_BASE_ENTITY_TYPE as usize] =
            checked_damage_metadata(MAIN_BASE_ENTITY_TYPE, 0x20, 1_000);
        metadata[FOLLOW_BEACON_ENTITY_TYPE as usize] =
            exact_fresh_quiet_death_metadata_fixture(FOLLOW_BEACON_ENTITY_TYPE);
        metadata[62] = exact_fresh_quiet_death_metadata_fixture(62);
        metadata[68] = exact_fresh_quiet_death_metadata_fixture(68);
        metadata[CARGO_DROP_PROXY_ENTITY_TYPE as usize] =
            exact_type93_materialiser_metadata_fixture();
        metadata[LEVEL_ONE_TYPE54_ENTITY_TYPE as usize] = exact_level_one_type54_metadata_fixture();
        metadata[LEVEL_ONE_TYPE9_ENTITY_TYPE as usize] = exact_level_one_type9_metadata_fixture();
        metadata[TYPE47_COMMON_DYING_ENTITY_TYPE as usize] =
            exact_level_one_type47_metadata_fixture();
        metadata[TYPE17_IMPACT_ENTITY_TYPE as usize] = exact_level_one_type17_metadata_fixture();
        metadata[LEVEL_ONE_TYPE66_ENTITY_TYPE as usize] = exact_level_one_type66_metadata_fixture();
        metadata[TYPE60_RING_ENTITY_TYPE as usize] =
            exact_type61_abort_metadata_fixture(TYPE60_RING_ENTITY_TYPE);
        metadata[LEVEL_ONE_TYPE61_ENTITY_TYPE as usize] =
            exact_type61_abort_metadata_fixture(LEVEL_ONE_TYPE61_ENTITY_TYPE);
        let mut type67_metadata = checked_damage_metadata(
            crate::hive_controller::HIVE_ENTITY_TYPE,
            0x18,
            1_000_000_000,
        );
        type67_metadata.model_slots = [341, 343, 341, 343];
        type67_metadata.mass_raw = 1_000;
        type67_metadata.capability_flags = 0x18;
        type67_metadata.common_mover_topology =
            RetailRuntimeValue::Known(CommonMoverComponentTopology {
                sub_n: true,
                ..CommonMoverComponentTopology::default()
            });
        type67_metadata.sub_n_payload = Some(ALTERNATE_CLEANUP_SUB_N_PAYLOAD);
        metadata[crate::hive_controller::HIVE_ENTITY_TYPE as usize] = type67_metadata;

        let mut manager = EntityManager::from_level_with_type_metadata(&level, &metadata, None);
        manager.fresh_new_game_first_world = true;
        let main_base_id = entity_id_for_spawn(FIRST_WORLD_MAIN_BASE_SPAWN_INDEX);
        assert!(manager
            .bind_captured_fresh_initial_behavior_success(main_base_id, 41)
            .is_some());
        let type54_id = entity_id_for_spawn(LEVEL_ONE_TYPE54_SPAWN_INDEX);
        assert!(manager
            .bind_captured_fresh_initial_behavior_success(
                type54_id,
                LEVEL_ONE_TYPE54_INITIAL_BEHAVIOR_CLASS,
            )
            .is_some());
        let quiet_spawn_indices = if include_prefix {
            vec![0_usize, 1, 2, 3, 4, 5, 7, 21, 25, 26, 27, 28, 29, 30, 31]
        } else {
            vec![7_usize, 21, 25, 26, 27, 28, 29, 30, 31]
        };
        for spawn_index in quiet_spawn_indices {
            let entity_id = entity_id_for_spawn(spawn_index);
            let profile = fresh_level_one_quiet_death_profile(
                manager.entities[entity_index_for_spawn(spawn_index)].entity_type,
            )
            .expect("composition quiet-death actor type");
            assert!(manager
                .bind_captured_fresh_initial_behavior_success(
                    entity_id,
                    profile.initial_behavior_class_id,
                )
                .is_some());
        }
        let mut constructor_terrain = empty_alternate_cleanup_terrain();
        constructor_terrain.cells[187 * GRID_SIZE + 129].attribute = 255;
        let terrain_objects = alternate_cleanup_terrain_objects(255, 22);
        // These composition fixtures do not replay the animation-bearing
        // fresh constructor. Retain its separately authenticated receipt:
        // birth Y is zero, while the accepted pre-abort actor has settled to
        // the current Y authored above.
        manager.entities[entity_index_for_spawn(24)].sub_n_runtime = alternate_cleanup_runtime(
            [type67_position_raw[0], 0, type67_position_raw[2]],
            true,
            Some(SubNConstructorTerrain {
                terrain: &constructor_terrain,
                terrain_objects: &terrain_objects,
            }),
        );
        let RetailRuntimeValue::Known(Some(factory)) = &mut manager.entities
            [entity_index_for_spawn(LEVEL_ONE_TYPE66_SPAWN_INDEX)]
        .base_factory_runtime
        else {
            panic!("detached Type-66 fixture must construct exact Sub-M state")
        };
        let production = factory
            .production
            .expect("exact Type-66 config constructs production state");
        factory.live_owner = Some(FactoryLiveOwnerRuntimeState::from_constructor(
            entity_id_for_spawn(LEVEL_ONE_TYPE66_SPAWN_INDEX),
            production.cached_health_raw,
        ));
        assert!(manager
            .bind_captured_fresh_factory_initialization_success(entity_id_for_spawn(
                LEVEL_ONE_TYPE66_SPAWN_INDEX,
            ))
            .is_some());
        // The full variant materializes the persistent player and all 35
        // authored actors, but neither variant replays the fresh behavior
        // publishers. Retain the Type-54 admission, six Type-9 component
        // receipts, and three Type-47 predecessors established separately by
        // their constructor/publication regressions.
        manager.entities[entity_index_for_spawn(LEVEL_ONE_TYPE54_SPAWN_INDEX)]
            .main_base_type54_sea_delta_source =
            RetailRuntimeValue::Known(MainBaseType54SeaDeltaSource::DeriveFromActorModelAndSea);
        for spawn_index in crate::main_base_type9_abort::LEVEL_ONE_TYPE9_SPAWN_INDICES {
            let entity = &mut manager.entities[entity_index_for_spawn(spawn_index)];
            entity.ordinary_type9_pending_initial_selection = Some(
                admit_fresh_level1_ordinary_type9(FreshLevel1OrdinaryType9SpawnFacts {
                    retail_first_world: true,
                    authored_spawn_index: entity.authored_spawn_index.unwrap(),
                    entity_type: entity.entity_type,
                    active_model_slot: entity.collision.active_model_slot(),
                    active_model: entity.model_index,
                    rotation: entity
                        .rotation_heading_pitch_roll_raw()
                        .map(|word| word as u16),
                    immutable_anchor_raw_at_0x90: RetailRuntimeValue::Known(entity.position_raw()),
                })
                .expect("detached Type-9 fixture preserves exact captured construction facts")
                .pending_initial_selection(),
            );
        }
        for entity in &mut manager.entities {
            entity.collision.state_flags_at_0x08 = RetailStateWord::exact(
                (entity.entity_type == MAIN_BASE_ENTITY_TYPE)
                    .then_some(PAIR_COLLISION_ENABLED_STATE_BIT)
                    .unwrap_or(0),
            );
        }
        manager.entities[entity_index_for_spawn(LEVEL_ONE_TYPE66_SPAWN_INDEX)]
            .collision
            .state_flags_at_0x08 =
            RetailStateWord::exact(LEVEL_ONE_TYPE66_CAPTURED_PREABORT_STATE_RAW);
        manager.entities[entity_index_for_spawn(24)].capability_flags = 0x18;
        manager.entities[entity_index_for_spawn(24)]
            .collision
            .state_flags_at_0x08 = RetailStateWord::exact(0x08C6_A805);
        for captured in LEVEL_ONE_TYPE61_CAPTURED_SPAWNS {
            let entity = &mut manager.entities[entity_index_for_spawn(captured.spawn_index)];
            entity.collision.state_flags_at_0x08 =
                RetailStateWord::exact(captured.preabort_state_raw);
        }
        manager.entities[entity_index_for_spawn(FIRST_WORLD_MAIN_BASE_SPAWN_INDEX)]
            .collision
            .pair_callbacks
            .damage_modifier_address = RetailRuntimeValue::Known(None);
        for spawn_index in crate::main_base_type9_abort::LEVEL_ONE_TYPE9_SPAWN_INDICES {
            manager.entities[entity_index_for_spawn(spawn_index)]
                .collision
                .state_flags_at_0x08 = RetailStateWord::exact(0x00C6_8825);
        }
        bind_detached_level_one_type47_predecessor(
            &mut manager.entities[entity_index_for_spawn(11)],
            32,
            [-18_688, -462, 32_512],
            0x0142_8805,
        );
        bind_detached_level_one_type47_predecessor(
            &mut manager.entities[entity_index_for_spawn(12)],
            6,
            [-16_896, -398, -31_488],
            0x0142_8805,
        );
        bind_detached_level_one_type47_predecessor(
            &mut manager.entities[entity_index_for_spawn(13)],
            32,
            [-16_896, -430, 32_000],
            0x0142_A805,
        );
        for (spawn_index, class_id) in [(17_usize, 9_u8), (18, 9), (19, 33), (20, 9)] {
            bind_detached_level_one_type17_predecessor(
                &mut manager.entities[entity_index_for_spawn(spawn_index)],
                class_id,
            );
        }
        manager
    }

