    fn fresh_type9_production_branch_snapshot(
        owner: &FreshLevel1Type9InitialProductionOwner,
    ) -> FreshType9ProductionBranchSnapshot {
        use crate::ordinary_type9_initial_production::FreshLevel1Type9InitialProductionBranch;

        match owner.branch() {
            FreshLevel1Type9InitialProductionBranch::RunAway(
                crate::ordinary_type9_run_away_initializer::OrdinaryType9RunAwayInitializerOutcome::Published { .. },
            ) => FreshType9ProductionBranchSnapshot::RunAwayPublished,
            FreshLevel1Type9InitialProductionBranch::RunAway(
                crate::ordinary_type9_run_away_initializer::OrdinaryType9RunAwayInitializerOutcome::InitializerFallbackPublished { .. },
            ) => FreshType9ProductionBranchSnapshot::RunAwayFallback,
            FreshLevel1Type9InitialProductionBranch::AttractAttention(
                crate::ordinary_type9_attract_attention_initializer::OrdinaryType9AttractAttentionInitializerOutcome::Published { .. },
            ) => FreshType9ProductionBranchSnapshot::AttractAttentionPublished,
            FreshLevel1Type9InitialProductionBranch::AttractAttention(
                crate::ordinary_type9_attract_attention_initializer::OrdinaryType9AttractAttentionInitializerOutcome::InitializerFallbackPublished { .. },
            ) => FreshType9ProductionBranchSnapshot::AttractAttentionFallback,
            FreshLevel1Type9InitialProductionBranch::GoToJob(
                crate::ordinary_type9_go_to_job_initializer::OrdinaryType9GoToJobInitializerOutcome::Published { .. },
            ) => FreshType9ProductionBranchSnapshot::GoToJobPublished,
            FreshLevel1Type9InitialProductionBranch::GoToJob(
                crate::ordinary_type9_go_to_job_initializer::OrdinaryType9GoToJobInitializerOutcome::InitializerFallbackPublished { .. },
            ) => FreshType9ProductionBranchSnapshot::GoToJobFallback,
            FreshLevel1Type9InitialProductionBranch::Wander(
                crate::ordinary_type9_wander_initializer::OrdinaryType9WanderInitializerOutcome::Published { .. },
            ) => FreshType9ProductionBranchSnapshot::WanderPublished,
            FreshLevel1Type9InitialProductionBranch::Wander(
                crate::ordinary_type9_wander_initializer::OrdinaryType9WanderInitializerOutcome::InitializerFallbackPublished { .. },
            ) => FreshType9ProductionBranchSnapshot::WanderFallback,
        }
    }

