    fn commit_terminal_main_base_origin(
        manager: &mut EntityManager,
    ) -> MainBaseTerminalAbortOrigin {
        let main_base_id = manager
            .entities
            .iter()
            .find(|entity| {
                entity.authored_spawn_index == Some(FIRST_WORLD_MAIN_BASE_SPAWN_INDEX)
                    && entity.entity_type == MAIN_BASE_ENTITY_TYPE
            })
            .expect("composition manager retains authored spawn-6 Main Base")
            .id;
        assert!(matches!(
            manager.apply_audited_base_factory_projectile_damage(
                main_base_id,
                primary_damage_request(crate::damage::PRIMARY_PROJECTILE_DAMAGE_PACKET, 17)
            ),
            CheckedProjectileDamageOutcome::ProgressiveDeathStarted(_)
        ));
        let events = manager.advance_base_factory_progressive_deaths(3_199_999);
        let mut origins = events
            .into_iter()
            .filter_map(|event| match event {
                BaseFactoryProgressionEvent::MainBaseLevelAbort { origin } => Some(origin),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(origins.len(), 1);
        assert!(
            manager
                .advance_base_factory_progressive_deaths(100_000)
                .into_iter()
                .all(|event| !matches!(
                    event,
                    BaseFactoryProgressionEvent::MainBaseLevelAbort { .. }
                )),
            "terminal progression must not replay its linear abort origin"
        );
        origins.pop().unwrap()
    }

    struct RecordingAlternateCleanupEffects {
        terrain: TerrainGrid,
        publications: Vec<([u8; 2], u8)>,
    }

    impl RecordingAlternateCleanupEffects {
        fn empty() -> Self {
            Self {
                terrain: empty_alternate_cleanup_terrain(),
                publications: Vec::new(),
            }
        }
    }

    impl MainBaseAbortAlternateCleanupEffects for RecordingAlternateCleanupEffects {
        fn clear_and_publish_old_terrain_attribute(&mut self, cell: [u8; 2]) {
            let index = usize::from(cell[0]) * GRID_SIZE + usize::from(cell[1]);
            let old_attribute = self.terrain.cells[index].attribute;
            self.terrain.cells[index].attribute = 0;
            self.publications.push((cell, old_attribute));
        }
    }

