    #[test]
    fn main_base_scientist_is_tail_appended_related_and_deferred_source_survives() {
        let mut level = make_level(&[9, MAIN_BASE_ENTITY_TYPE, FACTORY_ENTITY_TYPE]);
        let mut factory_config = [0_u8; 0x58];
        factory_config[4..6].copy_from_slice(&3_u16.to_le_bytes());
        level.entities[2].has_config = true;
        level.entities[2].config = Some(factory_config);
        let metadata = main_base_conversion_metadata();
        let mut manager = EntityManager::from_level_with_type_metadata(&level, &metadata, None);
        manager.entities[0].set_motion_raw([0x50ba, -0x02fe, 0x39ec], [0; 3]);
        let request_position_raw = [0x50ba, -0x02e5, 0x39ec];
        let terrain = flat_terrain(-24);
        let expected_replacement_position_raw =
            [request_position_raw[0], -0x0300, request_position_raw[2]];
        manager.entities[2].set_position_raw(expected_replacement_position_raw);
        let selected_behavior = BehaviorSelection {
            choice_index: 0,
            program: behavior_program(54).expect("Go to job behavior"),
        };

        assert_eq!(
            manager.queue_main_base_conversion_destroy(1),
            MainBaseConversionDestroyQueueOutcome::Queued { source_id: 1 }
        );
        assert_eq!(
            manager.entities[0]
                .collision
                .state_flags_at_0x08
                .masked(DEFERRED_DESTROY_PENDING_STATE_BIT),
            RetailRuntimeValue::Known(DEFERRED_DESTROY_PENDING_STATE_BIT),
            "deferred destruction becomes visible before the component/physical suffix"
        );
        let spawned = manager
            .append_main_base_scientist(
                MainBaseScientistSpawnRequest {
                    entity_type: SCIENTIST_ENTITY_TYPE,
                    body: Type8BodyConstruction::CapturedMainBaseFixture,
                    source_id: 1,
                    main_base_id: 2,
                    position_raw: request_position_raw,
                    constructor_surface_bits: None,
                    selected_behavior,
                    prepared_go_to_job: None,
                    terrain: Some(&terrain),
                },
                || 0x1234_ABCD,
            )
            .expect("exact type-8 replacement");

        assert_eq!(
            spawned,
            MainBaseScientistSpawned {
                source_id: 1,
                main_base_id: 2,
                replacement_id: 4,
                replacement_position: raw_position_world(expected_replacement_position_raw),
            }
        );
        assert_eq!(
            manager.retail_live_order_ids().collect::<Vec<_>>(),
            [1, 2, 3, 4],
            "the pending source remains live and the replacement publishes at the tail"
        );
        assert_eq!(manager.pending_main_base_conversion_destroy_ids(), [1]);
        let replacement = manager.entities.last().expect("tail replacement");
        assert_eq!(replacement.entity_type, SCIENTIST_ENTITY_TYPE);
        assert_eq!(
            replacement
                .type8_sub_d_frame_owner
                .expect("Main Base conversion mints the V200002 seed")
                .classifier_cache()
                .stagger_counter(),
            crate::common_mover::sub_d::TYPE8_MAIN_BASE_CONVERSION_SUB_D_SEED
        );
        assert!(replacement.type8_sub_d_runtime.is_some());
        assert_eq!(
            replacement.physical_body_basis_q31,
            RetailRuntimeValue::Known(Type9BodyBasis::from_angle_words(0, 0, 0)),
        );
        assert_eq!(
            replacement
                .collision
                .state_flags_at_0x08
                .masked(BODY_BASIS_REBUILT_STATE_BIT),
            RetailRuntimeValue::Known(BODY_BASIS_REBUILT_STATE_BIT),
        );
        assert_eq!(
            replacement.position_raw(),
            expected_replacement_position_raw,
            "type 8's common constructor terrain-snaps copied request Y"
        );
        assert_eq!(replacement.velocity_raw(), [0; 3]);
        assert_eq!(replacement.mass_raw, 37);
        assert_eq!(replacement.capability_flags, 0x400);
        assert_eq!(replacement.model_index, Some(8));
        assert_eq!(
            replacement.initial_behavior,
            RetailRuntimeValue::Known(Some(selected_behavior))
        );
        assert_eq!(
            replacement.collision.recent_relation_id_at_0x60,
            RetailRuntimeValue::Known(Some(2))
        );
        assert_eq!(
            replacement.collision.recent_relation_elapsed_us_at_0x68,
            RetailRuntimeValue::Known(0)
        );
        let go_to_job = match replacement.actor_task_state(ActorTaskSlot::Primary) {
            Some(ActorTaskRuntime::GoToJob(state)) => *state,
            other => panic!("class-54 birth must install Go-To-Job in slot 0, got {other:?}"),
        };
        assert_eq!(go_to_job.target_id(), Some(3));
        assert_eq!(
            go_to_job.private_state(),
            WanderNearPrivateState::tracked_entity(expected_replacement_position_raw, 3),
            "the task-private anchor is the scientist's post-birth position"
        );
        assert_eq!(go_to_job.elapsed_ms(), 0);
        assert_eq!(replacement.actor_task_state(ActorTaskSlot::Secondary), None);
        assert_eq!(replacement.actor_task_state(ActorTaskSlot::Tertiary), None);
        let RetailRuntimeValue::Known(Some(sub_a)) = replacement.sub_a_propulsion_runtime else {
            panic!("class-54 type 8 must retain its exact Sub-A runtime");
        };
        assert_eq!(sub_a.target_speed_raw(), RetailRuntimeValue::Known(0x0400));
        assert_eq!(sub_a.direction_multiplier(), 1);
        assert_eq!(sub_a.drive_scale_percent(), 100);

        assert_eq!(manager.cleanup_pending_main_base_conversion_destroys(), [1]);
        assert_eq!(
            manager.retail_live_order_ids().collect::<Vec<_>>(),
            [2, 3, 4]
        );
        assert!(manager
            .pending_main_base_conversion_destroy_ids()
            .is_empty());
    }

