    #[test]
    fn main_base_conversion_destroy_matches_suffix_preflight_on_first_scheduler_flags() {
        let level = make_level(&[9]);
        let metadata = main_base_conversion_metadata();
        let mut manager = EntityManager::from_level_with_type_metadata(&level, &metadata, None);
        manager.entities[0].collision.state_flags_at_0x08 = RetailStateWord::exact(0x0046_8805);

        let mut planned = manager.entities[0].collision.state_flags_at_0x08;
        planned.apply_deferred_destroy_pending_write();

        assert_eq!(
            manager.queue_main_base_conversion_destroy(1),
            MainBaseConversionDestroyQueueOutcome::Queued { source_id: 1 }
        );
        assert_eq!(
            manager.entities[0].collision.state_flags_at_0x08, planned,
            "suffix preflight must use FUN_00410B70's full 0x0016_0000 write"
        );

        let mut pending_bit_only = RetailStateWord::exact(0x0046_8805);
        pending_bit_only.overwrite(
            DEFERRED_DESTROY_PENDING_STATE_BIT,
            DEFERRED_DESTROY_PENDING_STATE_BIT,
        );
        assert_ne!(
            manager.entities[0].collision.state_flags_at_0x08, pending_bit_only,
            "or-ing only 0x00100000 leaves first-scheduler 0x00060000 bits live"
        );
    }

    #[test]
    fn main_base_conversion_queues_are_idempotent_and_independent() {
        let level = make_level(&[9, MAIN_BASE_ENTITY_TYPE, 61]);
        let metadata = main_base_conversion_metadata();
        let mut manager = EntityManager::from_level_with_type_metadata(&level, &metadata, None);

        assert_eq!(
            manager.queue_main_base_conversion_destroy(1),
            MainBaseConversionDestroyQueueOutcome::Queued { source_id: 1 }
        );
        assert_eq!(
            manager.queue_main_base_conversion_destroy(1),
            MainBaseConversionDestroyQueueOutcome::AlreadyPending { source_id: 1 }
        );
        assert_eq!(
            manager.queue_main_base_conversion_destroy(2),
            MainBaseConversionDestroyQueueOutcome::SourceIneligible { source_id: 2 }
        );
        manager.queue_power_up_destroys(&[3]);

        assert_eq!(manager.cleanup_pending_power_up_destroys(), [3]);
        assert_eq!(
            manager.pending_main_base_conversion_destroy_ids(),
            [1],
            "the type-61 splice must not consume Main Base's native queue"
        );
        assert_eq!(manager.cleanup_pending_main_base_conversion_destroys(), [1]);
        assert!(manager.pending_power_up_destroy_ids().is_empty());
        assert_eq!(manager.retail_live_order_ids().collect::<Vec<_>>(), [2]);
    }

    #[test]
    fn deferred_destroy_queues_apply_exact_retail_state_write_once() {
        let level = make_level(&[61, 9, MAIN_BASE_ENTITY_TYPE, 61]);
        let metadata = main_base_conversion_metadata();
        let mut manager = EntityManager::from_level_with_type_metadata(&level, &metadata, None);
        const STATE_BEFORE: u32 = 0x06c6_8825;
        const STATE_AFTER: u32 = 0x06d0_8825;
        for index in [0, 1, 3] {
            manager.entities[index].collision.state_flags_at_0x08 =
                RetailStateWord::exact(STATE_BEFORE);
        }

        manager.queue_power_up_destroys(&[4, 1]);
        assert_eq!(
            manager.queue_main_base_conversion_destroy(2),
            MainBaseConversionDestroyQueueOutcome::Queued { source_id: 2 }
        );
        assert_eq!(manager.pending_power_up_destroy_ids(), [1, 4]);
        assert_eq!(manager.pending_main_base_conversion_destroy_ids(), [2]);
        for index in [0, 1, 3] {
            assert_eq!(
                manager.entities[index]
                    .collision
                    .state_flags_at_0x08
                    .known_value_bits(),
                STATE_AFTER,
                "accepted entity {index} must receive FUN_00410B70's full masked write"
            );
        }

        manager.queue_power_up_destroys(&[1, 4]);
        assert_eq!(
            manager.queue_main_base_conversion_destroy(2),
            MainBaseConversionDestroyQueueOutcome::AlreadyPending { source_id: 2 }
        );
        assert_eq!(
            manager.pending_power_up_destroy_ids(),
            [1, 4],
            "duplicate acceptance must not disturb live-list order"
        );
        assert_eq!(manager.pending_main_base_conversion_destroy_ids(), [2]);
        for index in [0, 1, 3] {
            assert_eq!(
                manager.entities[index]
                    .collision
                    .state_flags_at_0x08
                    .known_value_bits(),
                STATE_AFTER,
                "duplicate acceptance must leave the first retail transition stable"
            );
        }
        assert_eq!(
            manager.retail_live_order_ids().collect::<Vec<_>>(),
            [1, 2, 3, 4],
            "acceptance only stages the later live-list splice"
        );

        assert_eq!(manager.cleanup_pending_power_up_destroys(), [1, 4]);
        assert_eq!(manager.retail_live_order_ids().collect::<Vec<_>>(), [2, 3]);
        assert_eq!(
            manager.pending_main_base_conversion_destroy_ids(),
            [2],
            "the independent Main Base queue survives the Power-Up splice"
        );
        assert_eq!(manager.cleanup_pending_main_base_conversion_destroys(), [2]);
        assert_eq!(manager.retail_live_order_ids().collect::<Vec<_>>(), [3]);
    }

    #[test]
    fn main_base_deferred_destroy_entry_accepts_only_consistent_external_custody() {
        let level = make_level(&[61]);
        let metadata = main_base_conversion_metadata();
        let mut manager = EntityManager::from_level_with_type_metadata(&level, &metadata, None);
        let entity_id = manager.entities[0].id;

        // Queue bits are Power-Up, Main-Base conversion, Factory scientist,
        // and actor-terminal respectively. Exhausting the matrix proves that
        // no bit/queue mismatch or multiple owner can be mistaken for retail's
        // one accepted idempotent helper call.
        for state_pending in [false, true] {
            for queue_bits in 0_u8..16 {
                manager.pending_power_up_destroy_ids.clear();
                manager.pending_main_base_conversion_destroy_ids.clear();
                manager.pending_factory_scientist_destroy_ids.clear();
                manager.pending_actor_deferred_destroy_ids.clear();
                if queue_bits & 1 != 0 {
                    manager.pending_power_up_destroy_ids.push(entity_id);
                }
                if queue_bits & 2 != 0 {
                    manager
                        .pending_main_base_conversion_destroy_ids
                        .push(entity_id);
                }
                if queue_bits & 4 != 0 {
                    manager
                        .pending_factory_scientist_destroy_ids
                        .push(entity_id);
                }
                if queue_bits & 8 != 0 {
                    manager.pending_actor_deferred_destroy_ids.push(entity_id);
                }
                let state_raw = if state_pending {
                    DEFERRED_DESTROY_PENDING_STATE_BIT
                } else {
                    0
                };
                manager.entities[0].collision.state_flags_at_0x08 =
                    RetailStateWord::exact(state_raw);
                let facts = MainBaseDeferredDestroyQueueFacts {
                    state_pending,
                    power_up_queued: queue_bits & 1 != 0,
                    main_base_conversion_queued: queue_bits & 2 != 0,
                    factory_scientist_queued: queue_bits & 4 != 0,
                    actor_terminal_queued: queue_bits & 8 != 0,
                };
                let external_count = facts.power_up_queued as usize
                    + facts.main_base_conversion_queued as usize
                    + facts.factory_scientist_queued as usize;
                let expected = if !state_pending && queue_bits == 0 {
                    Ok(MainBaseDeferredDestroyEntry::Unstaged)
                } else if state_pending && external_count == 1 && !facts.actor_terminal_queued {
                    let owner = if facts.power_up_queued {
                        MainBaseExternalDeferredDestroyOwner::Type61DeferredQueue
                    } else if facts.main_base_conversion_queued {
                        MainBaseExternalDeferredDestroyOwner::MainBaseConversion
                    } else {
                        MainBaseExternalDeferredDestroyOwner::FactoryScientist
                    };
                    Ok(MainBaseDeferredDestroyEntry::AlreadyPending(owner))
                } else {
                    Err(MainBaseDeferredDestroyCustodyBlock::StateQueueMismatch(
                        facts,
                    ))
                };

                assert_eq!(
                    manager.preflight_main_base_deferred_destroy_entry(
                        entity_id,
                        manager.entities[0].collision.state_flags_at_0x08,
                    ),
                    expected,
                    "state_pending={state_pending}, queue_bits={queue_bits:04b}"
                );
            }
        }

        manager.pending_power_up_destroy_ids.clear();
        manager.pending_main_base_conversion_destroy_ids.clear();
        manager.pending_factory_scientist_destroy_ids.clear();
        manager.pending_actor_deferred_destroy_ids.clear();
        manager.entities[0]
            .collision
            .state_flags_at_0x08
            .invalidate(DEFERRED_DESTROY_PENDING_STATE_BIT);
        assert_eq!(
            manager.preflight_main_base_deferred_destroy_entry(
                entity_id,
                manager.entities[0].collision.state_flags_at_0x08,
            ),
            Err(MainBaseDeferredDestroyCustodyBlock::StateUnresolved)
        );
    }

    #[test]
    fn externally_owned_destroy_commit_is_a_true_state_and_queue_noop() {
        let level = make_level(&[61]);
        let metadata = main_base_conversion_metadata();
        let mut manager = EntityManager::from_level_with_type_metadata(&level, &metadata, None);
        let entity_id = manager.entities[0].id;
        manager.entities[0].collision.state_flags_at_0x08 = RetailStateWord::exact(0x06c6_8825);
        manager.queue_power_up_destroys(&[entity_id]);
        let entry = manager
            .preflight_main_base_deferred_destroy_entry(
                entity_id,
                manager.entities[0].collision.state_flags_at_0x08,
            )
            .unwrap();
        assert_eq!(
            entry,
            MainBaseDeferredDestroyEntry::AlreadyPending(
                MainBaseExternalDeferredDestroyOwner::Type61DeferredQueue
            )
        );

        // A callback may republish either bit cleared by the first accepted
        // helper write. Retail sees 0x100000 already set at callback exit and
        // therefore preserves both words instead of applying 0xFFF9FFFF again.
        manager.entities[0]
            .collision
            .state_flags_at_0x08
            .overwrite(0x0006_0000, 0x0006_0000);
        let state_before_commit = manager.entities[0].collision.state_flags_at_0x08;
        assert_eq!(
            manager.commit_main_base_deferred_destroy(entity_id, entry),
            MainBaseDeferredDestroyCommit::AlreadyPending(
                MainBaseExternalDeferredDestroyOwner::Type61DeferredQueue
            )
        );
        assert_eq!(
            manager.entities[0].collision.state_flags_at_0x08,
            state_before_commit
        );
        assert_eq!(manager.pending_power_up_destroy_ids(), [entity_id]);
        assert!(manager.pending_actor_deferred_destroy_ids().is_empty());
    }

    #[test]
    fn deferred_destroy_rejections_leave_retail_state_untouched() {
        let level = make_level(&[61, WEIGHT_ENTITY_TYPE, MAIN_BASE_ENTITY_TYPE]);
        let metadata = main_base_conversion_metadata();
        let mut manager = EntityManager::from_level_with_type_metadata(&level, &metadata, None);
        const UNTOUCHED_STATE: u32 = 0x06c6_8825;
        for entity in &mut manager.entities {
            entity.collision.state_flags_at_0x08 = RetailStateWord::exact(UNTOUCHED_STATE);
        }

        manager.queue_power_up_destroys(&[2, 3, u32::MAX]);
        assert_eq!(
            manager.queue_main_base_conversion_destroy(3),
            MainBaseConversionDestroyQueueOutcome::SourceIneligible { source_id: 3 }
        );
        assert_eq!(
            manager.queue_main_base_conversion_destroy(u32::MAX),
            MainBaseConversionDestroyQueueOutcome::SourceUnavailable {
                source_id: u32::MAX
            }
        );
        assert!(manager.pending_power_up_destroy_ids().is_empty());
        assert!(manager
            .pending_main_base_conversion_destroy_ids()
            .is_empty());
        for entity in &manager.entities {
            assert_eq!(
                entity.collision.state_flags_at_0x08.known_value_bits(),
                UNTOUCHED_STATE,
                "rejected entity {} must not receive a destroy-state write",
                entity.id
            );
        }
    }

