    #[test]
    fn census_component_free_pair_state_rejects_near_matches() {
        for (spawn_index, entity_type, active_slot, model, rotation) in [
            (
                FIRST_WORLD_GROCK_SPAWN_INDEX + 1,
                54,
                0,
                FIRST_WORLD_GROCK_MODEL_ID,
                [0, 0, 0],
            ),
            (
                FIRST_WORLD_GROCK_SPAWN_INDEX,
                54,
                0,
                FIRST_WORLD_GROCK_MODEL_ID + 1,
                [0, 0, 0],
            ),
        ] {
            assert_eq!(
                audited_first_world_authored_pair_state(
                    true,
                    spawn_index,
                    entity_type,
                    RetailRuntimeValue::Known(active_slot),
                    Some(model),
                    rotation,
                ),
                EntityPairCallbackRuntimeState::unresolved_with_constructor_null_modifier()
            );
        }

        // Type 67 keeps constructor pair identity even when the Level-1
        // census spawn/slot/rotation guard misses. The miss no longer
        // unpublishes the world-independent `FUN_004104B0` null-component
        // identity.
        let near_hive = audited_first_world_authored_pair_state(
            true,
            FIRST_WORLD_HIVE_SPAWN_INDEX,
            HIVE_ENTITY_TYPE,
            RetailRuntimeValue::Known(0),
            Some(FIRST_WORLD_HIVE_MODEL_ID),
            [16_384, 0, 0],
        );
        assert_eq!(
            near_hive,
            EntityPairCallbackRuntimeState::audited_local(
                None,
                RetailRuntimeValue::Known(
                    PairOrientationPolicy::LiveHeadingWithAuthoredPitchRoll {
                        pitch_raw: 0,
                        roll_raw: 0,
                    }
                ),
            )
        );
    }

