    #[test]
    fn non_first_world_construction_retains_base_factory_pair_identity() {
        let level = make_level(&[
            MAIN_BASE_ENTITY_TYPE,
            FACTORY_ENTITY_TYPE,
            HIVE_ENTITY_TYPE,
            9,
        ]);
        let metadata = vec![EntityTypeRuntimeMetadata::default(); HIVE_ENTITY_TYPE as usize + 1];
        let manager = EntityManager::from_level_with_type_metadata(&level, &metadata, None);
        let expected_building = EntityPairCallbackRuntimeState::audited_local(
            None,
            RetailRuntimeValue::Known(PairOrientationPolicy::LiveHeadingWithAuthoredPitchRoll {
                pitch_raw: 0,
                roll_raw: 0,
            }),
        );
        for entity in manager.iter() {
            match entity.entity_type {
                MAIN_BASE_ENTITY_TYPE | FACTORY_ENTITY_TYPE | HIVE_ENTITY_TYPE => {
                    assert_eq!(entity.collision.pair_callbacks, expected_building);
                }
                9 => {
                    assert_eq!(
                        entity.collision.pair_callbacks,
                        EntityPairCallbackRuntimeState::unresolved_with_constructor_null_modifier()
                    );
                }
                _ => panic!("unexpected fixture type {}", entity.entity_type),
            }
        }
    }

    #[test]
    fn exact_fresh_level1_type9_spawns_retain_birth_anchor_state_and_matrix() {
        let mut types = vec![0; 35];
        types[FIRST_WORLD_MAIN_BASE_SPAWN_INDEX] = MAIN_BASE_ENTITY_TYPE;
        for spawn_index in FRESH_LEVEL1_ORDINARY_TYPE9_SPAWN_INDICES {
            types[spawn_index] = 9;
        }
        let mut level = make_level(&types);
        level.name.clear();
        for spawn_index in FRESH_LEVEL1_ORDINARY_TYPE9_SPAWN_INDICES {
            level.entities[spawn_index].pos_data_1 = [0x81, 0x01, 0x00, 0x00];
            level.entities[spawn_index].pos_data_2[..2].copy_from_slice(&[0x83, 0x02]);
        }
        level.entities[FIRST_WORLD_MAIN_BASE_SPAWN_INDEX].pos_data_1 = [0x00, 0x50, 0x00, 0x00];
        level.entities[FIRST_WORLD_MAIN_BASE_SPAWN_INDEX].pos_data_2[..2]
            .copy_from_slice(&[0x00, 0x3C]);

        let mut metadata = vec![EntityTypeRuntimeMetadata::default(); 55];
        metadata[0] = exact_initializer_metadata([0; 4]);
        metadata[PLAYER_ENTITY_TYPE as usize] = exact_initializer_metadata([0; 4]);
        metadata[MAIN_BASE_ENTITY_TYPE as usize] = exact_initializer_metadata([0; 4]);
        metadata[9] = exact_level_one_type9_metadata_fixture();

        let generic_manager = EntityManager::from_level_with_type_metadata(&level, &metadata, None);
        assert!(generic_manager
            .iter()
            .all(|entity| entity.ordinary_type9_pending_initial_selection.is_none()));
        assert!(generic_manager.iter().all(|entity| {
            if entity.authored_spawn_index.is_none() {
                return entity.physical_body_basis_q31 == RetailRuntimeValue::Unresolved;
            }
            let [heading, pitch, roll] = entity.rotation_heading_pitch_roll_raw();
            entity.physical_body_basis_q31
                == RetailRuntimeValue::Known(Type9BodyBasis::from_angle_words(heading, pitch, roll))
        }));

        let mut terrainless_world_fx = WorldFx::new();
        let terrainless = EntityManager::from_fresh_new_game_level_with_type_metadata(
            &level,
            &metadata,
            None,
            0,
            &mut terrainless_world_fx,
        );
        assert!(matches!(
            terrainless,
            Err(FreshNewGameEntityConstructionError::Type9(
                FreshLevel1Type9InitialProductionFailure::WeightedSelection(
                    crate::ordinary_type9_initial_selection::FreshLevel1Type9WeightedSelectionError::AdmissionBirthAnchorUnavailable
                )
            ))
        ));

        let mut terrain = flat_terrain(0);
        terrain.cells[1 * GRID_SIZE + 2].height = (-3_i8) as u8;
        terrain.cells[2 * GRID_SIZE + 2].height = 7;
        terrain.cells[1 * GRID_SIZE + 3].height = 11;
        terrain.cells[2 * GRID_SIZE + 3].height = (-5_i8) as u8;
        let authored_position_raw = [0x0181, 0, 0x0283];
        let snapped_birth_anchor_raw = [0x0181, 79, 0x0283];
        assert_ne!(authored_position_raw, snapped_birth_anchor_raw);
        assert_eq!(
            terrain.bilinear_height_raw(authored_position_raw[0], authored_position_raw[2]),
            snapped_birth_anchor_raw[1]
        );
        let float_round_trip_raw = world_position_raw([
            f32::from(authored_position_raw[0]) / 256.0,
            terrain.height_at(
                f32::from(authored_position_raw[0]) / 256.0,
                f32::from(authored_position_raw[2]) / 256.0,
            ),
            f32::from(authored_position_raw[2]) / 256.0,
        ]);
        assert_eq!(float_round_trip_raw[1], 80);
        assert_ne!(float_round_trip_raw, snapped_birth_anchor_raw);
        let mut world_fx = WorldFx::new();
        let mut manager = EntityManager::from_fresh_new_game_level_with_type_metadata(
            &level,
            &metadata,
            Some(&terrain),
            0,
            &mut world_fx,
        )
        .expect("type-9 fixture contains no admitted type-17 birth");
        for entity in manager.iter() {
            let Some(spawn_index) = entity.authored_spawn_index else {
                assert_eq!(entity.ordinary_type9_pending_initial_selection, None);
                assert_eq!(
                    entity.physical_body_basis_q31,
                    RetailRuntimeValue::Unresolved
                );
                continue;
            };
            let Some(ordinal) = FRESH_LEVEL1_ORDINARY_TYPE9_SPAWN_INDICES
                .iter()
                .position(|&accepted| accepted == spawn_index)
            else {
                assert_eq!(entity.ordinary_type9_pending_initial_selection, None);
                let [heading, pitch, roll] = entity.rotation_heading_pitch_roll_raw();
                assert_eq!(
                    entity.physical_body_basis_q31,
                    RetailRuntimeValue::Known(Type9BodyBasis::from_angle_words(
                        heading, pitch, roll,
                    ))
                );
                continue;
            };

            let selected = entity
                .ordinary_type9_selected_component_runtime
                .expect("exact captured spawn must retain selected component custody");
            assert_eq!(
                selected.components().immutable_anchor_raw_at_0x90(),
                RetailRuntimeValue::Known(snapped_birth_anchor_raw),
                "D4A0 copies the exact post-terrain +0x96 position into +0x90"
            );
            assert_eq!(entity.position_raw(), snapped_birth_anchor_raw);
            assert_eq!(
                selected
                    .components()
                    .sub_d_frame_owner
                    .classifier_cache()
                    .stagger_counter(),
                FRESH_LEVEL1_ORDINARY_TYPE9_SUB_D_SEEDS[ordinal]
            );
            assert_eq!(
                matches!(entity.initial_behavior, RetailRuntimeValue::Known(Some(_))),
                true,
                "fresh production must publish exactly one selected behavior"
            );
            assert_eq!(
                entity.physical_body_basis_q31,
                RetailRuntimeValue::Known(Type9BodyBasis::from_angle_words(0, 0, 0)),
                "the proven D720/13F70 birth boundary owns the initial matrix"
            );
            assert_eq!(
                entity
                    .collision
                    .state_flags_at_0x08
                    .masked(BODY_BASIS_REBUILT_STATE_BIT),
                RetailRuntimeValue::Known(BODY_BASIS_REBUILT_STATE_BIT),
                "bit 0x4 is published only after all nine basis words"
            );
        }
        assert_eq!(
            manager.fresh_level1_type9_initial_productions.len(),
            FRESH_LEVEL1_ORDINARY_TYPE9_SPAWN_INDICES.len()
        );
        for owner in &manager.fresh_level1_type9_initial_productions {
            let entity = manager
                .entities
                .iter()
                .find(|entity| entity.id == owner.entity_id())
                .expect("every retained production owner denotes a live allocation");
            assert!(owner.authenticates_retained_entity(entity));
        }
        assert_eq!(
            manager
                .fresh_level1_type9_initial_productions
                .iter()
                .map(|owner| {
                    manager
                        .entities
                        .iter()
                        .find(|entity| entity.id == owner.entity_id())
                        .and_then(|entity| entity.authored_spawn_index)
                        .unwrap()
                })
                .collect::<Vec<_>>(),
            FRESH_LEVEL1_ORDINARY_TYPE9_SPAWN_INDICES,
            "manager custody follows successful live-list tail publication order"
        );

        let moved = manager
            .entities
            .iter_mut()
            .find(|entity| entity.authored_spawn_index == Some(9))
            .unwrap();
        let moved_position_raw = [-1_234, 2_345, -3_456];
        let velocity_raw = moved.velocity_raw();
        moved.set_motion_raw(moved_position_raw, velocity_raw);
        assert_eq!(moved.position_raw(), moved_position_raw);
        assert_eq!(
            moved
                .ordinary_type9_selected_component_runtime
                .unwrap()
                .components()
                .immutable_anchor_raw_at_0x90(),
            RetailRuntimeValue::Known(snapped_birth_anchor_raw),
            "later +0x96 motion must not rewrite the immutable +0x90 anchor"
        );
    }

    fn set_level_u32(level: &mut LevelDescriptor, offset: usize, value: u32) {
        level.raw_header[offset..offset + 4].copy_from_slice(&value.to_le_bytes());
    }

    fn make_cargo_manager(weight_count: usize) -> EntityManager {
        let mut types = vec![PLAYER_ENTITY_TYPE];
        types.extend(std::iter::repeat_n(WEIGHT_ENTITY_TYPE, weight_count));
        let level = make_level(&types);
        let mut metadata =
            vec![EntityTypeRuntimeMetadata::default(); WEIGHT_ENTITY_TYPE as usize + 1];
        metadata[PLAYER_ENTITY_TYPE as usize].mass_raw = 100;
        metadata[PLAYER_ENTITY_TYPE as usize].capability_flags = 5;
        set_player_sub_j_descriptor(&mut metadata[PLAYER_ENTITY_TYPE as usize], 5);
        metadata[WEIGHT_ENTITY_TYPE as usize].mass_raw = 200;
        metadata[WEIGHT_ENTITY_TYPE as usize].capability_flags = 0x1000;
        metadata[WEIGHT_ENTITY_TYPE as usize].initializer =
            exact_initializer_metadata([0; 4]).initializer;
        let mut manager = EntityManager::from_level_with_type_metadata(&level, &metadata, None);
        // Most attachment mechanics below exercise the complete authored
        // Sub-J list independently of campaign unlock progression.
        manager
            .player_sub_j_runtime_mut()
            .expect("cargo fixture player must own Sub-J")
            .set_capacity_clamped(5);
        manager
    }

