    #[test]
    fn player_death_uses_authored_wreck_slot_then_removes_attached_allocations() {
        let level = make_level(&[PLAYER_ENTITY_TYPE, WEIGHT_ENTITY_TYPE, 9]);
        let mut metadata =
            vec![EntityTypeRuntimeMetadata::default(); WEIGHT_ENTITY_TYPE as usize + 1];
        metadata[PLAYER_ENTITY_TYPE as usize].model_slots = [41, 67, 41, 67];
        set_player_sub_j_descriptor(&mut metadata[PLAYER_ENTITY_TYPE as usize], 5);
        let mut manager = EntityManager::from_level_with_type_metadata(&level, &metadata, None);
        assert_eq!(
            manager.retail_live_order_ids().collect::<Vec<_>>(),
            [1, 2, 3]
        );
        let player_id = manager.player_id.unwrap();
        manager
            .player_mut()
            .unwrap()
            .collision
            .state_flags_at_0x08
            .overwrite(ACTIVE_MODEL_SLOT_HIGH_STATE_BIT, 0);
        let cargo_id = manager
            .entities
            .iter()
            .find(|entity| entity.entity_type == WEIGHT_ENTITY_TYPE)
            .unwrap()
            .id;
        manager
            .entities
            .iter_mut()
            .find(|entity| entity.id == cargo_id)
            .unwrap()
            .attached_to = Some(player_id);
        assert_eq!(
            manager
                .player_sub_j_runtime_mut()
                .expect("exact player Sub-J")
                .append(cargo_id),
            Ok(SubJAttachmentAppend::Appended)
        );
        // A backlink without an owner-side row is not teardown membership.
        manager
            .entities
            .iter_mut()
            .find(|entity| entity.entity_type == 9)
            .unwrap()
            .attached_to = Some(player_id);

        assert_eq!(manager.switch_player_to_dying_model(), Some(67));
        assert_eq!(manager.player().unwrap().model_index, Some(67));
        assert_eq!(
            manager.player().unwrap().collision.active_model_slot(),
            RetailRuntimeValue::Known(1)
        );
        assert!(manager.remove_player_and_attached_entities());
        assert!(manager.player().is_none());
        assert!(manager.iter_all().all(|entity| entity.id != cargo_id));
        assert_eq!(manager.retail_live_order_ids().collect::<Vec<_>>(), [3]);
        assert!(!manager.remove_player_and_attached_entities());
    }

