    #[test]
    fn lethal_live_hive_hit_commits_the_dying_wreck_without_a_type111() {
        let mut manager =
            checked_damage_manager(&[crate::hive_controller::HIVE_ENTITY_TYPE], 1_800);
        manager.entities[0].collision.state_flags_at_0x08.overwrite(
            ACTIVE_MODEL_SLOT_HIGH_STATE_BIT,
            ACTIVE_MODEL_SLOT_HIGH_STATE_BIT,
        );
        manager.entities[0].model_index = Some(341);
        let live_style = manager.entities[0].current_behavior_context;
        assert_eq!(
            manager.entities[0]
                .collision
                .accepted_hit_presentation_sound_id,
            RetailRuntimeValue::Known(Some(7)),
            "the final dying gate must suppress an authored nonzero cue"
        );

        let CheckedProjectileDamageOutcome::HiveDeathStarted(started) = manager
            .apply_audited_base_factory_projectile_damage(
                1,
                primary_damage_request(crate::damage::PRIMARY_PROJECTILE_DAMAGE_PACKET, 97_200),
            )
        else {
            panic!("the captured lethal hive hit must commit the wreck");
        };

        assert_eq!(
            started.accepted_hit_presentation,
            Some(PrimaryProjectileHitPresentationTransition {
                last_tick_after: 97_200,
                sound_id: None,
            })
        );
        assert_eq!(
            manager.entities[0]
                .collision
                .last_hit_presentation_tick_at_0x34,
            RetailRuntimeValue::Known(97_200)
        );
        assert_eq!(started.model_after, 343);
        assert_eq!(
            manager.entities[0].collision.health_raw,
            RetailRuntimeValue::Known(0)
        );
        assert_eq!(manager.entities[0].model_index, Some(343));
        assert_eq!(
            manager.entities[0].collision.active_model_slot(),
            RetailRuntimeValue::Known(3)
        );
        assert_eq!(
            manager.entities[0]
                .collision
                .state_flags_at_0x08
                .masked(DYING_STATE_BIT),
            RetailRuntimeValue::Known(DYING_STATE_BIT)
        );
        assert_ne!(manager.entities[0].current_behavior_context, live_style);
        assert_eq!(
            hive_wreck_contact_origin(&manager.entities[0]),
            None,
            "a synthetic hive without Sub-N has no authored exit marker"
        );
        assert!(
            !manager.iter().any(|entity| entity.entity_type == 111),
            "the dead hive is the exit; no type-111 teleporter is spawned"
        );
        assert_eq!(
            manager.entities[0].actor_task_state(ActorTaskSlot::Primary),
            Some(&ActorTaskRuntime::HiveRadial(HiveRadialTaskState::dying()))
        );
        assert_eq!(
            manager.entities[0].actor_task_state(ActorTaskSlot::Secondary),
            None
        );
        assert_eq!(
            manager.entities[0].actor_task_state(ActorTaskSlot::Tertiary),
            None
        );
        if let Some(emitter) = manager.entities[0].authored_radial_emitter.as_ref() {
            assert_eq!(
                emitter.controller_state(),
                crate::entity_emitters::HIVE_CONTROLLER_DEAD
            );
        }
    }

