    #[test]
    fn base_factory_progression_emits_exact_stages_then_terminal_model() {
        let mut manager = checked_damage_manager(&[FACTORY_ENTITY_TYPE], 1_800);
        let mut production_before = test_factory_production_runtime(1_800);
        production_before.spawned_pickup_handle = 77;
        let mut pickup = Entity::unresolved_port_entity(77, EntityKind::Unknown(61), 61);
        pickup.active = true;
        manager.append_entity_for_test(pickup);
        let RetailRuntimeValue::Known(Some(mut runtime)) = manager.entities[0].base_factory_runtime
        else {
            panic!("factory runtime");
        };
        runtime.production = Some(production_before);
        manager.entities[0].base_factory_runtime = RetailRuntimeValue::Known(Some(runtime));
        assert!(matches!(
            manager.apply_audited_base_factory_projectile_damage(
                1,
                primary_damage_request(crate::damage::PRIMARY_PROJECTILE_DAMAGE_PACKET, 11)
            ),
            CheckedProjectileDamageOutcome::ProgressiveDeathStarted(
                CheckedProjectileProgressiveDeathStarted {
                    death_sound_id: Some(62),
                    ..
                }
            )
        ));

        assert_eq!(manager.advance_base_factory_progressive_deaths(99_998), []);
        assert!(matches!(
            manager
                .advance_base_factory_progressive_deaths(1)
                .as_slice(),
            [BaseFactoryProgressionEvent::ModelEffectStage {
                target_id: 1,
                model_index: 227,
                effect: ProgressiveModelEffect { threshold: 25 },
                ..
            }]
        ));
        let events = manager.advance_base_factory_progressive_deaths(3_100_000);
        assert_eq!(
            events
                .iter()
                .filter(|event| matches!(
                    event,
                    BaseFactoryProgressionEvent::ModelEffectStage { .. }
                ))
                .count(),
            30
        );
        assert!(matches!(
            events.last(),
            Some(BaseFactoryProgressionEvent::TerminalDeath {
                target_id: 1,
                death_sound_id: Some(62),
                full_frame_sequence_requested: true,
                ..
            })
        ));
        assert!(
            events.iter().all(|event| !matches!(
                event,
                BaseFactoryProgressionEvent::MainBaseLevelAbort { .. }
            )),
            "Factory-only terminal destruction must not enter the Main Base abort path"
        );
        let factory = &manager.entities[0];
        assert_eq!(factory.collision.health_raw, RetailRuntimeValue::Known(0));
        assert_eq!(factory.model_index, Some(225));
        assert_eq!(
            factory
                .collision
                .state_flags_at_0x08
                .masked(DYING_STATE_BIT),
            RetailRuntimeValue::Known(DYING_STATE_BIT)
        );
        let RetailRuntimeValue::Known(Some(runtime)) = factory.base_factory_runtime else {
            panic!("factory runtime");
        };
        assert_eq!(runtime.progressive_death.elapsed_micros_raw, -1);
        assert_eq!(runtime.required_scientists, 0);
        assert_eq!(runtime.current_scientists, 0);
        let mut expected_production = production_before;
        expected_production.current_scientists_raw = 0;
        expected_production.scientist_capacity_raw = 0;
        assert_eq!(
            runtime.production,
            Some(expected_production),
            "FUN_00419750 writes production +0x68/+0x04 then republishes Sub-M"
        );
        assert!(
            manager.is_power_up_destroy_pending(77),
            "stage 32 queues the tracked type-61 before FUN_00419750"
        );
    }

    #[test]
    fn main_base_abort_arms_untouched_factory_without_a_damage_stamp() {
        let mut manager =
            checked_damage_manager(&[MAIN_BASE_ENTITY_TYPE, FACTORY_ENTITY_TYPE], 99_999);
        let factory_index = manager
            .entities
            .iter()
            .position(|entity| entity.entity_type == FACTORY_ENTITY_TYPE)
            .unwrap();
        manager.entities[factory_index]
            .collision
            .last_hit_presentation_tick_at_0x34 = RetailRuntimeValue::Known(0);
        let factory_id = manager.entities[factory_index].id;

        let started = manager.arm_live_factories_for_main_base_abort();
        assert_eq!(
            started,
            [FactoryAbortProgressionStarted {
                target_id: factory_id,
                target_position_raw: manager.entities[factory_index].position_raw(),
                death_sound_id: Some(62),
            }],
            "generic death owns the authored Factory cue before callback revival"
        );
        let factory = &manager.entities[factory_index];
        assert_eq!(
            factory.collision.health_raw,
            RetailRuntimeValue::Known(PROGRESSION_REVIVE_HEALTH_RAW)
        );
        assert_eq!(
            factory.collision.last_hit_presentation_tick_at_0x34,
            RetailRuntimeValue::Known(0),
            "systemic death dispatch is not a fabricated projectile hit"
        );
        let RetailRuntimeValue::Known(Some(runtime)) = factory.base_factory_runtime else {
            panic!("factory runtime");
        };
        assert_eq!(runtime.progressive_death.elapsed_micros_raw, 1);

        assert_eq!(
            manager.arm_live_factories_for_main_base_abort(),
            [],
            "an already-running progression must not be restarted"
        );
        let RetailRuntimeValue::Known(Some(runtime)) =
            manager.entities[factory_index].base_factory_runtime
        else {
            panic!("factory runtime");
        };
        assert_eq!(runtime.progressive_death.elapsed_micros_raw, 1);
    }

    #[test]
    fn factory_pickup_receipt_cannot_link_across_manager_generations() {
        fn factory_version(manager: &EntityManager) -> FactoryProductionEntityVersion {
            let factory = manager
                .entities
                .iter()
                .find(|entity| entity.authored_spawn_index == Some(LEVEL_ONE_TYPE66_SPAWN_INDEX))
                .expect("exact Level-1 factory");
            let RetailRuntimeValue::Known(Some(BaseFactoryRuntimeState {
                live_owner: Some(owner),
                ..
            })) = factory.base_factory_runtime
            else {
                panic!("exact live factory owner")
            };
            FactoryProductionEntityVersion {
                entity_id: factory.id,
                allocation_identity: owner.allocation_identity,
                state_version: owner.state_version,
            }
        }

        let request = FactoryEntitySpawnRequest {
            requested_handle: FactoryRequestedEntityHandle::Allocate,
            entity_type: LEVEL_ONE_TYPE61_ENTITY_TYPE,
            position_raw: [0x5700, -0x0300, 0x3A00],
            spawn_parameter_6: 0x0001_F412,
        };
        let mut first = full_terminal_abort_composition_manager();
        let mut second = full_terminal_abort_composition_manager();
        let first_factory = factory_version(&first);
        let second_factory = factory_version(&second);
        let mut first_fx = WorldFx::new();
        let mut second_fx = WorldFx::new();
        let first_product = first
            .append_factory_pickup(first_factory, request, &mut first_fx)
            .expect("first factory product");
        let second_product = second
            .append_factory_pickup(second_factory, request, &mut second_fx)
            .expect("second factory product");
        assert_eq!(first_product.entity_id, second_product.entity_id);
        assert_ne!(
            first_product.allocation_identity,
            second_product.allocation_identity
        );

        assert!(!second.link_factory_pickup_owner(first_product, second_factory));
        let second_entity = second
            .entities
            .iter()
            .find(|entity| entity.id == second_product.entity_id.get())
            .expect("second product remains live");
        assert_eq!(
            second_entity.collision.recent_relation_id_at_0x60,
            RetailRuntimeValue::Known(None)
        );
        assert!(second.link_factory_pickup_owner(second_product, second_factory));
        assert!(
            second.is_main_base_type61_constructor_authenticated(second_product.entity_id.get())
        );
    }

    fn canonical_factory_worker_metadata() -> EntityTypeRuntimeMetadata {
        let data = v2k_test_support::retail_dir();
        assert!(
            data.join("PRELOAD.DAT").is_file(),
            "normal-tier corpus required"
        );
        let mut session = crate::session::GameSession::init(&data).unwrap();
        session.load_auxiliary_ovl(3, 1).unwrap();
        session.load_level_by_id(13, 1).unwrap();
        EntityTypeRuntimeMetadata::from_section12(
            session
                .cache
                .global_entity_type(SCIENTIST_ENTITY_TYPE as usize)
                .unwrap(),
        )
    }

    #[v2k_test_support::retail_test]
    fn native_factory_worker_surface_uses_birth_tick_world_wave_policy_and_pre_grounding_y() {
        let metadata = canonical_factory_worker_metadata();
        for (waves_enabled, retail_tick, authored_y, expected_surface) in [
            (true, 0, 4096, 0),
            (true, 1, 4096, FULLY_BELOW_SURFACE_STATE_BIT),
            (false, 1, 4096, 0),
            (false, 1, 4097, FULLY_ABOVE_SURFACE_STATE_BIT),
        ] {
            let mut manager = full_terminal_abort_composition_manager();
            manager.type_metadata[SCIENTIST_ENTITY_TYPE as usize] = metadata.clone();
            manager.environment_physics.waves_enabled = waves_enabled;
            let factory = manager
                .entities
                .iter()
                .find(|entity| entity.authored_spawn_index == Some(LEVEL_ONE_TYPE66_SPAWN_INDEX))
                .unwrap();
            let RetailRuntimeValue::Known(Some(runtime)) = factory.base_factory_runtime else {
                panic!("factory runtime");
            };
            let owner = runtime.live_owner.unwrap();
            let source_factory = FactoryProductionEntityVersion {
                entity_id: factory.id,
                allocation_identity: owner.allocation_identity,
                state_version: owner.state_version,
            };
            let mut terrain = flat_terrain(-128);
            terrain.header[0] = 4096 << 8;
            let mut fx = WorldFx::new();
            let mut expected_fx = WorldFx::new();
            for _ in 0..3 {
                expected_fx.next_shared_retail_random_u16();
            }
            let output = manager
                .append_factory_converted_output(
                    source_factory,
                    FactoryEntitySpawnRequest {
                        requested_handle: FactoryRequestedEntityHandle::Allocate,
                        entity_type: 8,
                        position_raw: [0, authored_y, 0],
                        spawn_parameter_6: 0,
                    },
                    retail_tick,
                    &terrain,
                    &mut fx,
                )
                .expect("native worker constructor with explicit surface clock");
            let entity = manager.entity_mut(output.entity_id.get()).unwrap();
            assert_eq!(entity.position_raw(), [0, -4096, 0]);
            // Retail's known wave oracle at x=z=0 is4096 at tick0 and4114
            // at tick1. Comparing the post-D4A0 floor would fail both equalities.
            assert_eq!(
                entity
                    .collision
                    .state_flags_at_0x08
                    .masked(SURFACE_STATE_MASK),
                RetailRuntimeValue::Known(expected_surface),
                "waves={waves_enabled}, tick={retail_tick}, authored_y={authored_y}"
            );
            assert!(
                crate::intro2_type8::intro2_type8_manager_allocation_authenticates(
                    &manager,
                    output.entity_id.get()
                )
            );
            assert_eq!(
                fx.next_shared_retail_random_u16(),
                expected_fx.next_shared_retail_random_u16(),
                "surface comparison must not consume an RNG word"
            );
        }
    }

    #[v2k_test_support::retail_test]
    fn factory_class6_output_and_type93_materialiser_preserve_constructor_rng_and_lifecycle() {
        let mut manager = full_terminal_abort_composition_manager();
        let scientist_metadata = canonical_factory_worker_metadata();
        manager.type_metadata[SCIENTIST_ENTITY_TYPE as usize] = scientist_metadata;
        manager.type_primary_models[SCIENTIST_ENTITY_TYPE as usize] = Some(559);
        let factory_index = manager
            .entities
            .iter()
            .position(|entity| entity.authored_spawn_index == Some(LEVEL_ONE_TYPE66_SPAWN_INDEX))
            .expect("exact Level-1 factory");
        let source_factory = {
            let factory = &mut manager.entities[factory_index];
            let RetailRuntimeValue::Known(Some(runtime)) = &mut factory.base_factory_runtime else {
                panic!("exact live factory runtime")
            };
            // With no vacancy, JobNearby contributes zero and the exact 100:1
            // Type-8 record deterministically selects its class-6 fallback.
            runtime.current_scientists = runtime.required_scientists;
            let owner = runtime.live_owner.expect("exact live factory owner");
            FactoryProductionEntityVersion {
                entity_id: factory.id,
                allocation_identity: owner.allocation_identity,
                state_version: owner.state_version,
            }
        };
        let terrain = flat_terrain(-24);
        let request = FactoryEntitySpawnRequest {
            requested_handle: FactoryRequestedEntityHandle::Allocate,
            entity_type: SCIENTIST_ENTITY_TYPE,
            position_raw: [0x5700, -0x03fa, 0x3906],
            spawn_parameter_6: 0,
        };
        let expected_birth_position_raw = [0x5700, -0x0300, 0x3906];
        let mut expected_fx = WorldFx::new();
        let _component_sub_a_word = expected_fx.next_shared_retail_random_u16();
        let expected_selector_word = expected_fx.next_shared_retail_random_u16();
        let expected_constructor_word = expected_fx.next_shared_retail_random_u16();
        let expected_type93_word = expected_fx.next_shared_retail_random_u16();
        expected_fx.next_shared_retail_random_u16(); // CE90 release selector.
        expected_fx.next_shared_retail_random_u16(); // AD10 fresh Wander task.
        let expected_next_word = expected_fx.next_shared_retail_random_u16();
        let mut world_fx = WorldFx::new();

        let output = manager
            .append_factory_converted_output(source_factory, request, 0, &terrain, &mut world_fx)
            .expect("preflighted class-6 factory output");
        let birth = &manager.factory_converted_output_births()[0];
        assert_eq!(birth.entity_id(), output.entity_id.get());
        assert_eq!(birth.source_factory(), source_factory);
        assert_eq!(birth.spawn_request(), request);
        assert_eq!(birth.selector_rng_word(), expected_selector_word);
        assert_eq!(birth.constructor_rng_words(), &[expected_constructor_word]);
        assert_eq!(birth.selected_behavior_choice_index(), 1);
        assert_eq!(
            birth.selected_behavior_class_id(),
            WANDER_NEAR_BEHAVIOR_CLASS_ID
        );
        let output_entity = manager
            .entities
            .iter()
            .find(|entity| entity.id == output.entity_id.get())
            .expect("factory output was tail-appended");
        assert_eq!(output_entity.position_raw(), expected_birth_position_raw);
        assert_eq!(
            output_entity.type8_wander_anchor_raw_at_0x90,
            RetailRuntimeValue::Known(expected_birth_position_raw)
        );
        assert!(matches!(
            output_entity.actor_task_state(ActorTaskSlot::Primary),
            Some(ActorTaskRuntime::OrdinaryType9Wander(state))
                if state.private_state()
                    == WanderNearPrivateState::ordinary_type9(expected_birth_position_raw)
                    && state.elapsed_ms() == 0
        ));
        assert!(manager.link_factory_converted_output_owner(output, source_factory));
        assert_eq!(
            manager
                .entities
                .iter()
                .find(|entity| entity.id == output.entity_id.get())
                .unwrap()
                .collision
                .recent_relation_id_at_0x60,
            RetailRuntimeValue::Known(Some(source_factory.entity_id))
        );

        let materialiser_request = FactoryEntitySpawnRequest {
            entity_type: FACTORY_MATERIALISER_ENTITY_TYPE,
            ..request
        };
        let materialiser = manager
            .append_factory_output_materialiser(
                source_factory,
                materialiser_request,
                &terrain,
                &mut world_fx,
            )
            .expect("exact Type-93 generic constructor");
        assert_eq!(manager.factory_output_materialiser_births.len(), 1);
        assert_eq!(
            manager.factory_output_materialiser_births[0].selector_rng_word,
            expected_type93_word
        );
        let proxy_before_link = manager
            .entities
            .iter()
            .find(|entity| entity.id == materialiser.entity_id.get())
            .unwrap();
        assert_eq!(
            proxy_before_link.position_raw(),
            expected_birth_position_raw
        );
        assert!(matches!(
            &proxy_before_link.sub_j_attachment_runtime,
            RetailRuntimeValue::Known(Some(runtime)) if runtime.is_empty()
        ));

        assert!(manager.link_factory_materialiser_output(materialiser, output, &mut world_fx));
        let output_entity = manager
            .entities
            .iter()
            .find(|entity| entity.id == output.entity_id.get())
            .unwrap();
        assert_eq!(
            output_entity.attached_to,
            Some(materialiser.entity_id.get())
        );
        assert_eq!(
            output_entity
                .collision
                .state_flags_at_0x08
                .masked(0x0004_1800),
            RetailRuntimeValue::Known(0x0000_1000)
        );
        let proxy = manager
            .entities
            .iter()
            .find(|entity| entity.id == materialiser.entity_id.get())
            .unwrap();
        assert_eq!(proxy.position_raw(), [0x5700, -0x02ff, 0x3906]);
        assert_eq!(proxy.model_slots[0], output_entity.model_index);
        assert_eq!(proxy.model_slots[2], output_entity.model_index);
        assert!(matches!(
            &proxy.sub_j_attachment_runtime,
            RetailRuntimeValue::Known(Some(runtime))
                if runtime.ordered_entity_ids() == [output.entity_id.get()]
        ));

        // The proxy can settle elsewhere than the constructor point. 409030
        // must publish that release point as the child's new +90 anchor.
        let expected_release_position_raw = [0x5800, -0x0300, 0x3a06];
        manager
            .entities
            .iter_mut()
            .find(|entity| entity.id == materialiser.entity_id.get())
            .unwrap()
            .set_motion_raw(expected_release_position_raw, [0; 3]);
        let mut materialiser_tasks =
            crate::specialized_actor_task_production::SpecializedActorTaskScheduler::new();
        assert!(materialiser_tasks.adopt_intro2_type8(&mut manager) > 0);
        let mut materialiser_notifications = GameplayNotifications::new();
        for step in 0..32 {
            assert!(manager
                .update_late_tail_materialisers(LateTailMaterialiserFrame {
                    elapsed_micros: 20_000,
                    terrain: &terrain,
                    world_fx: &mut world_fx,
                    scheduler: &mut materialiser_tasks,
                    notifications: &mut materialiser_notifications,
                    retail_tick: 100 + step,
                })
                .is_empty());
        }
        assert!(manager
            .entities
            .iter()
            .all(|entity| entity.id != materialiser.entity_id.get()));
        let released = manager
            .entities
            .iter()
            .find(|entity| entity.id == output.entity_id.get())
            .expect("stable Type-93 release retains output");
        assert_eq!(released.attached_to, None);
        assert_eq!(released.position_raw(), expected_release_position_raw);
        assert_eq!(
            released.type8_wander_anchor_raw_at_0x90,
            RetailRuntimeValue::Known(expected_release_position_raw)
        );
        assert!(
            matches!(released.actor_task_state(ActorTaskSlot::Primary), Some(ActorTaskRuntime::OrdinaryType9Wander(state)) if state.private_state().target_position_raw == expected_release_position_raw),
            "native CE90 release reselects a fresh task at the rewritten +90 anchor"
        );
        assert_eq!(
            released.collision.default_state_flags_at_0xc8,
            RetailRuntimeValue::Known(0x0000_002f)
        );
        assert_eq!(
            released.collision.state_flags_at_0x08.masked(0x0004_0000),
            RetailRuntimeValue::Known(0x0004_0000)
        );
        assert_eq!(
            world_fx.next_shared_retail_random_u16(),
            expected_next_word,
            "20450, worker selector/task, Type93 selector and release selector/task each draw once"
        );
    }

