    #[test]
    fn main_base_abort_factory_dispatch_honors_retail_skip_masks() {
        let assert_skipped = |mut manager: EntityManager, reason: &str| {
            let before_health = manager.entities[0].collision.health_raw;
            let before_runtime = manager.entities[0].base_factory_runtime;
            assert_eq!(
                manager.arm_live_factories_for_main_base_abort(),
                [],
                "{reason}"
            );
            assert_eq!(manager.entities[0].collision.health_raw, before_health);
            assert_eq!(manager.entities[0].base_factory_runtime, before_runtime);
        };

        for capability_bit in [0x01, 0x10] {
            let mut manager = checked_damage_manager(&[FACTORY_ENTITY_TYPE], 99_999);
            manager.entities[0].capability_flags |= capability_bit;
            assert_skipped(
                manager,
                "FUN_004170A0 routes capability-mask entities to FUN_0041CF90",
            );
        }
        for state_bit in [0x0000_1000, 0x1000_0000] {
            let mut manager = checked_damage_manager(&[FACTORY_ENTITY_TYPE], 99_999);
            manager.entities[0]
                .collision
                .state_flags_at_0x08
                .overwrite(ORDINARY_DEATH_STATE_SKIP_MASK, state_bit);
            assert_skipped(
                manager,
                "FUN_004170A0 skips ordinary death for masked live state",
            );
        }

        let mut unresolved = checked_damage_manager(&[FACTORY_ENTITY_TYPE], 99_999);
        unresolved.entities[0].collision.state_flags_at_0x08 = RetailStateWord::unknown();
        assert_skipped(
            unresolved,
            "unavailable live state must not be replaced by a type-based guess",
        );
    }

