    #[test]
    fn main_base_abort_no_callback_advance_follows_live_skip_routes_and_order() {
        let level = make_level(&[1, 52, 0, 0x6f, 52, 1]);
        let metadata = vec![EntityTypeRuntimeMetadata::default(); 0x70];
        let mut manager = EntityManager::from_level_with_type_metadata(&level, &metadata, None);
        for (entity, state_flags_raw) in manager.entities.iter_mut().zip([
            0x1644_0005_u32,
            0x0640_0005,
            0x1646_0005,
            0x0820_1805,
            0x0640_0005,
            0x1644_0005,
        ]) {
            entity.capability_flags = 0;
            entity.collision.state_flags_at_0x08 = RetailStateWord::exact(state_flags_raw);
        }
        manager.remove_live_entity_ids(&[2]);
        let live_order_before = manager.retail_live_order_ids().collect::<Vec<_>>();
        assert_eq!(live_order_before, [1, 3, 4, 5, 6]);

        for (entity_id, expected_route, expected_successor) in [
            (
                1,
                MainBaseAbortActorRoute::SuppressedByState {
                    entity_id: 1,
                    masked_state: 0x1000_0000,
                },
                Some(3),
            ),
            (
                3,
                MainBaseAbortActorRoute::SuppressedByState {
                    entity_id: 3,
                    masked_state: 0x1000_0000,
                },
                Some(4),
            ),
            (
                4,
                MainBaseAbortActorRoute::ExcludedType {
                    entity_id: 4,
                    entity_type: 0x6f,
                },
                Some(5),
            ),
        ] {
            let actor = manager
                .main_base_abort_actor_observation(entity_id)
                .expect("live callback-free actor");
            let advance = manager
                .advance_main_base_abort_no_callback(actor.lease)
                .expect("eligible live route performs no callback");
            assert_eq!(advance.route, expected_route);
            assert_eq!(
                advance.next_actor.map(|next| next.lease.entity_id),
                expected_successor
            );
        }

        let tail = manager.main_base_abort_actor_observation(6).unwrap();
        assert_eq!(
            manager.advance_main_base_abort_no_callback(tail.lease),
            Ok(MainBaseAbortNoCallbackAdvance {
                route: MainBaseAbortActorRoute::SuppressedByState {
                    entity_id: 6,
                    masked_state: 0x1000_0000,
                },
                next_actor: None,
            })
        );

        let ordinary = manager.main_base_abort_actor_observation(5).unwrap();
        assert_eq!(
            manager.advance_main_base_abort_no_callback(ordinary.lease),
            Err(MainBaseAbortNoCallbackBlock::NotCallbackFreeRoute(
                MainBaseAbortActorRoute::OrdinaryDeath { entity_id: 5 },
            ))
        );

        manager
            .entities
            .iter_mut()
            .find(|entity| entity.id == 5)
            .unwrap()
            .collision
            .state_flags_at_0x08 = RetailStateWord::unknown();
        assert!(matches!(
            manager.advance_main_base_abort_no_callback(ordinary.lease),
            Err(MainBaseAbortNoCallbackBlock::NotCallbackFreeRoute(
                MainBaseAbortActorRoute::UnresolvedState { entity_id: 5 },
            ))
        ));

        let excluded = manager.main_base_abort_actor_observation(4).unwrap();
        manager
            .entities
            .iter_mut()
            .find(|entity| entity.id == 4)
            .unwrap()
            .collision
            .state_flags_at_0x08 = RetailStateWord::unknown();
        assert!(matches!(
            manager.advance_main_base_abort_no_callback(excluded.lease),
            Ok(MainBaseAbortNoCallbackAdvance {
                route: MainBaseAbortActorRoute::ExcludedType {
                    entity_id: 4,
                    entity_type: 0x6f,
                },
                ..
            })
        ));
        manager
            .entities
            .iter_mut()
            .find(|entity| entity.id == 4)
            .unwrap()
            .capability_flags = 1;
        assert_eq!(
            manager.advance_main_base_abort_no_callback(excluded.lease),
            Err(MainBaseAbortNoCallbackBlock::NotCallbackFreeRoute(
                MainBaseAbortActorRoute::AlternateCleanup { entity_id: 4 },
            ))
        );

        let replacement = EntityManager::from_level_with_type_metadata(&level, &metadata, None);
        let stale = manager.main_base_abort_actor_observation(1).unwrap().lease;
        let expected = replacement
            .main_base_abort_actor_observation(1)
            .unwrap()
            .lease;
        assert_eq!(
            replacement.advance_main_base_abort_no_callback(stale),
            Err(MainBaseAbortNoCallbackBlock::ActorLeaseMismatch {
                expected,
                actual: stale,
            })
        );
        assert_eq!(
            manager.advance_main_base_abort_no_callback(MainBaseAbortActorLease {
                entity_id: 999,
                allocation_identity: ordinary.lease.allocation_identity,
            }),
            Err(MainBaseAbortNoCallbackBlock::EntityMissing)
        );
        assert_eq!(
            manager.retail_live_order_ids().collect::<Vec<_>>(),
            live_order_before
        );
    }

    #[test]
    fn terminal_main_base_origin_authenticates_an_exact_nonmutating_nested_noop() {
        let mut manager = terminal_abort_composition_manager();
        let origin = commit_terminal_main_base_origin(&mut manager);
        let actor = origin.actor_lease();
        let collision_before = manager.entities[0].collision.clone();
        let context_before = manager.entities[0].current_behavior_context;
        let runtime_before = manager.entities[0].base_factory_runtime;
        let model_before = manager.entities[0].model_index;
        let live_order_before = manager.retail_live_order_ids().collect::<Vec<_>>();

        assert_eq!(
            manager.apply_main_base_abort_terminal_self_noop(origin, actor),
            Ok(MainBaseAbortTerminalSelfAdvance::Advanced {
                outcome: MainBaseAbortTerminalSelfOutcome::AlreadyDyingNoOp {
                    entity_id: 1,
                    entity_type: MAIN_BASE_ENTITY_TYPE,
                },
                next_actor: manager.main_base_abort_actor_observation(2),
            })
        );
        assert_eq!(manager.entities[0].collision, collision_before);
        assert_eq!(manager.entities[0].current_behavior_context, context_before);
        assert_eq!(manager.entities[0].base_factory_runtime, runtime_before);
        assert_eq!(manager.entities[0].model_index, model_before);
        assert_eq!(
            manager.retail_live_order_ids().collect::<Vec<_>>(),
            live_order_before
        );
        assert!(manager.pending_actor_deferred_destroy_ids().is_empty());
    }

    #[test]
    fn terminal_main_base_noop_returns_origin_for_stale_and_remote_rejections() {
        let mut original_manager = terminal_abort_composition_manager();
        let origin = commit_terminal_main_base_origin(&mut original_manager);
        let actor = origin.actor_lease();

        let mut replacement_manager = terminal_abort_composition_manager();
        let _replacement_origin = commit_terminal_main_base_origin(&mut replacement_manager);
        let replacement_collision_before = replacement_manager.entities[0].collision.clone();
        let failure = replacement_manager
            .apply_main_base_abort_terminal_self_noop(origin, actor)
            .expect_err("a lease from a replaced manager allocation must be stale");
        assert!(matches!(
            failure.error,
            MainBaseAbortTerminalSelfBlock::ActorLeaseMismatch {
                actual,
                ..
            } if actual == actor
        ));
        assert_eq!(
            replacement_manager.entities[0].collision,
            replacement_collision_before
        );
        assert!(replacement_manager
            .pending_actor_deferred_destroy_ids()
            .is_empty());

        original_manager.entities[0]
            .collision
            .state_flags_at_0x08
            .overwrite(REMOTE_OWNED_STATE_BIT, REMOTE_OWNED_STATE_BIT);
        let remote_collision_before = original_manager.entities[0].collision.clone();
        let failure = original_manager
            .apply_main_base_abort_terminal_self_noop(failure.origin, actor)
            .expect_err("remote ownership wins over the already-dying short circuit");
        assert_eq!(
            failure.error,
            MainBaseAbortTerminalSelfBlock::UnexpectedGenericDeathEntry(
                GenericDeathEntry::RemoteOwnedNoOp,
            )
        );
        assert_eq!(
            original_manager.entities[0].collision,
            remote_collision_before
        );
        assert!(original_manager
            .pending_actor_deferred_destroy_ids()
            .is_empty());

        original_manager.entities[0]
            .collision
            .state_flags_at_0x08
            .overwrite(REMOTE_OWNED_STATE_BIT, 0);
        assert!(matches!(
            original_manager.apply_main_base_abort_terminal_self_noop(failure.origin, actor),
            Ok(MainBaseAbortTerminalSelfAdvance::Advanced { .. })
        ));
    }

    fn type9_exploding_transition_request(
        task_lease: MainBaseType9ExplodingTaskLease,
    ) -> SharedRetargetTransitionRequest {
        SharedRetargetTransitionRequest {
            slot: ActorTaskSlot::Primary,
            task_id: task_lease.task_id(),
            reason: crate::shared_retarget_mover::SharedRetargetTransitionReason::LifetimeExpired,
            committed_prefix: crate::shared_retarget_mover::SharedRetargetCallbackPrefix {
                elapsed_ms: LEVEL_ONE_TYPE9_EXPLODING_LIFETIME_MS + 1,
                lifetime_ms: LEVEL_ONE_TYPE9_EXPLODING_LIFETIME_MS,
                retarget: crate::shared_retarget_mover::SharedRetarget::Retained,
            },
        }
    }

    fn publish_exact_type9_exploding_task(
        manager: &mut EntityManager,
        spawn_index: usize,
        world_fx: &mut WorldFx,
    ) -> (u32, MainBaseType9ExplodingTaskLease) {
        let entity_id = manager
            .entities
            .iter()
            .find(|entity| entity.authored_spawn_index == Some(spawn_index))
            .expect("authenticated Type-9 spawn")
            .id;
        let observation = manager
            .main_base_abort_actor_observation(entity_id)
            .expect("authenticated Type-9 observation");
        let advance = manager
            .apply_main_base_abort_type9_death(
                observation.lease,
                MainBaseType9ResultScreenState::AlreadyShownByMainBaseAbort,
                world_fx,
            )
            .expect("exact Type-9 death path");
        let outcome = match advance {
            MainBaseType9DeathAdvance::Advanced { outcome, .. }
            | MainBaseType9DeathAdvance::SuccessorUnavailableAfterCommit { outcome } => outcome,
        };
        let MainBaseType9DeathOutcome::ExplodingTaskPublished { task_lease, .. } = outcome else {
            panic!("exact Type-9 death must publish class 14's Primary task")
        };
        (entity_id, task_lease)
    }

    #[test]
    fn all_six_type9_spawns_commit_the_exact_class14_prefix_and_primary_task() {
        let mut manager = exact_level_one_type9_abort_manager();
        let mut world_fx = WorldFx::new();
        let mut rng_oracle = WorldFx::new();

        for spawn_index in crate::main_base_type9_abort::LEVEL_ONE_TYPE9_SPAWN_INDICES {
            let entity_id = manager
                .entities
                .iter()
                .find(|entity| entity.authored_spawn_index == Some(spawn_index))
                .unwrap()
                .id;
            let observation = manager
                .main_base_abort_actor_observation(entity_id)
                .unwrap();
            let expected_successor = manager.main_base_abort_actor_observation(entity_id + 1);
            let expected_rng_word = rng_oracle.next_shared_retail_random_u16();

            let MainBaseType9DeathAdvance::Advanced {
                outcome,
                next_actor,
            } = manager
                .apply_main_base_abort_type9_death(
                    observation.lease,
                    MainBaseType9ResultScreenState::AlreadyShownByMainBaseAbort,
                    &mut world_fx,
                )
                .unwrap()
            else {
                panic!("each Type-9 actor has a linked successor")
            };
            let MainBaseType9DeathOutcome::ExplodingTaskPublished {
                entity_id: outcome_entity_id,
                death_sound_id,
                sub_a_rng_word,
                message,
                task_lease,
            } = outcome
            else {
                panic!("exact Type-9 path must publish class 14's task")
            };
            assert_eq!(outcome_entity_id, entity_id);
            assert_eq!(death_sound_id, LEVEL_ONE_TYPE9_DEATH_SOUND_ID);
            assert_eq!(sub_a_rng_word, expected_rng_word);
            assert_eq!(
                message,
                MainBaseType9MessageDisposition::SuppressedBecauseResultAlreadyShown
            );
            assert_eq!(task_lease.actor(), observation.lease);
            assert_eq!(next_actor, expected_successor);

            let entity = manager
                .entities
                .iter()
                .find(|entity| entity.id == entity_id)
                .unwrap();
            assert_eq!(
                entity.physical_body_basis_q31,
                RetailRuntimeValue::Known(
                    MainBaseType9CapturedProfile::for_spawn(spawn_index)
                        .unwrap()
                        .physical_body_basis_q31
                ),
                "class 14 must inherit the accepted callback-entry entity matrix"
            );
            assert_eq!(
                entity.collision.animation_offset_at_0xb2,
                RetailRuntimeValue::Known(0),
                "the preceding same-frame scheduler visit clears +0xB2"
            );
            assert_eq!(entity.collision.health_raw, RetailRuntimeValue::Known(0));
            assert_eq!(
                entity.collision.state_flags_at_0x08.masked(DYING_STATE_BIT),
                RetailRuntimeValue::Known(DYING_STATE_BIT)
            );
            assert_eq!(
                entity
                    .collision
                    .state_flags_at_0x08
                    .masked(LEVEL_ONE_TYPE9_PAIR_COLLISION_STATE_BIT),
                RetailRuntimeValue::Known(0)
            );
            let RetailRuntimeValue::Known(Some(context)) = entity.current_behavior_context else {
                panic!("class-14 context")
            };
            assert_eq!(
                context.descriptor(),
                BehaviorDescriptorIdentity::Named(&EXPLODING_PERSON_BEHAVIOR_PROGRAM)
            );
            assert_eq!(
                context.active_style().style_address(),
                EXPLODING_PERSON_BEHAVIOR_PROGRAM
                    .initial_style
                    .frame_address
            );
            assert_eq!(
                context.choice_list_source(),
                RetailRuntimeValue::Known(BehaviorChoiceListSource::TypeDefault)
            );
            assert_eq!(
                context.target_handle_at_0x08(),
                RetailRuntimeValue::Unresolved
            );
            assert_eq!(
                context.auxiliary_word_at_0x0c(),
                RetailRuntimeValue::Unresolved
            );
            assert!(entity.ordinary_type9_pending_initial_selection.is_none());
            assert!(entity.main_base_type9_death_component_runtime.is_some());
            let RetailRuntimeValue::Known(Some(sub_a)) = entity.sub_a_propulsion_runtime else {
                panic!("exact Sub-A runtime")
            };
            assert_eq!(sub_a.target_speed_raw(), RetailRuntimeValue::Known(1));
            assert_eq!(sub_a.direction_multiplier(), 1);
            assert_eq!(sub_a.drive_scale_percent(), 100);
            let RetailRuntimeValue::Known(Some(animation)) = entity.actor_animation_runtime else {
                panic!("exact Sub-I runtime")
            };
            assert_eq!(animation.phase(), 0);
            assert!(animation.special_mode());
            assert_eq!(animation.linked_handle(), None);
            assert!(!animation.forced_stop());
            assert!(matches!(
                entity.actor_task_state(ActorTaskSlot::Primary),
                Some(ActorTaskRuntime::SharedRetarget(task))
                    if task.elapsed_ms() == 0
                        && task.lifetime_ms() == LEVEL_ONE_TYPE9_EXPLODING_LIFETIME_MS
                        && task.private_state().target_position_raw == entity.position_raw()
                        && task.private_state().tracked_entity_handle == 0
                        && task.private_state().direction == 1
                        && task.private_state().reversal_timer_ms == 0
            ));
            assert_eq!(entity.actor_task_state(ActorTaskSlot::Secondary), None);
            assert_eq!(entity.actor_task_state(ActorTaskSlot::Tertiary), None);
        }

        assert_eq!(world_fx.pending_event_count(), 6);
        assert!(world_fx.take_positional_sounds().is_empty());
        assert_eq!(
            world_fx.next_shared_retail_random_u16(),
            rng_oracle.next_shared_retail_random_u16(),
            "each successful post-constructor suffix consumes exactly one RNG word"
        );
        assert!(manager.pending_actor_deferred_destroy_ids().is_empty());
    }

