    #[test]
    fn production_abort_adapter_completes_live_sweep_and_defers_newborn_tasks() {
        let mut manager = full_terminal_abort_composition_manager();
        let origin = commit_terminal_main_base_origin(&mut manager);
        let mut cache_terrain = exact_level_one_type54_terrain();
        cache_terrain.cells[187 * GRID_SIZE + 129].attribute = 255;
        let mut cache = main_base_abort_world_cache(cache_terrain);
        assert!(cache
            .apply_main_base_abort_terrain_transform(|| 0)
            .is_some());
        let mut static_damage = StaticDamageScheduler::new();
        let mut world_fx = WorldFx::new();
        let mut player_hull = PlayerHull::default();
        let mut scheduler =
            crate::specialized_actor_task_production::SpecializedActorTaskScheduler::new();

        // Production already owns the normal Working Factory Primary before
        // the abort callback republishes that same family. The adapter must
        // retire the displaced owner rather than treating it as a conflict.
        let factory_actor = manager.main_base_abort_actor_observation(25).unwrap();
        let factory = match manager.entities[24].base_factory_runtime {
            RetailRuntimeValue::Known(Some(factory)) => factory,
            _ => panic!("exact fixture retains Working Factory runtime"),
        };
        let task_id = manager.entities[24]
            .actor_tasks
            .task_in_slot(ActorTaskSlot::Primary)
            .unwrap();
        scheduler
            .register_main_base_type66_production(MainBaseType66WorkingFactoryTaskLease::issue(
                factory_actor.lease,
                task_id,
                factory.live_owner.unwrap().allocation_identity,
            ))
            .unwrap();

        let level = make_level(&[]);
        let mut controller = main_base_abort_controller(1, &level);
        let report = crate::main_base_abort_production::execute_campaign_abort(
            MainBaseAbortTransactionId::new(1).unwrap(),
            Some(origin),
            &mut controller,
            &mut manager,
            &mut cache,
            &mut static_damage,
            &mut player_hull,
            &mut world_fx,
            &mut scheduler,
            crate::main_base_abort_production::MainBaseAbortGameplayContext {
                extra_lives: crate::entity_collision_state::RetailRuntimeValue::Unresolved,
                notifications: &mut crate::gameplay_notifications::GameplayNotifications::new(),
                retail_tick: 123,
            },
        )
        .expect("the exact full fixture closes every synchronous phase");

        assert_eq!(report.completion.actors_processed, 39);
        assert!(report.completion.terrain_transformed);
        assert!(report.completion.player_handoff_committed);
        assert!(report.completion.full_frame_submitted);
        assert_eq!(report.processed_actors.len(), 39);
        assert_eq!(report.publications.type9_exploding, 6);
        assert_eq!(report.publications.type17_common_dying, 4);
        assert_eq!(report.publications.type47_common_dying, 3);
        assert_eq!(report.publications.type54_sea_level, 1);
        assert_eq!(report.publications.type66_production, 1);
        assert_eq!(report.publications.appended_type60_actors, 3);
        assert_eq!(report.publications.same_family_replacements, 1);
        assert_eq!(report.publications.specialized_total(), 15);
        assert_eq!(scheduler.registered_len(), 15);
        assert_eq!(
            report.world_effects.terrain_attribute_publications().len(),
            9
        );
        assert!(report.world_effects.terrain_dirty());
        assert_eq!(report.terrain, None);
        assert_eq!(report.frame_request, controller.submitted_frame_request());

        // Publication happens after this frame's retail task pass: no newborn
        // task was advanced by the adapter itself.
        for entity_id in [11_u32, 12, 16, 17, 18, 24] {
            assert!(matches!(
                manager.entities[(entity_id - 1) as usize].actor_task_state(ActorTaskSlot::Primary),
                Some(ActorTaskRuntime::SharedRetarget(task)) if task.elapsed_ms() == 0
            ));
        }
        assert!(matches!(
            manager.entities[24].actor_task_state(ActorTaskSlot::Primary),
            Some(ActorTaskRuntime::WorkingFactory(task)) if task.elapsed_ms() == 0
        ));
    }

