    #[test]
    fn production_abort_adapter_rolls_back_a_late_actor_block_atomically() {
        let mut manager = full_terminal_abort_composition_manager();
        let constructor_terrain = exact_level_one_type54_terrain();
        let cargo_id = manager
            .entities
            .iter()
            .find(|entity| entity.entity_type == TYPE17_IMPACT_ENTITY_TYPE)
            .expect("the exact census retains its Type-17 cohort")
            .id;
        let (proxy_id, retained_type17_owner) =
            materialise_exact_type17_type93_for_test(&mut manager, cargo_id, &constructor_terrain);
        assert_eq!(proxy_id, 37);

        // Place one unsupported ordinary actor after Type-93. The speculative
        // sweep must commit the proxy's class-2 transition first, then restore
        // that context, task projection, child relation, sidecar, and queue
        // when this later callback blocks.
        let blocker_id = manager.next_entity_id;
        let mut blocker = Entity::unresolved_port_entity(blocker_id, EntityKind::Unknown(94), 94);
        blocker.collision.state_flags_at_0x08 = RetailStateWord::exact(0);
        assert_eq!(manager.allocate_live_entity_id(), blocker_id);
        manager.append_live_entity(blocker);
        let origin = commit_terminal_main_base_origin(&mut manager);
        let expected_origin_actor = origin.actor_lease();
        let manager_before = main_base_abort_atomic_manager_snapshot(&manager);

        let mut cache_terrain = exact_level_one_type54_terrain();
        cache_terrain.cells[187 * GRID_SIZE + 129].attribute = 255;
        let mut cache = main_base_abort_world_cache(cache_terrain);
        let terrain_before = terrain_snapshot(cache.level_terrain().unwrap());
        let mut static_damage = StaticDamageScheduler::new();
        let mut player_hull = PlayerHull::default();
        let player_hull_before = player_hull;
        let mut world_fx = WorldFx::new();
        let expected_next_random = {
            let mut untouched = WorldFx::new();
            untouched.next_shared_retail_random_u16()
        };
        let mut scheduler =
            crate::specialized_actor_task_production::SpecializedActorTaskScheduler::new();
        scheduler
            .register_type17_common_dying(retained_type17_owner)
            .expect("the materialising Type-17 owner remains registered");
        let mut controller = main_base_abort_controller(3, &make_level(&[]));
        let controller_before = controller;

        let failure = crate::main_base_abort_production::execute_campaign_abort(
            MainBaseAbortTransactionId::new(3).unwrap(),
            Some(origin),
            &mut controller,
            &mut manager,
            &mut cache,
            &mut static_damage,
            &mut player_hull,
            &mut world_fx,
            &mut scheduler,
            crate::main_base_abort_production::MainBaseAbortGameplayContext {
                extra_lives: crate::entity_collision_state::RetailRuntimeValue::Unresolved,
                notifications: &mut crate::gameplay_notifications::GameplayNotifications::new(),
                retail_tick: 123,
            },
        )
        .expect_err("the post-Type-93 unsupported actor must block the speculative sweep");

        assert_eq!(
            failure
                .terminal_origin
                .as_ref()
                .map(MainBaseTerminalAbortOrigin::actor_lease),
            Some(expected_origin_actor)
        );
        assert!(matches!(
            failure.diagnostic,
            crate::main_base_abort_production::MainBaseAbortProductionDiagnostic::
                ActorCallbackBlocked {
                    actor,
                    error: crate::main_base_abort_production::
                        MainBaseAbortActorCallbackBlock::UnsupportedOrdinaryType {
                            entity_type: 94
                        }
                } if actor.lease.entity_id == blocker_id
        ));
        assert!(failure.progress.processed_actors.is_empty());
        assert_eq!(failure.progress.publications.specialized_total(), 0);
        assert!(failure.progress.world_effects.is_none());
        assert!(failure.progress.terrain.is_none());
        assert!(failure.progress.frame_request.is_none());
        assert!(failure.unscheduled_owner.is_none());

        assert_eq!(
            main_base_abort_atomic_manager_snapshot(&manager),
            manager_before
        );
        assert_eq!(
            terrain_snapshot(cache.level_terrain().unwrap()),
            terrain_before
        );
        assert_eq!(static_damage.active_program_count(), 0);
        assert_eq!(player_hull, player_hull_before);
        assert_eq!(controller, controller_before);
        assert_eq!(scheduler.registered_len(), 1);
        assert_eq!(world_fx.pending_event_count(), 0);
        assert_eq!(world_fx.particle_count(), 0);
        assert!(world_fx.exploding_rings().is_empty());
        assert!(world_fx.take_positional_sounds().is_empty());
        assert_eq!(
            world_fx.next_shared_retail_random_u16(),
            expected_next_random,
            "failed speculative callbacks must restore the shared RNG cursor"
        );
        assert!(
            cache
                .apply_main_base_abort_terrain_transform(|| 0)
                .is_some(),
            "rollback must restore the one-shot terrain-transform latch"
        );
    }

    #[test]
    fn exact_fresh_level_one_type54_constructor_authenticates_zero_delta_source() {
        let mut types = vec![0; 35];
        types[FIRST_WORLD_MAIN_BASE_SPAWN_INDEX] = MAIN_BASE_ENTITY_TYPE;
        types[LEVEL_ONE_TYPE54_SPAWN_INDEX] = LEVEL_ONE_TYPE54_ENTITY_TYPE;
        let mut level = make_level(&types);
        level.name.clear();
        level.entities[FIRST_WORLD_MAIN_BASE_SPAWN_INDEX].pos_data_1 = [0x00, 0x50, 0x00, 0x00];
        level.entities[FIRST_WORLD_MAIN_BASE_SPAWN_INDEX].pos_data_2[..2]
            .copy_from_slice(&[0x00, 0x3c]);
        level.entities[LEVEL_ONE_TYPE54_SPAWN_INDEX].pos_data_1[..2]
            .copy_from_slice(&(-23_040_i16).to_le_bytes());
        level.entities[LEVEL_ONE_TYPE54_SPAWN_INDEX].pos_data_1[2..4]
            .copy_from_slice(&0_i16.to_le_bytes());
        level.entities[LEVEL_ONE_TYPE54_SPAWN_INDEX].pos_data_2[..2]
            .copy_from_slice(&(-4_096_i16).to_le_bytes());

        let mut metadata = vec![EntityTypeRuntimeMetadata::default(); 55];
        metadata[LEVEL_ONE_TYPE54_ENTITY_TYPE as usize] = exact_level_one_type54_metadata_fixture();

        let generic = EntityManager::from_level_with_type_metadata(&level, &metadata, None);
        let generic_type54 = generic
            .iter()
            .find(|entity| entity.authored_spawn_index == Some(LEVEL_ONE_TYPE54_SPAWN_INDEX))
            .unwrap();
        assert_eq!(
            generic_type54.main_base_type54_sea_delta_source,
            RetailRuntimeValue::Unresolved
        );

        let mut world_fx = WorldFx::new();
        let mut exact = EntityManager::from_fresh_new_game_level_with_type_metadata(
            &level,
            &metadata,
            None,
            0,
            &mut world_fx,
        )
        .expect("fixture contains no admitted type-17 birth");
        let exact_type54 = exact
            .entities
            .iter_mut()
            .find(|entity| entity.authored_spawn_index == Some(LEVEL_ONE_TYPE54_SPAWN_INDEX))
            .unwrap();
        assert_eq!(exact_type54.position_raw(), [-23_040, 0, -4_096]);
        assert_eq!(exact_type54.rotation_heading_pitch_roll_raw(), [0; 3]);
        assert_eq!(
            exact_type54.model_slots,
            [Some(LEVEL_ONE_TYPE54_MODEL_ID); 4]
        );
        assert_eq!(
            exact_type54.collision.active_model_slot(),
            RetailRuntimeValue::Known(0)
        );
        assert_eq!(exact_type54.model_index, Some(LEVEL_ONE_TYPE54_MODEL_ID));
        assert_eq!(
            exact_type54.main_base_type54_sea_delta_source,
            RetailRuntimeValue::Known(MainBaseType54SeaDeltaSource::DeriveFromActorModelAndSea,)
        );
        assert!(matches!(
            exact_type54.current_behavior_context,
            RetailRuntimeValue::Known(Some(context))
                if context.descriptor()
                    == BehaviorDescriptorIdentity::Named(
                        behavior_program(u32::from(
                            LEVEL_ONE_TYPE54_INITIAL_BEHAVIOR_CLASS,
                        ))
                        .unwrap(),
                    )
        ));

        // Accepted live capture has completed the external placement/collision
        // update, retaining authored X/Z while moving Y below the static spawn.
        exact_type54.position = raw_position_world([-23_040, -1_248, -4_096]);
        assert_eq!(exact_type54.position_raw(), [-23_040, -1_248, -4_096]);

        level.entities[LEVEL_ONE_TYPE54_SPAWN_INDEX].extra[8..12]
            .copy_from_slice(&1_i32.to_le_bytes());
        let near = EntityManager::from_fresh_new_game_level_with_type_metadata(
            &level,
            &metadata,
            None,
            0,
            &mut WorldFx::new(),
        )
        .expect("fixture contains no admitted type-17 birth");
        let near_type54 = near
            .iter()
            .find(|entity| entity.authored_spawn_index == Some(LEVEL_ONE_TYPE54_SPAWN_INDEX))
            .unwrap();
        assert_eq!(
            near_type54.main_base_type54_sea_delta_source,
            RetailRuntimeValue::Unresolved
        );
        assert_eq!(
            near_type54.current_behavior_context,
            RetailRuntimeValue::Unresolved
        );

        level.entities[LEVEL_ONE_TYPE54_SPAWN_INDEX].extra[8..12]
            .copy_from_slice(&0_i32.to_le_bytes());
        level.entities[LEVEL_ONE_TYPE54_SPAWN_INDEX].rotation[0] = 1;
        let wrong_rotation = EntityManager::from_fresh_new_game_level_with_type_metadata(
            &level,
            &metadata,
            None,
            0,
            &mut WorldFx::new(),
        )
        .expect("fixture contains no admitted type-17 birth");
        let wrong_rotation_type54 = wrong_rotation
            .iter()
            .find(|entity| entity.authored_spawn_index == Some(LEVEL_ONE_TYPE54_SPAWN_INDEX))
            .unwrap();
        assert_eq!(
            wrong_rotation_type54.main_base_type54_sea_delta_source,
            RetailRuntimeValue::Unresolved
        );
        assert_eq!(
            wrong_rotation_type54.current_behavior_context,
            RetailRuntimeValue::Unresolved
        );

        level.entities[LEVEL_ONE_TYPE54_SPAWN_INDEX].rotation[0] = 0;
        let mut wrong_slot_terrain = exact_level_one_type54_terrain();
        let cell_x = ((-23_040_i32 >> 8) & 0xff) as usize;
        let cell_z = ((-4_096_i32 >> 8) & 0xff) as usize;
        wrong_slot_terrain.cells[cell_x * GRID_SIZE + cell_z].terrain_type = 0x10;
        let wrong_slot = EntityManager::from_fresh_new_game_level_with_type_metadata(
            &level,
            &metadata,
            Some(&wrong_slot_terrain),
            0,
            &mut WorldFx::new(),
        )
        .expect("fixture contains no admitted type-17 birth");
        let wrong_slot_type54 = wrong_slot
            .iter()
            .find(|entity| entity.authored_spawn_index == Some(LEVEL_ONE_TYPE54_SPAWN_INDEX))
            .unwrap();
        assert_eq!(
            wrong_slot_type54.collision.active_model_slot(),
            RetailRuntimeValue::Known(2)
        );
        assert_eq!(
            wrong_slot_type54.main_base_type54_sea_delta_source,
            RetailRuntimeValue::Unresolved
        );
        assert_eq!(
            wrong_slot_type54.current_behavior_context,
            RetailRuntimeValue::Unresolved
        );
    }

    #[test]
    fn type54_class38_initializer_commits_exact_prefix_effects_and_primary_payload() {
        let mut manager = terminal_abort_composition_manager();
        manager.entities[2]
            .collision
            .state_flags_at_0x08
            .overwrite(0x0000_0800, 0x0000_0800);
        let observation = manager.main_base_abort_actor_observation(3).unwrap();
        let terrain = exact_level_one_type54_terrain();
        let terrain_before = terrain.header[0];
        let mut world_fx = WorldFx::new();
        let mut rng_oracle = WorldFx::new();
        let _initializer_sound_word = rng_oracle.next_shared_retail_random_u16();
        let expected_next_rng_word = rng_oracle.next_shared_retail_random_u16();

        let MainBaseType54DeathAdvance::Advanced {
            outcome,
            next_actor,
        } = manager
            .apply_main_base_abort_type54_death(
                observation.lease,
                &terrain,
                LEVEL_ONE_TYPE54_MODEL_EXTENT_RAW,
                MainBaseType54NetworkSession::SoloNetworkingDisabled,
                &mut world_fx,
            )
            .unwrap()
        else {
            panic!("Type-54 remains linked through initializer return")
        };
        let MainBaseType54DeathOutcome::SeaLevelTaskPublished {
            entity_id,
            sea_delta_raw,
            network,
            tick_receipt,
        } = outcome
        else {
            panic!("exact Type-54 path must publish Primary")
        };
        assert_eq!(entity_id, 3);
        assert_eq!(
            sea_delta_raw,
            crate::main_base_type54_abort::LEVEL_ONE_TYPE54_ACCEPTED_SEA_DELTA_RAW
        );
        assert_eq!(
            network,
            MainBaseType54NetworkDisposition::Kind2SuppressedBySoloSession
        );
        assert_eq!(tick_receipt.sequence(), 1);
        assert_eq!(tick_receipt.lease().actor(), observation.lease);
        assert_eq!(next_actor, manager.main_base_abort_actor_observation(4));

        let entity = &manager.entities[2];
        assert_eq!(entity.collision.health_raw, RetailRuntimeValue::Known(0));
        assert_eq!(
            entity.collision.state_flags_at_0x08.masked(DYING_STATE_BIT),
            RetailRuntimeValue::Known(DYING_STATE_BIT)
        );
        assert_eq!(
            entity.collision.state_flags_at_0x08.masked(0x0000_0800),
            RetailRuntimeValue::Known(0)
        );
        let RetailRuntimeValue::Known(Some(context)) = entity.current_behavior_context else {
            panic!("class-38 context")
        };
        assert_eq!(
            context.descriptor(),
            BehaviorDescriptorIdentity::Named(behavior_program(38).unwrap())
        );
        assert_eq!(
            context.active_style().style_address(),
            crate::main_base_type54_abort::LEVEL_ONE_TYPE54_DEATH_STYLE_ADDRESS
        );
        assert!(matches!(
            entity.actor_task_state(ActorTaskSlot::Primary),
            Some(ActorTaskRuntime::ChangeSeaLevel(state))
                if state.remaining_delta_raw() == sea_delta_raw && state.elapsed_ms() == 0
        ));
        assert_eq!(entity.actor_task_state(ActorTaskSlot::Secondary), None);
        assert_eq!(entity.actor_task_state(ActorTaskSlot::Tertiary), None);
        assert!(manager.pending_actor_deferred_destroy_ids().is_empty());
        assert_eq!(terrain.header[0], terrain_before);
        assert!(world_fx.particle_count() >= 2);
        let sounds = world_fx.take_positional_sounds();
        assert_eq!(sounds.len(), 1);
        assert_eq!(sounds[0].sound_id, 62);
        assert_eq!(
            world_fx.next_shared_retail_random_u16(),
            expected_next_rng_word,
            "the null FUN_00406070 suffix consumes no second RNG word"
        );
    }

    #[test]
    fn type54_remote_and_already_dying_entries_are_exact_zero_rng_noops() {
        for (remote, dying, expected_remote) in [(true, true, true), (false, true, false)] {
            let mut manager = terminal_abort_composition_manager();
            manager.entities[2].collision.state_flags_at_0x08.overwrite(
                REMOTE_OWNED_STATE_BIT | DYING_STATE_BIT,
                u32::from(remote) * REMOTE_OWNED_STATE_BIT | u32::from(dying) * DYING_STATE_BIT,
            );
            if remote {
                manager.entities[2]
                    .collision
                    .state_flags_at_0x08
                    .invalidate(DYING_STATE_BIT);
            }
            let observation = manager.main_base_abort_actor_observation(3).unwrap();
            let collision_before = manager.entities[2].collision.clone();
            let context_before = manager.entities[2].current_behavior_context;
            let mut world_fx = WorldFx::new();
            let mut rng_oracle = WorldFx::new();
            let expected_first_rng_word = rng_oracle.next_shared_retail_random_u16();

            let MainBaseType54DeathAdvance::Advanced { outcome, .. } = manager
                .apply_main_base_abort_type54_death(
                    observation.lease,
                    &exact_level_one_type54_terrain(),
                    1,
                    MainBaseType54NetworkSession::NetworkingEnabled,
                    &mut world_fx,
                )
                .unwrap()
            else {
                panic!("no-op actor remains observable")
            };
            assert!(if expected_remote {
                matches!(outcome, MainBaseType54DeathOutcome::RemoteOwnedNoOp { .. })
            } else {
                matches!(outcome, MainBaseType54DeathOutcome::AlreadyDyingNoOp { .. })
            });
            assert_eq!(manager.entities[2].collision, collision_before);
            assert_eq!(manager.entities[2].current_behavior_context, context_before);
            assert_eq!(world_fx.particle_count(), 0);
            assert!(world_fx.take_positional_sounds().is_empty());
            assert_eq!(
                world_fx.next_shared_retail_random_u16(),
                expected_first_rng_word
            );
            assert!(manager.pending_actor_deferred_destroy_ids().is_empty());
        }
    }

    #[test]
    fn type54_stale_extent_and_network_preflight_blocks_leave_rng_and_actor_untouched() {
        let manager_a = terminal_abort_composition_manager();
        let stale = manager_a
            .main_base_abort_actor_observation(3)
            .unwrap()
            .lease;
        let mut manager_b = terminal_abort_composition_manager();
        let exact = manager_b
            .main_base_abort_actor_observation(3)
            .unwrap()
            .lease;

        for (lease, extent, network, expected) in [
            (
                stale,
                LEVEL_ONE_TYPE54_MODEL_EXTENT_RAW,
                MainBaseType54NetworkSession::SoloNetworkingDisabled,
                "stale",
            ),
            (
                exact,
                LEVEL_ONE_TYPE54_MODEL_EXTENT_RAW - 1,
                MainBaseType54NetworkSession::SoloNetworkingDisabled,
                "extent",
            ),
            (
                exact,
                LEVEL_ONE_TYPE54_MODEL_EXTENT_RAW,
                MainBaseType54NetworkSession::Unresolved,
                "network",
            ),
        ] {
            let collision_before = manager_b.entities[2].collision.clone();
            let context_before = manager_b.entities[2].current_behavior_context;
            let mut world_fx = WorldFx::new();
            let mut rng_oracle = WorldFx::new();
            let expected_first_rng_word = rng_oracle.next_shared_retail_random_u16();
            let error = manager_b
                .apply_main_base_abort_type54_death(
                    lease,
                    &exact_level_one_type54_terrain(),
                    extent,
                    network,
                    &mut world_fx,
                )
                .expect_err("preflight must fail");
            assert!(match (expected, error) {
                ("stale", MainBaseType54DeathBlock::ActorLeaseMismatch { .. })
                | ("extent", MainBaseType54DeathBlock::ActiveModelExtentMismatch { .. })
                | ("network", MainBaseType54DeathBlock::NetworkSessionUnsupported(_)) => true,
                _ => false,
            });
            assert_eq!(manager_b.entities[2].collision, collision_before);
            assert_eq!(
                manager_b.entities[2].current_behavior_context,
                context_before
            );
            assert_eq!(world_fx.particle_count(), 0);
            assert!(world_fx.take_positional_sounds().is_empty());
            assert_eq!(
                world_fx.next_shared_retail_random_u16(),
                expected_first_rng_word
            );
        }
    }

    #[test]
    fn type54_unresolved_or_explicit_delta_source_fails_closed_before_mutation() {
        for source in [
            RetailRuntimeValue::Unresolved,
            RetailRuntimeValue::Known(MainBaseType54SeaDeltaSource::ExplicitPreShiftWords(7)),
        ] {
            let mut manager = terminal_abort_composition_manager();
            manager.entities[2].main_base_type54_sea_delta_source = source;
            let observation = manager.main_base_abort_actor_observation(3).unwrap();
            let collision_before = manager.entities[2].collision.clone();
            let context_before = manager.entities[2].current_behavior_context;
            let mut world_fx = WorldFx::new();
            let mut rng_oracle = WorldFx::new();
            let expected_first_rng_word = rng_oracle.next_shared_retail_random_u16();

            let error = manager
                .apply_main_base_abort_type54_death(
                    observation.lease,
                    &exact_level_one_type54_terrain(),
                    LEVEL_ONE_TYPE54_MODEL_EXTENT_RAW,
                    MainBaseType54NetworkSession::SoloNetworkingDisabled,
                    &mut world_fx,
                )
                .expect_err("unsupported +0x88 authority must fail closed");
            assert_eq!(
                error,
                MainBaseType54DeathBlock::SeaDeltaSourceUnsupported(source)
            );
            assert_eq!(manager.entities[2].collision, collision_before);
            assert_eq!(manager.entities[2].current_behavior_context, context_before);
            assert!(ActorTaskSlot::IN_RETAIL_TICK_ORDER
                .into_iter()
                .all(|slot| manager.entities[2].actor_task_state(slot).is_none()));
            assert_eq!(world_fx.particle_count(), 0);
            assert!(world_fx.take_positional_sounds().is_empty());
            assert_eq!(
                world_fx.next_shared_retail_random_u16(),
                expected_first_rng_word
            );
        }
    }

    #[test]
    fn type54_primary_allocation_failure_commits_effects_then_outer_fallback() {
        let mut manager = terminal_abort_composition_manager();
        manager.entities[2]
            .collision
            .state_flags_at_0x08
            .overwrite(0x0006_8800, 0x0006_8800);
        let observation = manager.main_base_abort_actor_observation(3).unwrap();
        let mut world_fx = WorldFx::new();
        let mut rng_oracle = WorldFx::new();
        let _initializer_sound_word = rng_oracle.next_shared_retail_random_u16();
        let expected_next_rng_word = rng_oracle.next_shared_retail_random_u16();
        let mut allocator = RejectMainBaseType54PrimaryTaskAllocation;
        let MainBaseType54DeathAdvance::Advanced {
            outcome,
            next_actor,
        } = manager
            .apply_main_base_abort_type54_death_with_allocator(
                observation.lease,
                &exact_level_one_type54_terrain(),
                LEVEL_ONE_TYPE54_MODEL_EXTENT_RAW,
                MainBaseType54NetworkSession::SoloNetworkingDisabled,
                &mut world_fx,
                &mut allocator,
            )
            .unwrap()
        else {
            panic!("allocation failure still returns to the actor sweep")
        };
        assert!(matches!(
            outcome,
            MainBaseType54DeathOutcome::InitializerFallbackAfterTaskAllocationFailure {
                entity_id: 3,
                sea_delta_raw:
                    crate::main_base_type54_abort::LEVEL_ONE_TYPE54_ACCEPTED_SEA_DELTA_RAW,
                network: MainBaseType54NetworkDisposition::Kind2SuppressedBySoloSession,
            }
        ));
        assert_eq!(next_actor, manager.main_base_abort_actor_observation(4));
        let entity = &manager.entities[2];
        let RetailRuntimeValue::Known(Some(context)) = entity.current_behavior_context else {
            panic!("outer fallback context")
        };
        assert_eq!(
            context.descriptor(),
            BehaviorDescriptorIdentity::InitializerFailureFallback
        );
        assert_eq!(
            context.target_handle_at_0x08(),
            RetailRuntimeValue::Known(None)
        );
        assert_eq!(
            context.auxiliary_word_at_0x0c(),
            RetailRuntimeValue::Known(0)
        );
        assert_eq!(
            entity.collision.state_flags_at_0x08.masked(DYING_STATE_BIT),
            RetailRuntimeValue::Known(DYING_STATE_BIT)
        );
        assert_eq!(
            entity.collision.state_flags_at_0x08.masked(0x0000_0800),
            RetailRuntimeValue::Known(0)
        );
        assert_eq!(
            entity.collision.state_flags_at_0x08.masked(0x0006_8000),
            RetailRuntimeValue::Known(0),
            "outer 0x1280 fallback policy clears every translated live bit"
        );
        for slot in ActorTaskSlot::IN_RETAIL_TICK_ORDER {
            assert_eq!(entity.actor_task_state(slot), None);
        }
        assert!(world_fx.particle_count() >= 2);
        assert_eq!(world_fx.take_positional_sounds().len(), 1);
        assert_eq!(
            world_fx.next_shared_retail_random_u16(),
            expected_next_rng_word,
            "allocation failure preserves the one committed helper draw"
        );
        assert!(manager.pending_actor_deferred_destroy_ids().is_empty());
    }

    #[test]
    fn type54_task_receipts_tick_elapsed_then_stage_one_deferred_unlink() {
        let mut manager = terminal_abort_composition_manager();
        let observation = manager.main_base_abort_actor_observation(3).unwrap();
        let mut terrain = exact_level_one_type54_terrain();
        let mut world_fx = WorldFx::new();
        let MainBaseType54DeathAdvance::Advanced { outcome, .. } = manager
            .apply_main_base_abort_type54_death(
                observation.lease,
                &terrain,
                LEVEL_ONE_TYPE54_MODEL_EXTENT_RAW,
                MainBaseType54NetworkSession::SoloNetworkingDisabled,
                &mut world_fx,
            )
            .unwrap()
        else {
            panic!("published Type-54 task")
        };
        let MainBaseType54DeathOutcome::SeaLevelTaskPublished { tick_receipt, .. } = outcome else {
            panic!("published Type-54 task")
        };
        let stale_first = tick_receipt.duplicate_for_test();

        let mut expected_terrain = exact_level_one_type54_terrain();
        let mut expected_transition = SeaLevelTransition::new(
            crate::main_base_type54_abort::LEVEL_ONE_TYPE54_ACCEPTED_SEA_DELTA_RAW,
        );
        assert!(!expected_transition.tick(&mut expected_terrain, 96_000));
        let MainBaseType54SeaLevelTickOutcome::Continuing {
            elapsed_ms,
            remaining_delta_raw,
            next_receipt,
            ..
        } = manager
            .tick_main_base_abort_type54_sea_level(tick_receipt, &mut terrain, 96_000)
            .unwrap()
        else {
            panic!("first accepted callback remains nonterminal")
        };
        assert_eq!(elapsed_ms, 96);
        assert_eq!(remaining_delta_raw, expected_transition.remaining());
        assert_eq!(terrain.header[0], expected_terrain.header[0]);
        assert_eq!(next_receipt.sequence(), 2);
        let task_id = manager.entities[2]
            .actor_tasks
            .task_in_slot(ActorTaskSlot::Primary)
            .unwrap();
        assert_eq!(
            manager.entities[2].actor_tasks.wrapper_flags(task_id),
            Some(crate::actor_task_owner::ActorTaskWrapperFlags {
                alive: true,
                in_callback: false,
            }),
            "nonterminal callbacks unwind in release builds too"
        );
        assert!(matches!(
            manager.entities[2].actor_task_state(ActorTaskSlot::Primary),
            Some(ActorTaskRuntime::ChangeSeaLevel(state))
                if state.elapsed_ms() == 96
                    && state.remaining_delta_raw() == remaining_delta_raw
        ));

        let terrain_before_replay = terrain.header[0];
        let replay = manager
            .tick_main_base_abort_type54_sea_level(stale_first, &mut terrain, 96_000)
            .expect_err("sequence-one receipt cannot replay callback two");
        assert_eq!(
            replay.error,
            MainBaseType54SeaLevelTickBlock::ReceiptSequenceMismatch {
                expected: 2,
                actual: 1,
            }
        );
        assert_eq!(terrain.header[0], terrain_before_replay);

        let mut receipt = next_receipt;
        let (terminal_elapsed_ms, terminal_replay) = loop {
            let duplicate = receipt.duplicate_for_test();
            match manager
                .tick_main_base_abort_type54_sea_level(receipt, &mut terrain, 2_000_000)
                .unwrap()
            {
                MainBaseType54SeaLevelTickOutcome::Continuing { next_receipt, .. } => {
                    receipt = next_receipt;
                }
                MainBaseType54SeaLevelTickOutcome::DeferredDestroyStaged {
                    elapsed_ms,
                    final_sea_level_raw,
                    ..
                } => {
                    assert_eq!(final_sea_level_raw, -216_832 - 168_192);
                    break (elapsed_ms, duplicate);
                }
            }
        };
        assert!(terminal_elapsed_ms > 96);
        assert_eq!(manager.pending_actor_deferred_destroy_ids(), &[3]);
        assert_eq!(
            manager.entities[2].actor_tasks.wrapper_flags(task_id),
            Some(crate::actor_task_owner::ActorTaskWrapperFlags {
                alive: true,
                in_callback: false,
            }),
            "terminal callbacks unwind before the deferred entity sweep"
        );
        assert!(matches!(
            manager.entities[2].actor_task_state(ActorTaskSlot::Primary),
            Some(ActorTaskRuntime::ChangeSeaLevel(state))
                if state.remaining_delta_raw() == 0
                    && state.elapsed_ms() == terminal_elapsed_ms
        ));

        let terrain_after_completion = terrain.header[0];
        let duplicate_completion = manager
            .tick_main_base_abort_type54_sea_level(terminal_replay, &mut terrain, 2_000_000)
            .expect_err("terminal callback cannot queue deferred removal twice");
        assert_eq!(
            duplicate_completion.error,
            MainBaseType54SeaLevelTickBlock::DeferredDestroyAlreadyPending
        );
        assert_eq!(terrain.header[0], terrain_after_completion);
        assert_eq!(manager.pending_actor_deferred_destroy_ids(), &[3]);

        assert_eq!(manager.cleanup_pending_actor_deferred_destroys(), [3]);
        let final_entity_id = manager
            .entities
            .last()
            .expect("composition fixture retains later actors")
            .id;
        assert_eq!(
            manager.retail_live_order_ids().collect::<Vec<_>>(),
            (1..=final_entity_id)
                .filter(|entity_id| *entity_id != 3)
                .collect::<Vec<_>>()
        );
    }

    #[test]
    fn quiet_death_commits_all_fifteen_exact_actors_and_samples_successors_afterward() {
        let mut manager = exact_fresh_quiet_death_manager();
        let mut world_fx = WorldFx::new();
        let actor_count = manager.entities.len();
        let type62_index = manager
            .entities
            .iter()
            .position(|entity| entity.entity_type == 62)
            .unwrap();
        let mut sub_a =
            SubAPropulsionRuntime::from_retail_words(RetailRuntimeValue::Known(0), 1, 100);
        crate::ordinary_type9_wander_owner::plan_ordinary_type9_wander_setup([0; 3], 0)
            .apply(
                &mut manager.entities[type62_index].actor_tasks,
                &mut sub_a,
                |specification| {
                    Ok::<_, Infallible>(
                        specification
                            .prepare_after_allocation(|| 0)
                            .map_task(ActorTaskRuntime::OrdinaryType9Wander),
                    )
                },
            )
            .unwrap();
        assert!(matches!(
            manager.entities[type62_index].actor_task_state(ActorTaskSlot::Primary),
            Some(ActorTaskRuntime::OrdinaryType9Wander(_))
        ));

        for entity_index in 0..actor_count {
            let entity_id = manager.entities[entity_index].id;
            let observation = manager
                .main_base_abort_actor_observation(entity_id)
                .expect("quiet-death actor");
            let entity_type = observation.entity_type;
            let expected_sound = fresh_level_one_quiet_death_profile(entity_type)
                .unwrap()
                .death_sound_id;
            let result = manager
                .apply_main_base_abort_quiet_death(observation.lease, &mut world_fx)
                .expect("exact class-2 callback");
            let MainBaseAbortQuietDeathAdvance::Advanced {
                outcome,
                next_actor,
            } = result
            else {
                panic!("the retained allocation makes its post-callback successor observable")
            };
            assert_eq!(
                outcome,
                MainBaseAbortQuietDeathOutcome::DeferredDestroyStaged {
                    entity_id,
                    entity_type,
                    death_sound_id: expected_sound,
                }
            );
            assert_eq!(
                next_actor.map(|next| next.lease.entity_id),
                manager
                    .entities
                    .get(entity_index + 1)
                    .map(|entity| entity.id)
            );

            let entity = &manager.entities[entity_index];
            assert_eq!(entity.collision.health_raw, RetailRuntimeValue::Known(0));
            assert_eq!(
                entity.collision.state_flags_at_0x08.masked(DYING_STATE_BIT),
                RetailRuntimeValue::Known(DYING_STATE_BIT)
            );
            assert_eq!(
                entity
                    .collision
                    .state_flags_at_0x08
                    .masked(DEFERRED_DESTROY_STATE_WRITE_MASK),
                RetailRuntimeValue::Known(DEFERRED_DESTROY_PENDING_STATE_BIT)
            );
            let RetailRuntimeValue::Known(Some(context)) = entity.current_behavior_context else {
                panic!("class-2 context")
            };
            assert_eq!(
                context.descriptor(),
                BehaviorDescriptorIdentity::Named(&QUIET_DEATH_BEHAVIOR_PROGRAM)
            );
            assert_eq!(
                context.active_style(),
                ActiveBehaviorStyle::Audited(QUIET_DEATH_STYLE)
            );
            for slot in [
                ActorTaskSlot::Primary,
                ActorTaskSlot::Secondary,
                ActorTaskSlot::Tertiary,
            ] {
                assert!(entity.actor_task_state(slot).is_none());
            }
        }

        assert_eq!(
            manager.pending_actor_deferred_destroy_ids(),
            &(1..=actor_count as u32).collect::<Vec<_>>()
        );
        assert_eq!(
            world_fx.pending_event_count(),
            1,
            "only type 68 has a death cue"
        );
        world_fx.process_pending();
        let sounds = world_fx.take_positional_sounds();
        assert_eq!(sounds.len(), 1);
        assert_eq!(sounds[0].sound_id, 62);
        assert_eq!(
            manager.cleanup_pending_actor_deferred_destroys(),
            (1..=actor_count as u32).collect::<Vec<_>>()
        );
        assert!(manager.entities.is_empty());
    }

