    #[test]
    fn type93_main_base_death_preserves_sub_j_until_deferred_child_cascade() {
        let terrain = flat_terrain(0);
        let mut manager = exact_type17_materialiser_manager();
        manager.entities[1].set_position_raw([1_000, 0, 2_000]);
        let (proxy_id, _retained_owner) =
            materialise_exact_type17_type93_for_test(&mut manager, 2, &terrain);
        let observation = manager
            .main_base_abort_actor_observation(proxy_id)
            .expect("tail-appended Type-93 actor");

        assert_eq!(
            manager.apply_main_base_abort_type93_death(observation.lease),
            Ok(MainBaseType93DeathAdvance::Advanced {
                outcome: MainBaseType93DeathOutcome::DeferredDestroyStaged {
                    entity_id: proxy_id,
                    cargo_id: 2,
                },
                next_actor: None,
            })
        );
        let proxy = manager
            .entities
            .iter()
            .find(|entity| entity.id == proxy_id)
            .expect("class-2 leaves the proxy linked for deferred cleanup");
        assert_eq!(proxy.collision.health_raw, RetailRuntimeValue::Known(0));
        assert_eq!(
            proxy.collision.state_flags_at_0x08.masked(DYING_STATE_BIT),
            RetailRuntimeValue::Known(DYING_STATE_BIT)
        );
        let RetailRuntimeValue::Known(Some(context)) = proxy.current_behavior_context else {
            panic!("Type-93 class-2 context")
        };
        assert_eq!(
            context.descriptor(),
            BehaviorDescriptorIdentity::Named(&QUIET_DEATH_BEHAVIOR_PROGRAM)
        );
        let RetailRuntimeValue::Known(Some(sub_j)) = &proxy.sub_j_attachment_runtime else {
            panic!("class-2 must retain Type-93 Sub-J custody")
        };
        assert_eq!(sub_j.ordered_entity_ids(), [2]);
        assert_eq!(manager.entities[1].attached_to, Some(proxy_id));
        assert!(!manager.cargo_drop_proxies[0].task_active);
        assert_eq!(manager.pending_actor_deferred_destroy_ids(), [proxy_id]);

        let stable_before = manager.cargo_drop_proxies[0].stable_us;
        manager.update_cargo_drop_proxies(20_000, &terrain);
        assert_eq!(manager.cargo_drop_proxies[0].stable_us, stable_before);
        assert!(manager.cargo_proxy_events.is_empty());

        assert_eq!(
            manager.cleanup_pending_actor_deferred_destroys(),
            [proxy_id, 2],
            "the next live-list scan removes cargo which preceded its proxy"
        );
        assert_eq!(manager.retail_live_order_ids().collect::<Vec<_>>(), [1]);
        assert!(manager.cargo_drop_proxies.is_empty());
        assert!(manager.pending_actor_deferred_destroy_ids().is_empty());
        assert!(manager.cargo_proxy_events.is_empty());
    }

