    #[test]
    fn type93_native_sub_j_copies_clamped_pose_and_zeroes_velocity_for_each_purpose() {
        for purpose in [
            Type93LifecyclePurpose::PlayerCargoDrop,
            Type93LifecyclePurpose::Type17MissingRelation {
                type_default_state_flags_at_0xc0: 0,
            },
            Type93LifecyclePurpose::FactoryConvertedOutput {
                type_default_state_flags_at_0xc0: 0,
            },
        ] {
            let terrain = flat_terrain(-7);
            let mut manager = exact_type17_materialiser_manager();
            let (proxy_id, _retained_owner) =
                materialise_exact_type17_type93_for_test(&mut manager, 2, &terrain);
            manager.cargo_drop_proxies[0].purpose = purpose;
            let child = manager.entity_mut(2).unwrap();
            // This focused control uses the authenticated native constructor
            // with a live row, separately from Type-17's dying-row fixture.
            child
                .collision
                .state_flags_at_0x08
                .overwrite(DYING_STATE_BIT, 0);
            child.set_motion_raw([24_628, -633, -25_948], [11, -22, 33]);
            child.surface_lifetime_timer_ms_at_0x48 = RetailRuntimeValue::Known(91);
            let state_before = child.collision.state_flags_at_0x08;
            manager
                .entity_mut(proxy_id)
                .unwrap()
                .set_motion_raw([24_613, -1_791, -25_925], [0; 3]);
            let expected = [
                24_613,
                terrain_height_raw(&terrain, 24_613, -25_925),
                -25_925,
            ];

            manager.update_type93_materialisers_with_callbacks(
                20_000,
                &terrain,
                Type93UpdatePhase::LateTailMaterialiser,
                &mut AttachmentProjectionCallbacks,
            );

            let child = manager.entity_mut(2).unwrap();
            assert_eq!(child.position_raw(), expected);
            assert_eq!(child.velocity_raw(), [0; 3]);
            assert_eq!(child.attached_to, Some(proxy_id));
            assert_eq!(child.collision.state_flags_at_0x08, state_before);
            assert_eq!(
                child.surface_lifetime_timer_ms_at_0x48,
                RetailRuntimeValue::Known(91)
            );
            assert!(matches!(
                manager.entity_mut(proxy_id).unwrap().sub_j_attachment_runtime,
                RetailRuntimeValue::Known(ref rows) if rows.as_ref().unwrap().ordered_entity_ids() == [2]
            ));
        }
    }

    #[test]
    fn type93_native_sub_j_retirement_does_not_later_release_stale_sidecar_child() {
        for stale_kind in 0..3 {
            let terrain = flat_terrain(0);
            let mut manager = exact_type17_materialiser_manager();
            let (proxy_id, _retained_owner) =
                materialise_exact_type17_type93_for_test(&mut manager, 2, &terrain);
            manager.cargo_drop_proxies[0].purpose = Type93LifecyclePurpose::PlayerCargoDrop;
            if stale_kind == 0 {
                manager.remove_live_entity_ids(&[2]);
            } else {
                let child = manager.entity_mut(2).unwrap();
                child.collision.state_flags_at_0x08 =
                    RetailStateWord::exact(if stale_kind == 1 { DYING_STATE_BIT } else { 0 });
                child.set_motion_raw([123, 456, 789], [12, 34, 56]);
            }
            manager.take_cargo_proxy_events();
            for _ in 0..32 {
                manager.update_type93_materialisers_with_callbacks(
                    20_000,
                    &terrain,
                    Type93UpdatePhase::LateTailMaterialiser,
                    &mut AttachmentProjectionCallbacks,
                );
            }

            assert!(manager.entity_mut(proxy_id).is_none());
            assert!(manager.cargo_drop_proxies.is_empty());
            assert!(!manager
                .take_cargo_proxy_events()
                .iter()
                .any(|event| { matches!(event, CargoProxyEvent::Released { .. }) }));
            if stale_kind != 0 {
                let child = manager.entity_mut(2).unwrap();
                assert_eq!(child.attached_to, Some(proxy_id));
                assert_eq!(child.position_raw(), [123, 456, 789]);
                assert_eq!(child.velocity_raw(), [12, 34, 56]);
            }
        }
    }

    #[test]
    fn type93_native_sub_j_rejects_unproven_relation_or_descriptor() {
        for invalid_descriptor in [false, true] {
            let terrain = flat_terrain(0);
            let mut manager = exact_type17_materialiser_manager();
            let (proxy_id, _retained_owner) =
                materialise_exact_type17_type93_for_test(&mut manager, 2, &terrain);
            let child = manager.entity_mut(2).unwrap();
            child
                .collision
                .state_flags_at_0x08
                .overwrite(DYING_STATE_BIT, 0);
            child.set_motion_raw([123, 456, 789], [12, 34, 56]);
            if invalid_descriptor {
                let RetailRuntimeValue::Known(Some(descriptor)) = &mut manager.type_metadata
                    [CARGO_DROP_PROXY_ENTITY_TYPE as usize]
                    .sub_j_attachment_descriptor
                else {
                    unreachable!()
                };
                descriptor.slots[0].local_offset_raw[0] = 1;
            } else {
                manager.entity_mut(2).unwrap().attached_to = Some(1);
            }
            assert_eq!(
                manager.type93_sub_j_pose_plan(manager.cargo_drop_proxies[0]),
                Type93SubJPosePlan::Unsupported,
            );
            let mut world_fx = WorldFx::new();
            let mut scheduler =
                crate::specialized_actor_task_production::SpecializedActorTaskScheduler::new();
            let mut notifications = GameplayNotifications::new();
            let blocked = manager.update_late_tail_materialisers(LateTailMaterialiserFrame {
                elapsed_micros: 20_000,
                terrain: &terrain,
                world_fx: &mut world_fx,
                scheduler: &mut scheduler,
                notifications: &mut notifications,
                retail_tick: 0,
            });
            assert_eq!(
                blocked,
                vec![(
                    2,
                    "native Type93 Sub-J pose authority unavailable".to_owned()
                )]
            );
            let child = manager.entity_mut(2).unwrap();
            assert_eq!(child.position_raw(), [123, 456, 789]);
            assert_eq!(child.velocity_raw(), [12, 34, 56]);
            assert!(matches!(
                manager.entity_mut(proxy_id).unwrap().sub_j_attachment_runtime,
                RetailRuntimeValue::Known(ref rows) if rows.as_ref().unwrap().ordered_entity_ids() == [2]
            ));
        }
    }

