            assert_eq!(proxy_id, 3);
            manager.entities[2].collision.state_flags_at_0x08.overwrite(
                REMOTE_OWNED_STATE_BIT | DYING_STATE_BIT,
                u32::from(remote) * REMOTE_OWNED_STATE_BIT | u32::from(dying) * DYING_STATE_BIT,
            );
