    #[test]
    fn alternate_cleanup_exact_type46_51_88_topologies_are_no_ops() {
        let types = [46_u32, 51, 88];
        let level = make_level(&types);
        let mut metadata = vec![EntityTypeRuntimeMetadata::default(); 89];
        for (index, entity_type) in types.into_iter().enumerate() {
            metadata[entity_type as usize].capability_flags = if index == 1 { 0x10 } else { 1 };
            metadata[entity_type as usize].common_mover_topology =
                RetailRuntimeValue::Known(CommonMoverComponentTopology::default());
        }
        let mut manager = EntityManager::from_level_with_type_metadata(&level, &metadata, None);
        let mut effects = RecordingAlternateCleanupEffects::empty();

        for (entity_index, entity_type) in types.into_iter().enumerate() {
            let entity_id = manager.entities[entity_index].id;
            let observation = manager
                .main_base_abort_actor_observation(entity_id)
                .expect("live alternate-route actor");
            let MainBaseAbortAlternateCleanupAdvance::Advanced {
                outcome,
                next_actor,
            } = manager
                .apply_main_base_abort_alternate_cleanup(observation.lease, &mut effects)
                .expect("exact null Sub-N callback")
            else {
                panic!("linked alternate actor keeps successor custody")
            };
            assert_eq!(
                outcome,
                MainBaseAbortAlternateCleanupOutcome::ExactNoSubN {
                    entity_id,
                    entity_type,
                }
            );
            assert_eq!(
                next_actor.map(|next| next.lease.entity_id),
                manager
                    .entities
                    .get(entity_index + 1)
                    .map(|entity| entity.id)
            );
        }
        assert!(effects.publications.is_empty());
    }

    #[test]
    fn alternate_cleanup_type67_commits_timer_and_publishes_every_old_byte() {
        let source_position_raw = [0x0080, 0x0080, 0];
        let mut constructor_terrain = empty_alternate_cleanup_terrain();
        constructor_terrain.cells[GRID_SIZE].attribute = 7; // cell [1, 0]
        let objects = alternate_cleanup_terrain_objects(7, 22);
        let sub_n_runtime = alternate_cleanup_runtime(
            source_position_raw,
            true,
            Some(SubNConstructorTerrain {
                terrain: &constructor_terrain,
                terrain_objects: &objects,
            }),
        );
        let mut manager = exact_type67_alternate_cleanup_manager(sub_n_runtime);
        assert_eq!(manager.entities[0].position_raw(), source_position_raw);
        let observation = manager
            .first_main_base_abort_actor_observation()
            .expect("type-67 actor");
        assert_eq!(
            manager.main_base_abort_actor_observation(observation.lease.entity_id),
            Some(observation)
        );
        let mut effects = RecordingAlternateCleanupEffects::empty();
        let nonzero_cell = [2_u8, 1_u8];
        let nonzero_index = usize::from(nonzero_cell[0]) * GRID_SIZE + usize::from(nonzero_cell[1]);
        effects.terrain.cells[nonzero_index] = TerrainCell {
            height: 73,
            attribute: 255,
            terrain_type: 0xa5,
        };

        let MainBaseAbortAlternateCleanupAdvance::Advanced {
            outcome:
                MainBaseAbortAlternateCleanupOutcome::Applied {
                    entity_id,
                    runtime,
                    terrain_publications,
                },
            next_actor,
        } = manager
            .apply_main_base_abort_alternate_cleanup(observation.lease, &mut effects)
            .expect("exact Sub-N cleanup")
        else {
            panic!("type 67 must own Sub-N")
        };
        assert_eq!(next_actor, None);
        assert_eq!(entity_id, observation.lease.entity_id);
        assert_eq!(
            runtime.terrain_patch_present(),
            RetailRuntimeValue::Known(true)
        );
        assert_eq!(
            runtime.cleanup_timer_us(),
            crate::sub_n_runtime::MAIN_BASE_ABORT_SUB_N_TIMER_US
        );
        assert_eq!(
            runtime.anchor_raw(),
            RetailRuntimeValue::Known([0x0180, 0x0080, 0x0080])
        );
        assert_eq!(terrain_publications, 9);
        let expected_cells = [
            [1, 0],
            [1, 1],
            [1, 2],
            [2, 0],
            [2, 1],
            [2, 2],
            [3, 0],
            [3, 1],
            [3, 2],
        ];
        assert_eq!(effects.publications.len(), expected_cells.len());
        assert_eq!(
            effects
                .publications
                .iter()
                .map(|(cell, _)| *cell)
                .collect::<Vec<_>>(),
            expected_cells
        );
        assert_eq!(
            effects
                .publications
                .iter()
                .map(|(_, old_attribute)| *old_attribute)
                .collect::<Vec<_>>(),
            [0, 0, 0, 0, 255, 0, 0, 0, 0]
        );
        assert_eq!(effects.terrain.cells[nonzero_index].attribute, 0);
        assert_eq!(effects.terrain.cells[nonzero_index].height, 73);
        assert_eq!(effects.terrain.cells[nonzero_index].terrain_type, 0xa5);
    }

