    #[test]
    fn f780_type9_15040_is_lethal_and_publishes_class14() {
        let mut manager = exact_level_one_type9_wander_manager();
        let entity_id = manager
            .iter_all()
            .find(|entity| entity.entity_type == LEVEL_ONE_TYPE9_ENTITY_TYPE)
            .expect("wander fixture")
            .id;
        {
            let entity = manager.entity_mut_for_test(entity_id).unwrap();
            entity.collision.damage_profile =
                RetailRuntimeValue::Known(crate::damage::TYPE_9_DAMAGE_PROFILE);
            entity.collision.pre_health_damage_buffer_raw = RetailRuntimeValue::Known(0);
            entity.collision.generic_hit_sound_id = RetailRuntimeValue::Known(None);
            entity.collision.pair_callbacks =
                EntityPairCallbackRuntimeState::audited_local(None, RetailRuntimeValue::Unresolved);
        }
        let mut world_fx = WorldFx::new();

        let outcome = manager.apply_fun_00411250_type9_checked_damage(
            entity_id,
            crate::damage::FUN_0043F780_DAMAGE_PACKET,
            &mut world_fx,
            0,
            None,
        );

        assert!(
            matches!(
                outcome,
                Fun00411250Type9DamageOutcome::Lethal {
                    task_lease: Some(_),
                    ..
                }
            ),
            "F780 4000 vs Type-9 1500 must reach class 14: {outcome:?}"
        );
        let entity = manager
            .iter_all()
            .find(|entity| entity.id == entity_id)
            .unwrap();
        assert_eq!(entity.collision.health_raw, RetailRuntimeValue::Known(0));
        assert_eq!(
            entity.collision.state_flags_at_0x08.masked(DYING_STATE_BIT),
            RetailRuntimeValue::Known(DYING_STATE_BIT)
        );
        assert!(crate::ordinary_type9_standard_death::type9_entity_has_class14_publication(entity));
    }

