    #[test]
    fn player_sub_j_preflight_leaves_completed_child_state_unchanged_until_commit() {
        let mut manager = make_cargo_manager(1);
        let before = RetailStateWord::exact(SUB_J_LOCAL_OFFSET_STATE_BIT | 0x0604_0001);
        manager.entities[1].collision.state_flags_at_0x08 = before;

        let plan = manager.prepare_player_sub_j_append(2).unwrap();
        assert_eq!(manager.entities[1].collision.state_flags_at_0x08, before);
        assert!(player_attachment_ids(&manager).is_empty());
        assert_eq!(manager.entities[1].attached_to, None);

        assert_eq!(
            manager.commit_player_sub_j_append(plan),
            SubJAttachmentAppend::Appended
        );
        assert_eq!(player_attachment_ids(&manager), [2]);
        assert_eq!(manager.entities[1].attached_to, None);
        assert_eq!(
            manager.entities[1].collision.state_flags_at_0x08,
            RetailStateWord::exact(0x0604_0001 | SUB_J_OUTER_POLICY_STATE_BIT)
        );
    }

