    #[test]
    fn player_sub_j_append_applies_zero_slot_and_outer_policy_before_relation_link() {
        let mut manager = make_cargo_manager(1);
        manager.entities[1].collision.state_flags_at_0x08 =
            RetailStateWord::exact(SUB_J_LOCAL_OFFSET_STATE_BIT);
        assert_eq!(
            manager
                .player_sub_j_runtime()
                .expect("exact player Sub-J")
                .policy_raw_at_0x0c(),
            1
        );

        assert_eq!(
            manager.append_player_sub_j_entity(2),
            Ok(SubJAttachmentAppend::Appended)
        );
        assert_eq!(player_attachment_ids(&manager), [2]);
        assert_eq!(manager.entities[1].attached_to, None);
        assert_eq!(
            manager.entities[1]
                .collision
                .state_flags_at_0x08
                .masked(SUB_J_LOCAL_OFFSET_STATE_BIT | SUB_J_OUTER_POLICY_STATE_BIT),
            RetailRuntimeValue::Known(SUB_J_OUTER_POLICY_STATE_BIT)
        );

        manager.entities[1].collision.state_flags_at_0x08 =
            RetailStateWord::exact(SUB_J_LOCAL_OFFSET_STATE_BIT);
        assert_eq!(
            manager.append_player_sub_j_entity(2),
            Ok(SubJAttachmentAppend::AlreadyPresent)
        );
        assert_eq!(
            manager.entities[1]
                .collision
                .state_flags_at_0x08
                .masked(SUB_J_LOCAL_OFFSET_STATE_BIT | SUB_J_OUTER_POLICY_STATE_BIT),
            RetailRuntimeValue::Known(SUB_J_LOCAL_OFFSET_STATE_BIT),
            "duplicate success must not replay slot or outer-policy writes"
        );
    }

