    #[test]
    fn fresh_profile_unlocks_one_of_the_five_authored_cargo_slots() {
        let mut level = make_level(&[PLAYER_ENTITY_TYPE, WEIGHT_ENTITY_TYPE, WEIGHT_ENTITY_TYPE]);
        // Retail's cargo HUD bypasses this live Section-13 override and reads
        // the immutable type table's primary model.
        level.entities[1].model_overrides[0] = 42;
        let mut metadata =
            vec![EntityTypeRuntimeMetadata::default(); WEIGHT_ENTITY_TYPE as usize + 1];
        metadata[PLAYER_ENTITY_TYPE as usize].capability_flags = 5;
        set_player_sub_j_descriptor(&mut metadata[PLAYER_ENTITY_TYPE as usize], 5);
        metadata[WEIGHT_ENTITY_TYPE as usize].capability_flags = 0x1000;
        metadata[WEIGHT_ENTITY_TYPE as usize].model_slots[0] = 81;
        metadata[WEIGHT_ENTITY_TYPE as usize].initializer =
            exact_initializer_metadata([0; 4]).initializer;
        let mut manager = EntityManager::from_level_with_type_metadata(&level, &metadata, None);
        set_entity_position(&mut manager, 1, [10.0, 0.0, 10.0]);
        set_entity_position(&mut manager, 2, [11.0, 0.0, 10.0]);
        set_entity_position(&mut manager, 3, [12.0, 0.0, 10.0]);

        assert_eq!(manager.player_cargo_capacity(), 1);
        assert_eq!(manager.player_cargo_unlock_raw, 1);
        assert_eq!(manager.player_cargo_capacity_max(), 5);
        assert_eq!(manager.player_cargo_hud_models(), [None]);
        manager.queue_beam(BeamCommand::Collect);
        assert_eq!(
            manager.tick_beam(81_000),
            Some(BeamOutcome::Collected { entity_id: 2 })
        );
        assert_eq!(manager.player_cargo_hud_models(), [Some(81)]);
        manager.queue_beam(BeamCommand::Collect);
        assert_eq!(manager.tick_beam(81_000), Some(BeamOutcome::CargoFull));
        assert_eq!(manager.player_cargo_hud_models(), [Some(81)]);

        manager.raise_player_cargo_capacity_to(3);
        assert_eq!(manager.player_cargo_unlock_raw, 1);
        assert_eq!(manager.player_cargo_hud_models(), [Some(81)]);
        manager.set_player_cargo_unlock_raw(3);
        assert_eq!(manager.player_cargo_hud_models(), [Some(81), None, None]);
        manager.queue_beam(BeamCommand::Collect);
        assert_eq!(
            manager.tick_beam(81_000),
            Some(BeamOutcome::Collected { entity_id: 3 })
        );
        assert_eq!(
            manager.player_cargo_hud_models(),
            [Some(81), Some(81), None]
        );
        manager.raise_player_cargo_capacity_to(99);
        assert_eq!(manager.player_cargo_capacity(), 5);
    }

