    #[test]
    fn native_save_restore_reuses_level1_player_without_replacing_pair_policy() {
        let mut types = vec![17; 35];
        types[FIRST_WORLD_MAIN_BASE_SPAWN_INDEX] = MAIN_BASE_ENTITY_TYPE;
        let mut level = make_level(&types);
        level.name.clear();
        level.entities[FIRST_WORLD_MAIN_BASE_SPAWN_INDEX].pos_data_1 = [0x00, 0x50, 0x00, 0x00];
        level.entities[FIRST_WORLD_MAIN_BASE_SPAWN_INDEX].pos_data_2[..2]
            .copy_from_slice(&[0x00, 0x3C]);
        let metadata = vec![EntityTypeRuntimeMetadata::default(); PLAYER_ENTITY_TYPE as usize + 1];
        let mut manager = EntityManager::from_level_with_type_metadata(&level, &metadata, None);
        let live_order_before = manager.retail_live_order_ids().collect::<Vec<_>>();
        let player_id = manager.player().expect("Level 1 persistent player").id;
        let pair_callbacks = manager
            .player()
            .expect("Level 1 persistent player")
            .collision
            .pair_callbacks;
        assert_eq!(
            pair_callbacks,
            EntityPairCallbackRuntimeState::audited_player()
        );

        manager.restore_persistent_player_from_save(
            metadata.get(PLAYER_ENTITY_TYPE as usize),
            [11_008, 2_560, 24_576],
            [1, -2, 3],
            0x4000,
            None,
        );

        assert_eq!(
            manager.retail_live_order_ids().collect::<Vec<_>>(),
            live_order_before
        );
        let player = manager.player().expect("restored Level 1 player");
        assert_eq!(player.id, player_id);
        assert_eq!(player.position_raw(), [11_008, 2_560, 24_576]);
        assert_eq!(player.velocity_raw(), [1, -2, 3]);
        assert_eq!(player.heading_raw(), 0x4000);
        assert_eq!(player.collision.pair_callbacks, pair_callbacks);
    }

    #[test]
    fn cargo_drop_target_uses_q31_body_columns_and_strict_low_branch() {
        let terrain = flat_terrain(0);
        let mut orientation = [[0.0; 3]; 3];
        orientation[0][1] = 0.5;
        orientation[2][1] = -0.25;
        orientation[0][2] = 1.0;
        orientation[2][2] = 1.0;

        // At high altitude only +0x18/+0x20's 200-raw-unit body column
        // contributes: 0.5*200=100 and -0.25*200=-50 exactly.
        assert_eq!(
            cargo_drop_target_raw(
                raw_position_world([1_000, 1_000, 2_000]),
                orientation,
                &terrain
            ),
            [900, 0, 2_050]
        );

        // The fallback is strict: exactly 400 above ground does not apply it.
        assert_eq!(
            cargo_drop_target_raw(
                raw_position_world([1_000, 400, 2_000]),
                orientation,
                &terrain
            ),
            [900, 0, 2_050]
        );
        // At 399 it subtracts +0x24/+0x2c cumulatively. Q31 positive one is
        // 0x7fff_ffff, so its 400-unit product deliberately truncates to 399.
        assert_eq!(
            cargo_drop_target_raw(
                raw_position_world([1_000, 399, 2_000]),
                orientation,
                &terrain
            ),
            [501, 0, 1_651]
        );

        // Horizontal word arithmetic wraps rather than clamping at the seam.
        orientation[0][1] = 1.0;
        orientation[2][1] = 0.0;
        assert_eq!(
            cargo_drop_target_raw(
                raw_position_world([i16::MIN + 8, 1_000, 0]),
                orientation,
                &terrain
            )[0],
            32_577
        );
    }

    #[test]
    fn cargo_drop_terrain_sampling_matches_signed_integer_bilinear_and_seam() {
        let mut terrain = flat_terrain(0);
        set_terrain_height(&mut terrain, 5, 3, -1);
        set_terrain_height(&mut terrain, 6, 3, 3);
        set_terrain_height(&mut terrain, 5, 4, -5);
        set_terrain_height(&mut terrain, 6, 4, 1);

        // X=5.5, Z=3.25: the two signed X lerps are 32 and -64 raw;
        // the final signed Z lerp is exactly 8 raw.
        assert_eq!(terrain_height_raw(&terrain, 5 * 256 + 128, 3 * 256 + 64), 8);

        set_terrain_height(&mut terrain, 255, 0, -4);
        set_terrain_height(&mut terrain, 0, 0, 2);
        set_terrain_height(&mut terrain, 255, 1, -4);
        set_terrain_height(&mut terrain, 0, 1, 2);
        assert_eq!(terrain_height_raw(&terrain, -128, 0), -32);
    }

    #[test]
    fn cargo_drop_proxy_presents_settles_and_releases_on_strict_retail_timing() {
        let terrain = flat_terrain(0);
        let mut manager = make_cargo_manager(1);
        set_entity_position(&mut manager, 1, raw_position_world([1_000, 500, 2_000]));
        set_entity_position(&mut manager, 2, raw_position_world([1_100, 500, 2_000]));
        manager.entities[1].model_slots = [Some(310), Some(311), Some(312), Some(313)];
        manager.entities[1].model_index = Some(777);

        manager.queue_beam(BeamCommand::Collect);
        assert_eq!(
            manager.tick_beam(81_000),
            Some(BeamOutcome::Collected { entity_id: 2 })
        );
        assert_eq!(manager.retail_live_order_ids().collect::<Vec<_>>(), [1, 2]);
        assert_eq!(manager.attached_cargo_mass(), 200);
        assert_eq!(
            tick_drop_with_context(&mut manager, &terrain),
            BeamOutcome::DropStarted {
                cargo_id: 2,
                proxy_id: 3
            }
        );
        assert_eq!(
            manager.retail_live_order_ids().collect::<Vec<_>>(),
            [1, 2, 3]
        );
        assert_eq!(manager.attached_cargo_mass(), 0);

        let cargo = manager
            .entities
            .iter()
            .find(|entity| entity.id == 2)
            .unwrap();
        assert_eq!(cargo.attached_to, Some(3));
        let proxy = manager
            .entities
            .iter()
            .find(|entity| entity.id == 3)
            .unwrap();
        assert_eq!(proxy.entity_type, CARGO_DROP_PROXY_ENTITY_TYPE);
        assert_eq!(
            proxy.kind,
            EntityKind::Unknown(CARGO_DROP_PROXY_ENTITY_TYPE)
        );
        assert_eq!(proxy.heading, 0.0);
        assert_eq!(proxy.mass_raw, 1);
        assert_eq!(proxy.model_slots, [Some(310), None, Some(310), None]);
        assert_eq!(world_position_raw(proxy.position), [1_000, 1, 2_000]);
        let RetailRuntimeValue::Known(Some(proxy_runtime)) = &proxy.sub_j_attachment_runtime else {
            panic!("the Type-93 proxy must own its authored Sub-J row")
        };
        assert_eq!(proxy_runtime.authored_slot_count(), 1);
        assert_eq!(proxy_runtime.ordered_entity_ids(), [2]);
        assert_eq!(
            manager.iter().map(|entity| entity.id).collect::<Vec<_>>(),
            vec![1, 3]
        );
        assert_eq!(
            manager
                .iter_collidable()
                .map(|entity| entity.id)
                .collect::<Vec<_>>(),
            vec![1]
        );
        assert_eq!(
            manager.take_cargo_proxy_events(),
            vec![CargoProxyEvent::Spawned {
                proxy_id: 3,
                cargo_id: 2,
                target: raw_position_world([1_000, 0, 2_000]),
                sound_id: 8,
            }]
        );

        // Update #1 sees FUN_00408F00's +1 Y, emits once, resets age, then
        // clamps to terrain. Update #2 sees that clamp while the counter is odd
        // and therefore emits nothing.
        manager.update_cargo_drop_proxies(20_000, &terrain);
        assert_eq!(
            world_position_raw(manager.entities.last().unwrap().position)[1],
            0
        );
        assert_eq!(manager.cargo_drop_proxies[0].movement_counter, 1);
        assert_eq!(manager.cargo_drop_proxies[0].stable_us, 0);
        assert_eq!(
            manager.take_cargo_proxy_events(),
            vec![CargoProxyEvent::PositionChanged {
                proxy_id: 3,
                cargo_id: 2,
                position: raw_position_world([1_000, 1, 2_000]),
                particle_class: 0x33,
            }]
        );

        manager.update_cargo_drop_proxies(20_000, &terrain);
        assert!(manager.take_cargo_proxy_events().is_empty());
        assert_eq!(manager.cargo_drop_proxies[0].movement_counter, 1);
        assert_eq!(manager.cargo_drop_proxies[0].stable_us, 20_000);

        // Update #26 reaches equality (500 ms) and must not release. Update
        // #27 reaches 520 ms and takes the strict-greater deletion path.
        for _ in 0..24 {
            manager.update_cargo_drop_proxies(20_000, &terrain);
        }
        assert_eq!(manager.cargo_drop_proxies[0].stable_us, 500_000);
        assert!(manager.entities.iter().any(|entity| entity.id == 3));
        manager.update_cargo_drop_proxies(20_000, &terrain);
        assert!(!manager.entities.iter().any(|entity| entity.id == 3));
        assert!(manager.cargo_drop_proxies.is_empty());
        assert_eq!(manager.retail_live_order_ids().collect::<Vec<_>>(), [1, 2]);
        let cargo = manager
            .entities
            .iter()
            .find(|entity| entity.id == 2)
            .unwrap();
        assert_eq!(cargo.attached_to, None);
        assert_eq!(world_position_raw(cargo.position), [1_000, 0, 2_000]);
        assert_eq!(
            manager.take_cargo_proxy_events(),
            vec![CargoProxyEvent::Released {
                proxy_id: 3,
                cargo_id: 2,
                position: raw_position_world([1_000, 0, 2_000]),
            }]
        );
    }

    #[test]
    fn cargo_drop_refuses_an_unresolved_active_model_without_detaching() {
        let terrain = flat_terrain(0);
        let mut manager = make_cargo_manager(1);
        set_entity_position(&mut manager, 1, raw_position_world([1_000, 500, 2_000]));
        set_entity_position(&mut manager, 2, raw_position_world([1_100, 500, 2_000]));
        manager.queue_beam(BeamCommand::Collect);
        assert_eq!(
            manager.tick_beam(81_000),
            Some(BeamOutcome::Collected { entity_id: 2 })
        );
        manager.entities[1]
            .collision
            .state_flags_at_0x08
            .invalidate(ACTIVE_MODEL_SLOT_LOW_STATE_BIT | ACTIVE_MODEL_SLOT_HIGH_STATE_BIT);
        let next_entity_id_before = manager.next_entity_id;

        assert_eq!(
            tick_drop_with_context(&mut manager, &terrain),
            BeamOutcome::DropConstructionUnavailable
        );
        assert_eq!(player_attachment_ids(&manager), [2]);
        assert_eq!(manager.entities[1].attached_to, Some(1));
        assert_eq!(manager.next_entity_id, next_entity_id_before);
        assert!(manager.cargo_drop_proxies.is_empty());
        assert!(manager.cargo_proxy_events.is_empty());
    }

    #[test]
    fn cargo_drop_proxy_uses_even_odd_movement_counter_without_particle_cap() {
        let terrain = flat_terrain(0);
        let mut manager = make_cargo_manager(1);
        set_entity_position(&mut manager, 1, raw_position_world([1_000, 500, 2_000]));
        set_entity_position(&mut manager, 2, raw_position_world([1_100, 500, 2_000]));
        manager.queue_beam(BeamCommand::Collect);
        assert!(matches!(
            manager.tick_beam(81_000),
            Some(BeamOutcome::Collected { .. })
        ));
        assert!(matches!(
            tick_drop_with_context(&mut manager, &terrain),
            BeamOutcome::DropStarted { .. }
        ));
        manager.take_cargo_proxy_events();
        manager.update_cargo_drop_proxies(20_000, &terrain);
        manager.take_cargo_proxy_events();
        manager.update_cargo_drop_proxies(20_000, &terrain);

        // Let the odd phase exceed 100 ms, then move: no particle, velocity is
        // zeroed, and the counter advances to the next even phase.
        for _ in 0..4 {
            manager.update_cargo_drop_proxies(20_000, &terrain);
        }
        let proxy_index = manager
            .entities
            .iter()
            .position(|entity| entity.id == 3)
            .unwrap();
        manager.entities[proxy_index].position[0] += 1.0 / FIXED_SCALE;
        manager.entities[proxy_index].velocity = [3.0, 4.0, 5.0];
        manager.update_cargo_drop_proxies(20_000, &terrain);
        assert!(manager.take_cargo_proxy_events().is_empty());
        assert_eq!(manager.entities[proxy_index].velocity, [0.0; 3]);
        assert_eq!(manager.cargo_drop_proxies[0].movement_counter, 2);

        manager.entities[proxy_index].position[0] += 1.0 / FIXED_SCALE;
        manager.update_cargo_drop_proxies(20_000, &terrain);
        assert!(matches!(
            manager.take_cargo_proxy_events().as_slice(),
            [CargoProxyEvent::PositionChanged {
                particle_class: 0x33,
                ..
            }]
        ));
        assert_eq!(manager.cargo_drop_proxies[0].movement_counter, 3);
        assert_eq!(manager.cargo_drop_proxies[0].stable_us, 0);

        // Sixteen is only the timer-reset threshold. An even counter at 16
        // still increments and emits, but its existing age is retained.
        manager.cargo_drop_proxies[0].movement_counter = 16;
        manager.cargo_drop_proxies[0].stable_us = 400_000;
        manager.entities[proxy_index].position[0] += 1.0 / FIXED_SCALE;
        manager.update_cargo_drop_proxies(20_000, &terrain);
        assert!(matches!(
            manager.take_cargo_proxy_events().as_slice(),
            [CargoProxyEvent::PositionChanged { .. }]
        ));
        assert_eq!(manager.cargo_drop_proxies[0].movement_counter, 17);
        assert_eq!(manager.cargo_drop_proxies[0].stable_us, 420_000);
    }

    #[test]
    fn attached_weight_switches_hover_from_waves_to_static_terrain() {
        let terrain = TerrainGrid {
            // Keep the synthetic Section-10 header consistent with the
            // `Some(4.0)` sea level supplied below. Retail FUN_0041F470 reads
            // this header directly (`header[0] >> 8`).
            header: [4 * 65_536, 0, 0, 0, 0],
            cells: vec![
                v2k_formats::terrain::TerrainCell {
                    height: 0,
                    attribute: 0,
                    terrain_type: 0,
                };
                v2k_formats::terrain::GRID_SIZE * v2k_formats::terrain::GRID_SIZE
            ],
        };
        let mut light = make_cargo_manager(1);
        let mut heavy = make_cargo_manager(1);
        for manager in [&mut light, &mut heavy] {
            set_entity_position(manager, 1, [10.0, 2.0, 10.0]);
            set_entity_position(manager, 2, [11.0, 2.0, 10.0]);
        }

        heavy.queue_beam(BeamCommand::Collect);
        assert_eq!(
            heavy.tick_beam(81_000),
            Some(BeamOutcome::Collected { entity_id: 2 })
        );
        let heavy_mass = heavy.attached_cargo_mass();
        assert_eq!(heavy_mass, 200);

        light.update(PlayerUpdateRequest {
            sea_level: Some(4.0),
            frame: VehicleFrameForces::Hover(HoverFrameForces::default()),
            ..player_update_request(&terrain, idle_vtol_frame())
        });
        heavy.update(PlayerUpdateRequest {
            sea_level: Some(4.0),
            attached_cargo_mass: heavy_mass,
            frame: VehicleFrameForces::Hover(HoverFrameForces::default()),
            ..player_update_request(&terrain, idle_vtol_frame())
        });
        assert!(light.player().unwrap().velocity[1] >= 0.0);
        assert!(heavy.player().unwrap().velocity[1] < 0.0);
    }

