    #[test]
    fn terrain_type_and_explicit_slot_changes_share_one_authoritative_selector() {
        let level = make_level(&[69]);
        let mut metadata = vec![EntityTypeRuntimeMetadata::default(); 70];
        metadata[69] = exact_initializer_metadata([10, 11, 12, 13]);

        let mut terrain = flat_terrain(0);
        terrain.cells[0].attribute = 0xff;
        terrain.cells[0].terrain_type = 0x10;
        let mut manager =
            EntityManager::from_level_with_type_metadata(&level, &metadata, Some(&terrain));
        let entity = &mut manager.entities[0];
        assert_eq!(
            entity.collision.active_model_slot(),
            RetailRuntimeValue::Known(2)
        );
        assert_eq!(entity.model_index, Some(12));
        assert_eq!(
            entity.collision.state_flags_at_0x08.known_mask(),
            !CONSTRUCTOR_SURFACE_STATE_MASK
        );

        for (slot, model) in [10, 11, 12, 13].into_iter().enumerate() {
            assert_eq!(entity.select_active_model_slot(slot), Some(model));
            assert_eq!(
                entity.collision.active_model_slot(),
                RetailRuntimeValue::Known(slot)
            );
            assert_eq!(entity.model_index, Some(model));
        }

        terrain.cells[0].terrain_type = 0;
        let attribute_only =
            EntityManager::from_level_with_type_metadata(&level, &metadata, Some(&terrain));
        assert_eq!(
            attribute_only.entities[0].collision.active_model_slot(),
            RetailRuntimeValue::Known(0),
            "the decompiler's attribute expression reduces to terrain_type bit 0x10"
        );
        assert_eq!(attribute_only.entities[0].model_index, Some(10));
    }

