    #[test]
    fn common_underwater_signed_damping_and_velocity_cap_match_msvc_shifts() {
        let mut signed = [1000, 1600, -1000];
        apply_common_gravity_and_underwater_raw(
            &mut signed,
            20_000,
            underwater_frame(-400, 100, 0),
        );
        // Gravity leaves +1571, above the strict +0x600 lift cap. Arithmetic
        // right shift damps +1000 by 9 but -1000 by -10.
        assert_eq!(signed, [991, 1557, -990]);

        let mut disabled = [1000, 0, -1000];
        let mut frame = underwater_frame(-800, 100, 0);
        frame.effective_environment_flags = ENVIRONMENT_GRAVITY_DISABLE_FLAG;
        apply_common_gravity_and_underwater_raw(&mut disabled, 20_000, frame);
        assert_eq!(disabled, [1000, 0, -1000]);
    }

