    #[test]
    fn vtol_surface_emitter_uses_pre_near_lift_and_suppresses_zero_lift() {
        let level = make_level(&[PLAYER_ENTITY_TYPE]);
        let mut masses = vec![0; PLAYER_ENTITY_TYPE as usize + 1];
        masses[PLAYER_ENTITY_TYPE as usize] = 100;
        let mut manager = EntityManager::from_level_with_type_masses(&level, &[], &masses, None);
        let player = manager.player_mut().unwrap();
        let player_id = player.id;
        player.set_motion_raw([0x100, 0, -0x100], [7, 0, -9]);
        let terrain = flat_terrain(0);
        let frame = match vtol_frame(0, true) {
            VehicleFrameForces::Vtol(frame) => frame,
            VehicleFrameForces::Hover(_) | VehicleFrameForces::DyingCommon => unreachable!(),
        };

        // At zero clearance the powered VTOL controller contributes altitude
        // assist even with neutral throttle. That pre-near value, rather than
        // the later boosted/attenuated lift, controls the emitter.
        let outcome = manager.update(player_update_request(
            &terrain,
            VehicleFrameForces::Vtol(frame),
        ));
        let emission = outcome.surface_effect.expect("altitude assist emits");
        assert_eq!(emission.position_raw, [0x100, 0, -0x100]);
        assert_eq!(emission.velocity_raw, [7, 0, -9]);
        assert_eq!(emission.lateral_q31, frame.previous_basis.lateral);
        assert_eq!(emission.up_q31, frame.previous_basis.up);
        assert_eq!(emission.forward_q31, frame.previous_basis.forward);
        assert_eq!(emission.owner_entity_id, player_id);
        assert_eq!(
            emission.strength_raw,
            vtol_surface_effect_strength_raw(24, 20_000)
        );

        let no_fuel = manager.update(player_update_request(&terrain, idle_vtol_frame()));
        assert_eq!(no_fuel.surface_effect, None);
    }

