    #[test]
    fn pre_water_contact_observes_integrated_motion_and_drives_water_classification() {
        let level = make_level(&[PLAYER_ENTITY_TYPE]);
        let mut masses = vec![0; PLAYER_ENTITY_TYPE as usize + 1];
        masses[PLAYER_ENTITY_TYPE as usize] = 100;
        let mut manager = EntityManager::from_level_with_type_masses(&level, &[], &masses, None);
        let player_id = manager.player().unwrap().id;
        let initial_position_raw = [0, 0x100, 0];
        let player = manager.player_mut().unwrap();
        player.set_motion_raw(initial_position_raw, [0, -0x100, 0]);
        player
            .collision
            .state_flags_at_0x08
            .overwrite(SURFACE_STATE_MASK, FULLY_ABOVE_SURFACE_STATE_BIT);
        let terrain = flat_terrain(-128);

        let corrected_position_raw = [0, -0x100, 0];
        let corrected_velocity_raw = [0, -1001, 0];
        let (outcome, integrated_position_raw) = manager.update_with_player_surface_contacts(
            PlayerUpdateRequest {
                sea_level: Some(0.0),
                active_model_collision_radius_raw: 10,
                ..player_update_request(&terrain, idle_vtol_frame())
            },
            true,
            |manager, phase| match phase {
                PlayerSurfaceContactPhase::Terrain => {
                    let player = manager.player_mut().unwrap();
                    let integrated_position_raw = player.position_raw();
                    player.set_motion_raw(corrected_position_raw, corrected_velocity_raw);
                    PlayerSurfaceContactDispatch::Terrain(integrated_position_raw)
                }
                PlayerSurfaceContactPhase::Water { .. } => {
                    PlayerSurfaceContactDispatch::WaterComplete
                }
            },
        );

        let integrated_position_raw = integrated_position_raw.expect("player hook ran");
        assert!(
            integrated_position_raw[1] < initial_position_raw[1],
            "the contact hook must observe common-force integration, not the frame-start pose"
        );
        assert_eq!(
            outcome.water_entry,
            Some(PlayerWaterEntry {
                position_raw: corrected_position_raw,
                surface_y_raw: 0,
                owner_entity_id: player_id,
                response: PlayerWaterEntryResponse::HardImpact { severe: false },
            }),
            "whole-body water classification must consume the hook-corrected position and velocity"
        );
        let commit = outcome
            .hard_water_entry_commit
            .expect("the hard branch returns its ordered constructor suffix");
        assert_eq!(commit.actor().entity_id, player_id);
        assert_eq!(commit.body_position_raw(), corrected_position_raw);
        assert_eq!(commit.ring_position_raw(), [0, 0, 0]);
        assert_eq!(commit.vertical_velocity_after_raw(), -501);

        let player = manager.player().unwrap();
        assert_eq!(player.position_raw(), corrected_position_raw);
        assert_eq!(
            player.velocity_raw(),
            corrected_velocity_raw,
            "hard damping remains deferred until the constructor and sound owners are supplied"
        );
        assert_eq!(
            player
                .collision
                .state_flags_at_0x08
                .masked(SURFACE_STATE_MASK),
            RetailRuntimeValue::Known(FULLY_BELOW_SURFACE_STATE_BIT)
        );
    }

    #[test]
    fn pre_water_contact_runs_once_only_when_the_player_exists() {
        let terrain = flat_terrain(-128);
        let mut player_manager =
            EntityManager::from_level(&make_level(&[PLAYER_ENTITY_TYPE]), &[], None);
        let mut player_calls = 0;
        let (_, player_result) = player_manager.update_with_player_surface_contacts(
            player_update_request(&terrain, idle_vtol_frame()),
            true,
            |_, phase| match phase {
                PlayerSurfaceContactPhase::Terrain => {
                    player_calls += 1;
                    PlayerSurfaceContactDispatch::Terrain(0x46_u8)
                }
                PlayerSurfaceContactPhase::Water { .. } => {
                    PlayerSurfaceContactDispatch::WaterComplete
                }
            },
        );
        assert_eq!(player_calls, 1);
        assert_eq!(player_result, Some(0x46));

        let mut no_player_manager = EntityManager::from_level(&make_level(&[1]), &[], None);
        let mut absent_calls = 0;
        let (_, absent_result) = no_player_manager.update_with_player_surface_contacts(
            player_update_request(&terrain, idle_vtol_frame()),
            true,
            |_, phase| match phase {
                PlayerSurfaceContactPhase::Terrain => {
                    absent_calls += 1;
                    PlayerSurfaceContactDispatch::Terrain(0x46_u8)
                }
                PlayerSurfaceContactPhase::Water { .. } => {
                    PlayerSurfaceContactDispatch::WaterComplete
                }
            },
        );
        assert_eq!(absent_calls, 0);
        assert_eq!(absent_result, None);
    }

